    if(dv<.35){g+=half(-s/2,s);if(dv>0)g+=`<path d="M0 ${f1(-w/2)}v${f1(w*.3*dv/.35)}M0 ${f1(w/2)}v${f1(-w*.3*dv/.35)}" style="stroke:var(--pathogen-dark);stroke-width:${f1(s*.06)}"/>`}
