    const PN=N?[{x:56,y:40,w:300,h:150},{x:56,y:290,w:300,h:150},{x:96,y:540,w:260,h:160}]:[{x:56,y:44,w:170,h:170},{x:300,y:44,w:160,h:170},{x:578,y:44,w:120,h:170}];
