/* ===== 1.3 Vessels, clotting & failing organs ===== */
/* (1) a vessel, a capillary bed, a lactate tube and six organ systems through seven phases;
   (2) a teaching calculator for the SIC and ISTH overt DIC scores, quoted as published (Iba 2017; Taylor 2001 via Iba 2023).
   Uses whCoag() from 11-what.js for the clotting-system icon. */
const EN_T=(x,y,txt,c='t-xs',st='')=>`<text x="${f1(x)}" y="${f1(y)}" class="${c}"${st?` style="${st}"`:''}>${txt}</text>`;
const EN_TH=(x,y,txt,c='t-xs t-mid',col='var(--ink)')=>EN_T(x,y,txt,c,`fill:${col};font-weight:700;paint-order:stroke;stroke:var(--panel);stroke-width:3px;stroke-linejoin:round`);
const EN_PH=[
 {from:0,at:.06,k:'Phase 1 · healthy',t:'A healthy lining',
  txt:`The endothelium controls vessel tone, the barrier, inflammation and clotting. <sup class="c" data-ref="Ince2016Endothelium" title="Source 212"><a href="/sepsis-and-shock/sources/#src-Ince2016Endothelium">212</a></sup> On its inner surface the glycocalyx, a gel about 0.5–5.0 μm thick, controls permeability and tone, prevents microvascular thrombosis and regulates white-cell adhesion. <sup class="c" data-ref="Uchimido2019" title="Source 485"><a href="/sepsis-and-shock/sources/#src-Uchimido2019">485</a></sup> Every small capillary carries red cells, and the organs are perfused.`,
  pt:`The inside of every blood vessel has a thin, gel-like lining that keeps fluid in, keeps blood flowing and stops it clotting.`,
  hook:`Glycocalyx: proteoglycans (syndecan-1), glycosaminoglycans (> 50% heparan sulfate), plasma proteins. <sup class="c" data-ref="Uchimido2019" title="Source 485"><a href="/sepsis-and-shock/sources/#src-Uchimido2019">485</a></sup>`},
 {from:.14,at:.2,k:'Phase 2 · shedding',t:'The glycocalyx is shed',
  txt:`Metalloproteinases, heparanase and hyaluronidase, activated by reactive oxygen species, TNF-α and IL-1β, strip the glycocalyx. In volunteers given low-dose endotoxin, its thickness fell from 0.60 to 0.30 μm as plasma hyaluronan rose. <sup class="c" data-ref="Uchimido2019" title="Source 485"><a href="/sepsis-and-shock/sources/#src-Uchimido2019">485</a></sup> White cells start to stick to the bare wall. Shed syndecan-1 in the blood was higher in people who died. <sup class="c" data-ref="Sun2022SDC1" title="Source 465"><a href="/sepsis-and-shock/sources/#src-Sun2022SDC1">465</a></sup>`,
  pt:`Sepsis strips the protective gel away. White blood cells start to stick to the bare wall.`,
  hook:`Endotoxin halved glycocalyx thickness in volunteers (0.60 → 0.30 μm). <sup class="c" data-ref="Uchimido2019" title="Source 485"><a href="/sepsis-and-shock/sources/#src-Uchimido2019">485</a></sup>`},
 {from:.28,at:.34,k:'Phase 3 · leak and dilation',t:'Gaps open, vessels relax',
  txt:`Proteases make endothelial cells internalise VE-cadherin and lose tight junctions; leaky capillaries lose protein and plasma into the tissues, causing oedema. Diffuse vasodilation causes distributive shock, in which blood pressure may not recover with fluids alone. <sup class="c" data-ref="Hotchkiss2016NRDP" title="Source 201"><a href="/sepsis-and-shock/sources/#src-Hotchkiss2016NRDP">201</a></sup> Vasoplegia is classically attributed to nitric oxide, ATP-sensitive potassium channels and relative vasopressin deficiency. <sup class="c" data-ref="Landry2001" title="Source 250"><a href="/sepsis-and-shock/sources/#src-Landry2001">250</a></sup>`,
  pt:`Gaps open between the cells of the lining, so fluid leaks out and tissues swell. Vessels also go slack, so blood pressure falls.`,
  hook:`Vasoplegia: NO, K-ATP channels, relative vasopressin deficiency. <sup class="c" data-ref="Landry2001" title="Source 250"><a href="/sepsis-and-shock/sources/#src-Landry2001">250</a></sup>`},
 {from:.42,at:.48,k:'Phase 4 · microclots',t:'Microclots form',
  txt:`Tissue factor on monocytes and endothelial cells starts thrombin generation; the protein C system is impaired and fibrinolysis is blocked by PAI-1. More fibrin and less clearance means microvascular clots. <sup class="c" data-ref="Levi2017Coag" title="Source 258"><a href="/sepsis-and-shock/sources/#src-Levi2017Coag">258</a></sup> Antithrombin and activated protein C fall, and so does endothelial heparan sulfate. <sup class="c" data-ref="Hotchkiss2016NRDP" title="Source 201"><a href="/sepsis-and-shock/sources/#src-Hotchkiss2016NRDP">201</a></sup> Platelets and clotting factors are consumed. The early stage can be scored as sepsis-induced coagulopathy (SIC). <sup class="c" data-ref="Iba2017SIC" title="Source 206"><a href="/sepsis-and-shock/sources/#src-Iba2017SIC">206</a></sup>`,
  pt:`Tiny clots form inside small vessels, while clotting factors get used up. That can cause clots and bleeding at the same time.`,
  hook:`Sepsis coagulopathy = tissue factor ↑, antithrombin and protein C ↓, PAI-1 ↑ (fibrinolysis shut-down). <sup class="c" data-ref="Levi2017Coag" title="Source 258"><a href="/sepsis-and-shock/sources/#src-Levi2017Coag">258</a></sup>`},
 {from:.56,at:.62,k:'Phase 5 · microcirculation',t:'Small vessels stop flowing',
  txt:`Under the tongue, perfused small vessels were 48% in severe sepsis vs 90% in volunteers. <sup class="c" data-ref="DeBacker2002" title="Source 112"><a href="/sepsis-and-shock/sources/#src-DeBacker2002">112</a></sup> In septic shock they improved only in survivors, and stayed low in people who later died of organ failure despite similar blood pressure. <sup class="c" data-ref="Sakr2004" title="Source 406"><a href="/sepsis-and-shock/sources/#src-Sakr2004">406</a></sup> Cells may also fail to use oxygen (cytopathic hypoxia). <span class="ev hyp">Hypothesis</span> <sup class="c" data-ref="Fink2002" title="Source 149"><a href="/sepsis-and-shock/sources/#src-Fink2002">149</a></sup> Lactate rises, though much may come from adrenaline-driven glycolysis in muscle rather than oxygen debt. <sup class="c" data-ref="Levy2005Lactate,GarciaAlvarez2014" title="Source 164,260"><a href="/sepsis-and-shock/sources/#src-Levy2005Lactate">164,260</a></sup>`,
  pt:`The tiniest vessels can stop flowing even when blood pressure looks normal. A high lactate shows someone is very ill, but it does not always mean the body is short of oxygen.`,
  hook:`Sublingual perfused small vessels: 48% in severe sepsis vs 90% in health. <sup class="c" data-ref="DeBacker2002" title="Source 112"><a href="/sepsis-and-shock/sources/#src-DeBacker2002">112</a></sup>`},
 {from:.7,at:.77,k:'Phase 6 · organs',t:'Organs fail',
  txt:`Sepsis-3 counts an acute rise in SOFA of 2 points or more across six systems. <sup class="c" data-ref="Singer2016Sepsis3,Vincent1996SOFA" title="Source 448,495"><a href="/sepsis-and-shock/sources/#src-Singer2016Sepsis3">448,495</a></sup> Lungs: ARDS. <sup class="c" data-ref="ARDS2012Berlin" title="Source 27"><a href="/sepsis-and-shock/sources/#src-ARDS2012Berlin">27</a></sup> Kidneys: septic shock was the commonest contributor to acute renal failure in ICUs (47.5%). <sup class="c" data-ref="Uchino2005" title="Source 486"><a href="/sepsis-and-shock/sources/#src-Uchino2005">486</a></sup> Brain: encephalopathy in up to 70% of people with severe systemic infection. <sup class="c" data-ref="Gofton2012" title="Source 172"><a href="/sepsis-and-shock/sources/#src-Gofton2012">172</a></sup> Heart: low ejection fraction despite normal cardiac index. <sup class="c" data-ref="Parker1984" title="Source 343"><a href="/sepsis-and-shock/sources/#src-Parker1984">343</a></sup> Liver: early dysfunction carried the highest independent mortality risk (OR 1.86). <sup class="c" data-ref="Kramer2007" title="Source 238"><a href="/sepsis-and-shock/sources/#src-Kramer2007">238</a></sup> Clotting: platelets fall. <sup class="c" data-ref="Vanderschueren2000" title="Source 489"><a href="/sepsis-and-shock/sources/#src-Vanderschueren2000">489</a></sup>`,
  pt:`The lungs, kidneys, brain, heart and liver start to struggle. Confusion, fast breathing or passing little urine can be signs. It is an emergency.`,
  hook:`SOFA's six systems: respiratory, coagulation, liver, cardiovascular, CNS, renal; 0–4 each. <sup class="c" data-ref="Vincent1996SOFA" title="Source 495"><a href="/sepsis-and-shock/sources/#src-Vincent1996SOFA">495</a></sup>`},
 {from:.85,at:.95,k:'Phase 7 · recovery',t:'Recovery in survivors',
  txt:`In survivors of septic shock, microcirculatory perfusion improved over time. <sup class="c" data-ref="Sakr2004" title="Source 406"><a href="/sepsis-and-shock/sources/#src-Sakr2004">406</a></sup> The heart's "profound but reversible" depression recovered, with ejection fraction and volumes back to normal in about 10 days. <sup class="c" data-ref="Parker1984" title="Source 343"><a href="/sepsis-and-shock/sources/#src-Parker1984">343</a></sup> Total SOFA fell in 33% of survivors staying at least a week. <sup class="c" data-ref="Vincent1998SOFA" title="Source 496"><a href="/sepsis-and-shock/sources/#src-Vincent1998SOFA">496</a></sup> Life after sepsis: <a href="#after" data-go="after">After sepsis: recovery &amp; families</a>.`,
  pt:`In people who recover, flow in the small vessels improves and the heart usually recovers within about 10 days.`,
  hook:`Septic cardiomyopathy is reversible in survivors (~10 days). <sup class="c" data-ref="Parker1984" title="Source 343"><a href="/sepsis-and-shock/sources/#src-Parker1984">343</a></sup>`}
];
const EN_ORG=[['lung','lungs',.64],['kidney','kidneys',.66],['brain','brain',.67],['heart','heart',.69],['liver','liver',.72],['coag','clotting',.5]];
inits.endothelium=()=>{
  const svg=$('#enSvg'),rg=$('#enT');let setSt=()=>{};
  function draw(t){const N=vb(svg,'720 400','400 600'),p=phaseOf(EN_PH,t),P=EN_PH[p],rec=ramp(t,.85,.98);
    const L=N?{v:[16,62,368,118],c:[16,206,262,128],m:[318,206,24,128],o:{x:[72,200,328],y:[392,486],s:36},st:[16,566,368]}
             :{v:[16,62,440,128],c:[16,224,300,120],m:[352,224,24,120],o:{x:[548,660],y:[90,180,270],s:40},st:[16,374,688]};
    const shed=ramp(t,.14,.26)*(1-rec*.75),leak=ramp(t,.28,.38)*(1-rec*.85),dil=ramp(t,.3,.4)*(1-rec),clots=.66*ramp(t,.42,.52)*(1-rec*.9),cells=ramp(t,.14,.3)*(1-rec*.8);
    const perf=1-.6*ramp(t,.5,.62)+.55*rec,lac=.18+.6*ramp(t,.52,.68)-.5*rec;
    let s=EN_T(N?16:20,26,P.t,'t-big')+EN_T(N?16:20,43,P.k,'t-sm');
    /* the vessel */
    const [vx,vy,vw,vh]=L.v,V=vessel(vx,vy,vw,vh,{ph:t*12,shed,leak,dilate:dil,clots,cells,o2:1-.5*Math.max(leak,clots),seed:11});s+=V.svg;
    s+=EN_TH(vx+vw-6,vy+12,'small blood vessel','t-xs t-end');
    if(shed<.5)s+=`<path d="M${f1(vx+vw*.3)} ${f1(vy+8)}L${f1(vx+vw*.33)} ${f1(V.at.top+2)}" style="stroke:var(--muted);stroke-width:1.2"/>`+EN_TH(vx+vw*.3,vy+8,'glycocalyx','t-xs t-mid','var(--glyco)');
    if(p===1)s+=EN_TH(vx+vw*.5,V.at.cy+4,'enzymes shed the glycocalyx','t-xs t-mid','var(--accent)');
    if(leak>.3)s+=EN_TH(vx+vw*.24,vy+vh-4,'fluid and protein leak out','t-xs t-mid','var(--fluid)')+(dil>.4?EN_TH(vx+vw*.62,V.at.cy+4,'vessel relaxes (NO)','t-xs t-mid','var(--ink)'):'');
    if(clots>.3)s+=EN_TH(vx+vw*.72,vy+vh-4,'microclots + platelets','t-xs t-mid','var(--clot)');
    /* capillary bed and lactate */
    const [cx,cy,cw,ch]=L.c,C=capbed(cx,cy,cw,ch,{perf:clamp(perf),ph:t*8,seed:3});s+=C.svg;
    s+=EN_T(cx,cy-6,`capillary bed · ${C.n} of 5 perfused (schematic)`,'t-xs','fill:var(--ink);font-weight:600');
    const [mx,my,mw,mh]=L.m;s+=lactateMeter(mx,my,mw,mh,clamp(lac)*10,10,{label:'',val:false});
    s+=EN_T(mx+mw/2,my-6,'lactate','t-xs t-mid','fill:var(--lactate);font-weight:700')+EN_T(mx+mw/2,my+mh+14,'schematic','t-xs t-mid');
    /* six organ systems */
    let nf=0;EN_ORG.forEach(([k,lab,st],i)=>{const fl=ramp(t,st,st+.08)*(1-ramp(t,.86+i*.015,.97));if(fl>.5)nf++;
      const x=N?L.o.x[i%3]:L.o.x[i%2],y=N?L.o.y[Math.floor(i/3)]:L.o.y[Math.floor(i/2)];
      s+=k==='coag'?whCoag(x,y,L.o.s,fl):organ(k,x,y,L.o.s,{fail:fl});
      s+=EN_T(x,y+L.o.s*.5+15,lab,'t-xs t-mid','fill:var(--ink);font-weight:600')+EN_T(x,y+L.o.s*.5+28,fl>.5?'failing':fl>.15?'struggling':'working','t-xs t-mid',fl>.5?'fill:var(--bad);font-weight:600':'')});
    s+=EN_T(N?16:500,N?L.o.y[0]-L.o.s*.5-14:44,'organ systems (as in SOFA)','t-xs','fill:var(--ink);font-weight:700;letter-spacing:.06em');
    /* phase strip */
    const [sx,sy,sw]=L.st,w=sw/EN_PH.length,KS=['healthy','shed','leak','clots','flow','organs','recover'];
    EN_PH.forEach((q,i)=>{const on=i===p,x=sx+i*w;s+=`<rect x="${f1(x+1)}" y="${sy}" width="${f1(w-2)}" height="6" rx="3" style="fill:${on?(i===6?'var(--good)':'var(--brand)'):'var(--panel-2)'}"/>`+EN_T(x+w/2,sy+19,KS[i],'t-xs t-mid',on?'fill:var(--ink);font-weight:600':'')});
    s+=`<circle cx="${f1(sx+sw*t)}" cy="${sy+3}" r="5.5" style="fill:var(--ink);stroke:var(--panel);stroke-width:2"/>`;
    svg.innerHTML=s;setSt(p);
    $('#enRead').innerHTML=`<span>glycocalyx <b>${shed<.2?'intact':shed<.7?'thinning':'shed'}</b></span><span>capillaries perfused <b>${C.n} of 5</b> (schematic)</span><span>organ systems failing <b>${nf} of 6</b></span>`;
    $('#enNote').innerHTML=noteHTML(P)}
  const stop=playWire(rg,$('#enPlay'),draw,24000,'Replay','endothelium');
  setSt=stepWire($('#enSteps'),EN_PH,rg,draw,stop);draw(+rg.value);

  /* ---------- SIC and ISTH overt DIC teaching calculator ---------- */
  const ids=['enPlt','enInr','enSofa','enPt','enFib','enFbg'],v=id=>parseFloat($('#'+id).value);
  function calc(){const plt=v('enPlt'),inr=v('enInr'),sofa=v('enSofa'),pt=v('enPt'),fib=v('enFib'),fbg=v('enFbg');
    const ok=[plt,inr,pt,fbg].every(x=>isFinite(x)&&x>=0);
    if(!ok){$('#enOut').innerHTML=`<div class="card"><p>Enter a number in each box to see the published point counts.</p></div>`;return}
    const sInr=inr>1.4?2:inr>1.2?1:0,sPlt=plt<100?2:plt<150?1:0,sic=sInr+sPlt+sofa,isSic=sic>=4&&sInr+sPlt>2;
    const dPlt=plt<50?2:plt<100?1:0,dPt=pt>=6?2:pt>=3?1:0,dFbg=fbg<1?1:0,dic=dPlt+fib+dPt+dFbg,isDic=dic>=5;
    $('#enOut').innerHTML=`<div class="card"><small>SIC score (Iba 2017)</small><span class="big-num">${sic} / 6</span><p>PT-INR ${sInr} + platelets ${sPlt} + "total SOFA" ${sofa}. ${isSic?'<b>Meets the published SIC criteria</b> (total ≥ 4 and PT plus platelet points &gt; 2).':'Does not meet the published SIC criteria (total ≥ 4 and PT plus platelet points &gt; 2).'} <sup class="c" data-ref="Iba2017SIC" title="Source 206"><a href="/sepsis-and-shock/sources/#src-Iba2017SIC">206</a></sup></p></div>`+
      `<div class="card"><small>ISTH overt DIC score (2001)</small><span class="big-num">${dic} / 8</span><p>Platelets ${dPlt} + fibrin marker ${fib} + PT ${dPt} + fibrinogen ${dFbg}. ${isDic?'<b>Total ≥ 5: compatible with overt DIC</b> as published.':'Below 5: not compatible with overt DIC as published.'} <sup class="c" data-ref="Taylor2001DIC,Iba2023DIC" title="Source 208,468"><a href="/sepsis-and-shock/sources/#src-Taylor2001DIC">208,468</a></sup></p></div>`+
      `<div class="card"><small>Why both?</small><p>SIC is meant to catch an earlier, compensated stage; overt DIC a later, decompensated one. In one Sepsis-3 cohort, 56.1% met SIC and 22.6% overt DIC. Teaching only. <sup class="c" data-ref="Iba2023DIC" title="Source 208"><a href="/sepsis-and-shock/sources/#src-Iba2023DIC">208</a></sup></p></div>`}
  ids.forEach(id=>{const e=$('#'+id);e.addEventListener('input',calc);e.addEventListener('change',calc)});
  calc();
};
/* =============== 1.4 Shock and haemodynamics =============== */
/* ---- shared with 5.1 (othershock): a schematic circulation drawn as pump, pipes and tank ----
   shCircuit(x,y,w,h,o) draws, in the box, a heart (the pump) feeding an arterial pipe to a capillary bed, a
   venous pipe back to a reservoir (the tank, the blood volume) and a short return into the heart. Schematic only:
   no glyph encodes a measured value. o: {pump (0..1 strength), dim (0..1 heart muscle dims), tone (0 wide relaxed
   pipe .. 1 narrow; .5 normal), tank (0..1 level), flow (0..1.4 red-cell density), perf (0..1 capillaries open),
   leak (0..1 fluid escapes the capillary bed), bleed (0..1 drops lost from the tank), obs (0..1 obstruction),
   obsKind ('tamp' fluid round the heart, 'in' a pinched return, 'pe' a clot in the outflow), ph (cell phase),
   beat (beat phase), fail ([part,...] 'pump'|'pipes'|'tank'|'block' outlined), fv (0..1 outline opacity), id}. */
function shAlong(P,u){const L=[0];for(let i=1;i<P.length;i++)L.push(L[i-1]+Math.hypot(P[i][0]-P[i-1][0],P[i][1]-P[i-1][1]));
  const d=clamp(u)*L[L.length-1];for(let i=1;i<P.length;i++)if(d<=L[i]){const k=(d-L[i-1])/((L[i]-L[i-1])||1);return [lerp(P[i-1][0],P[i][0],k),lerp(P[i-1][1],P[i][1],k)]}
  return P[P.length-1]}
function shCircuit(x,y,w,h,o={}){
  const g=k=>o[k]==null?{pump:1,tone:.5,tank:.75,flow:1,perf:1}[k]||0:o[k];
  const pump=g('pump'),tone=g('tone'),tank=clamp(g('tank')),flow=g('flow'),perf=g('perf'),leak=clamp(g('leak')),bleed=clamp(g('bleed')),obs=clamp(g('obs')),dim=clamp(g('dim'));
  const kind=o.obsKind||'tamp',ph=o.ph||0,beat=o.beat||0,id=o.id||'shc',fail=o.fail||[],fv=o.fv==null?1:o.fv,k=Math.min(1.1,w/430);
  const s=Math.min(w*.21,h*.33),Px=x+w*.2,Py=y+h*.36;
  const bx=x+w*.62,by=y+h*.17,bw=w*.34,bh=h*.48;
  const tx=x+w*.05,ty=y+h*.64,tw=w*.3,th=h*.22;
  const A=[[Px+s*.18,Py-s*.34],[Px+s*.18,y+h*.06],[bx+bw*.12,y+h*.06],[bx+bw*.12,by+6]];
  const V=[[bx+bw*.88,by+bh-6],[bx+bw*.88,y+h*.78],[tx+tw,y+h*.78]];
  const R=[[tx+tw*.5,ty],[tx+tw*.5,Py+s*.36]];
  const aw=lerp(21,6,clamp(tone))*k,vw=11*k;
  const pipe=(P,wd,col)=>`<path d="${ptsD(P)}" style="fill:none;stroke:var(--wall);stroke-width:${f1(wd+4)};stroke-linejoin:round;stroke-linecap:round"/><path d="${ptsD(P)}" style="fill:none;stroke:${col};stroke-width:${f1(wd)};stroke-linejoin:round;stroke-linecap:round"/>`;
  let sv=`<defs>${marker(id+'A','var(--muted)',6)}</defs>`;
  /* the tank: a reservoir whose level is the blood volume */
  sv+=`<rect x="${f1(tx)}" y="${f1(ty)}" width="${f1(tw)}" height="${f1(th)}" rx="7" style="fill:var(--panel);stroke:var(--muted);stroke-width:1.4"/>`;
  const lv=th*.9*tank;if(lv>.5)sv+=`<rect x="${f1(tx+2)}" y="${f1(ty+th-2-lv)}" width="${f1(tw-4)}" height="${f1(lv)}" rx="5" style="fill:var(--deoxy);opacity:.5"/>`;
  sv+=`<text x="${f1(tx+tw/2)}" y="${f1(ty+12)}" class="t-xs t-mid" style="fill:var(--ink);font-weight:600">TANK · blood volume</text>`;
  /* pipes */
  sv+=pipe(V,vw,'var(--blood-soft)')+pipe(R,vw,'var(--blood-soft)')+pipe(A,aw,'var(--blood-soft)');
  sv+=`<path d="M${f1(lerp(A[1][0],A[2][0],.42))} ${f1(A[1][1])}h${f1(24*k)}" style="stroke:var(--muted);stroke-width:1.3" marker-end="url(#${id}A)"/>`;
  sv+=`<path d="M${f1(lerp(V[1][0],V[2][0],.4))} ${f1(V[1][1])}h${f1(-24*k)}" style="stroke:var(--muted);stroke-width:1.3" marker-end="url(#${id}A)"/>`;
  /* red cells: oxygenated going out, deoxygenated coming back; density follows flow */
  const na=Math.round(3+7*clamp(flow,0,1.4)),VR=V.concat(R.slice());
  for(let i=0;i<na;i++){const u=(i/na+ph*.3)%1,p=shAlong(A,u);sv+=`<ellipse cx="${f1(p[0])}" cy="${f1(p[1])}" rx="${f1(Math.min(5,aw*.32))}" ry="${f1(Math.min(2.8,aw*.2))}" style="fill:var(--oxy)"/>`;
    const q=shAlong(V,u);sv+=`<ellipse cx="${f1(q[0])}" cy="${f1(q[1])}" rx="3.6" ry="2.2" style="fill:var(--deoxy)"/>`;
    if(i%2===0){const r2=shAlong(R,u);sv+=`<ellipse cx="${f1(r2[0])}" cy="${f1(r2[1])}" rx="2.2" ry="3.4" style="fill:var(--deoxy)"/>`}}
  /* the capillary bed (from the kit), with fluid leaking out as the lining fails */
  sv+=capbed(bx,by,bw,bh,{perf,ph:ph*.6,seed:7}).svg;
  sv+=`<text x="${f1(bx+bw*.56)}" y="${f1(by-6)}" class="t-xs t-mid" style="fill:var(--ink);font-weight:600">PIPES · vessels</text>`;
  if(leak>.02)for(let i=0;i<6;i++){const kk=(ph*1.4+i*.19)%1,dx=bx+bw*(.2+.12*i),dy=by+bh+4+kk*h*.05;
    sv+=`<path d="M${f1(dx)} ${f1(dy-3)}C${f1(dx+2.4)} ${f1(dy)} ${f1(dx+1.8)} ${f1(dy+2.6)} ${f1(dx)} ${f1(dy+2.6)}C${f1(dx-1.8)} ${f1(dy+2.6)} ${f1(dx-2.4)} ${f1(dy)} ${f1(dx)} ${f1(dy-3)}Z" style="fill:var(--fluid);opacity:${f1(leak*(1-kk*.7))}"/>`}
  if(leak>.3)sv+=`<text x="${f1(bx-6)}" y="${f1(by+bh+h*.06)}" class="t-xs t-end" style="fill:var(--fluid);font-weight:600;opacity:${f1(ramp(leak,.3,.6))}">fluid leaks out</text>`;
  /* blood lost from the tank */
  if(bleed>.02){for(let i=0;i<3;i++){const kk=(ph*1.2+i/3)%1,dx=tx+tw*(.22+i*.08),dy=ty+th+3+kk*h*.09;
      sv+=`<circle cx="${f1(dx)}" cy="${f1(dy)}" r="${f1(2.6*k+.6)}" style="fill:var(--oxy);opacity:${f1(bleed*(1-kk*.6))}"/>`}
    sv+=`<text x="${f1(tx+tw*.5)}" y="${f1(y+h*.985)}" class="t-xs" style="fill:var(--oxy);font-weight:600;opacity:${f1(bleed)}">blood or fluid lost</text>`}
  /* obstruction */
  if(obs>.02){if(kind==='in'){const m=shAlong(R,.45);sv+=`<path d="M${f1(m[0]-vw*1.6)} ${f1(m[1]-7)}l${f1(vw*1.6*obs*.75)} 7l${f1(-vw*1.6*obs*.75)} 7Z M${f1(m[0]+vw*1.6)} ${f1(m[1]-7)}l${f1(-vw*1.6*obs*.75)} 7l${f1(vw*1.6*obs*.75)} 7Z" style="fill:var(--ink);opacity:${f1(.4+.6*obs)}"/>`}
    else if(kind==='pe'){const m=shAlong(A,.18);sv+=`<path d="${smoothPath(blobPts(aw*.55*obs+2,9,.25,4).map(p=>[p[0]+m[0],p[1]+m[1]]))}" style="fill:var(--clot);opacity:${f1(.3+.7*obs)}"/>`}}
  /* the pump: a beating heart, squeezed by fluid in tamponade */
  const sq=kind==='tamp'?obs:0,sc=(1+.06*pump*Math.sin(beat*Math.PI*2))*(1-.16*sq);
  if(sq>.02)sv+=`<circle cx="${f1(Px)}" cy="${f1(Py)}" r="${f1(s*.56)}" style="fill:var(--fluid-soft);stroke:var(--fluid);stroke-width:${f1(1+9*sq*k)};opacity:${f1(.35+.6*sq)}"/>`;
  sv+=organ('heart',Px,Py,s*sc,{fail:dim});
  sv+=`<text x="${f1(x+4)}" y="${f1(y+h*.06+4)}" class="t-xs" style="fill:var(--ink);font-weight:600">PUMP · heart</text>`;
  /* outline the failing part */
  const box=(X,Y,W,H)=>`<rect x="${f1(X)}" y="${f1(Y)}" width="${f1(W)}" height="${f1(H)}" rx="9" style="fill:none;stroke:var(--bad);stroke-width:2;stroke-dasharray:5 4;opacity:${f1(fv)}"/>`;
  fail.forEach(p=>{if(p==='pump')sv+=box(Px-s*.62,Py-s*.62,s*1.24,s*1.24);
    else if(p==='pipes')sv+=box(bx-5,by-5,bw+10,bh+10);
    else if(p==='tank')sv+=box(tx-5,ty-5,tw+10,th+10);
    else if(p==='block'){if(kind==='tamp')sv+=box(Px-s*.66,Py-s*.66,s*1.32,s*1.32);else if(kind==='in'){const m=shAlong(R,.45);sv+=box(m[0]-vw*2,m[1]-12,vw*4,24)}else{const m=shAlong(A,.18);sv+=box(m[0]-aw-4,m[1]-aw-4,aw*2+8,aw*2+8)}}});
  return {svg:sv,at:{pump:[Px,Py],s,cap:[bx,by,bw,bh],tank:[tx,ty,tw,th]}}}
/* three bedside windows on perfusion (ESICM): skin, kidneys, brain. v = {skin, kid, brain} 0..1 worse */
function shWindows(x,y,w,v){const c=w/3;let s='';
  const sx=x+c*.5-22,sy=y;
  s+=`<rect x="${f1(sx)}" y="${f1(sy)}" width="44" height="34" rx="8" style="fill:var(--skin);stroke:var(--line)"/>`;
  [[10,9,6],[28,8,5],[20,22,7],[35,24,4.5],[8,25,4]].forEach((b,i)=>{s+=`<path d="${smoothPath(blobPts(b[2],7,.3,i+3).map(p=>[p[0]+sx+b[0],p[1]+sy+b[1]]))}" style="fill:var(--mottle);opacity:${f1(clamp(v.skin)*.85)}"/>`});
  s+=`<text x="${f1(x+c*.5)}" y="${f1(y+50)}" class="t-xs t-mid" style="fill:var(--ink)">skin</text><text x="${f1(x+c*.5)}" y="${f1(y+61)}" class="t-xs t-mid">mottling</text>`;
  s+=organ('kidney',x+c*1.5,y+16,34,{fail:v.kid})+`<text x="${f1(x+c*1.5)}" y="${f1(y+50)}" class="t-xs t-mid" style="fill:var(--ink)">kidneys</text><text x="${f1(x+c*1.5)}" y="${f1(y+61)}" class="t-xs t-mid">urine</text>`;
  s+=organ('brain',x+c*2.5,y+16,34,{fail:v.brain})+`<text x="${f1(x+c*2.5)}" y="${f1(y+50)}" class="t-xs t-mid" style="fill:var(--ink)">brain</text><text x="${f1(x+c*2.5)}" y="${f1(y+61)}" class="t-xs t-mid">alertness</text>`;
  return s}
const SH_N={pump:1,tone:.5,tank:.75,flow:1,perf:1,leak:0,bleed:0,obs:0,dim:0,map:1,co:1,skin:0,kid:0,brain:0,hr:1};
const SH_STEPS=[
 {from:0,at:.09,short:'normal',fail:[],kind:'tamp',sub:'all three parts working',flow:'normal',
  st:SH_N,
  k:'Scene 1 · the circuit',t:'Pump, pipes and tank',
  txt:`Cardiac output, the blood the heart pumps each minute, equals stroke volume times heart rate. It depends on four things: heart rate, contractility, preload and afterload <sup class="c" data-ref="Vincent2008CO" title="Source 498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">498</a></sup>. Preload is "the degree of myocardial distension prior to shortening": within limits, the more the muscle is stretched, the harder it contracts (Frank–Starling). Afterload is the force the ventricles eject against, set largely by arterial pressure and vascular tone <sup class="c" data-ref="Vincent2008CO" title="Source 498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">498</a></sup>. The RUSH bedside ultrasound exam checks the same three parts, the pump, the tank and the pipes, to identify the type of shock <sup class="c" data-ref="Perera2010RUSH" title="Source 352"><a href="/sepsis-and-shock/sources/#src-Perera2010RUSH">352</a></sup>.`,
  pt:`The heart is a pump, the blood is the fluid in the tank, and the blood vessels are the pipes. Shock happens when one or more of these fails <sup class="c" data-ref="Perera2010RUSH" title="Source 352"><a href="/sepsis-and-shock/sources/#src-Perera2010RUSH">352</a></sup>.`,
  hook:`CO = HR × SV. Its four determinants: heart rate, contractility, preload and afterload <sup class="c" data-ref="Vincent2008CO" title="Source 498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">498</a></sup>.`},
 {from:1/6,at:1/6+.55/6,short:'distributive',fail:['pipes'],kind:'tamp',sub:'the pipes widen and leak',flow:'normal or high',
  st:{pump:1,tone:.02,tank:.66,flow:1.3,perf:.55,leak:.85,bleed:0,obs:0,dim:0,map:.52,co:1.22,skin:.5,kid:.55,brain:.45,hr:1.5},
  k:'Scene 2 · distributive',t:'The pipes fail',
  txt:`Distributive shock is "relative hypovolemia": the blood is still there, but widened, leaky vessels redistribute it <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>. It is the one hyperkinetic pattern of the four <sup class="c" data-ref="Cecconi2014ESICM" title="Source 85"><a href="/sepsis-and-shock/sources/#src-Cecconi2014ESICM">85</a></sup>: in sepsis, cardiac output is usually normal or high, because tachycardia and low vascular tone reduce afterload <sup class="c" data-ref="Vincent2008CO" title="Source 498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">498</a></sup>. Its subtypes are septic, anaphylactic and neurogenic shock, and Standl 2018 describes its treatment as vasoconstrictors plus fluid (quoted as published) <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>.`,
  pt:`In septic shock the blood vessels relax and leak. The heart often pumps hard, but the pressure still falls <sup class="c" data-ref="Vincent2008CO,Singer2016Sepsis3" title="Source 448,498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">448,498</a></sup>.`,
  hook:`Distributive = hyperkinetic: normal or high cardiac output with low vascular tone. Septic, anaphylactic, neurogenic <sup class="c" data-ref="Cecconi2014ESICM,Standl2018" title="Source 85,458"><a href="/sepsis-and-shock/sources/#src-Cecconi2014ESICM">85,458</a></sup>.`},
 {from:2/6,at:2/6+.55/6,short:'cardiogenic',fail:['pump'],kind:'tamp',sub:'the pump weakens',flow:'low',
  st:{pump:.35,tone:.5,tank:.8,flow:.45,perf:.5,leak:0,bleed:0,obs:0,dim:.75,map:.5,co:.45,skin:.75,kid:.6,brain:.5,hr:1},
  k:'Scene 3 · cardiogenic',t:'The pump fails',
  txt:`In cardiogenic shock, primary pump failure lowers cardiac output: a low-flow state <sup class="c" data-ref="Vincent2008CO,Cecconi2014ESICM" title="Source 85,498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">85,498</a></sup>. Standl 2018 gives criteria of a cardiac index below 1.8 L/min/m² without support (below 2.0 with drug or mechanical support) together with a systolic pressure below 90 mmHg <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>. It occurs in up to 10% of people straight after a heart attack, and opening the blocked artery is the only treatment supported by randomised trials <sup class="c" data-ref="Samsky2021" title="Source 410"><a href="/sepsis-and-shock/sources/#src-Samsky2021">410</a></sup>. The trials are in <a href="#othershock" data-go="othershock">module 5.1</a>.`,
  pt:`When heart muscle is badly damaged, for example by a heart attack, it cannot pump enough blood round the body, so the organs go short <sup class="c" data-ref="Samsky2021" title="Source 410"><a href="/sepsis-and-shock/sources/#src-Samsky2021">410</a></sup>.`,
  hook:`Cardiogenic shock: cardiac index &lt;1.8 L/min/m² without support plus SBP &lt;90 mmHg <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>.`},
 {from:3/6,at:3/6+.55/6,short:'hypovolaemic',fail:['tank'],kind:'tamp',sub:'the tank drains',flow:'low',
  st:{pump:1,tone:.5,tank:.14,flow:.45,perf:.5,leak:0,bleed:1,obs:0,dim:0,map:.5,co:.45,skin:.75,kid:.6,brain:.5,hr:1},
  k:'Scene 4 · hypovolaemic',t:'The tank runs low',
  txt:`Hypovolaemic shock is loss of intravascular volume <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>. Standl 2018 splits it into haemorrhagic shock, traumatic haemorrhagic shock (bleeding plus tissue injury), hypovolaemic shock in the narrow sense (plasma loss without bleeding, as in persistent vomiting and diarrhoea such as cholera, or hyperthermia) and traumatic hypovolaemic shock such as large burns <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>. Venous return equals cardiac output, so with less blood coming back the heart has less to pump: a low-flow state <sup class="c" data-ref="Vincent2008CO,Cecconi2014ESICM" title="Source 85,498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">85,498</a></sup>. Standl 2018 says it is treated by fluid replacement with balanced crystalloids (quoted as published) <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>.`,
  pt:`If the body loses a lot of blood or fluid, from bleeding, severe vomiting and diarrhoea, or burns, there is not enough left for the heart to pump round <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>.`,
  hook:`Four hypovolaemic subtypes: haemorrhagic, traumatic haemorrhagic, hypovolaemic in the narrow sense, traumatic hypovolaemic (burns) <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>.`},
 {from:4/6,at:4/6+.55/6,short:'obstructive',fail:['block'],kind:'tamp',sub:'fluid squeezes the heart',flow:'low',
  st:{pump:.8,tone:.5,tank:.78,flow:.4,perf:.45,leak:0,bleed:0,obs:1,dim:0,map:.45,co:.4,skin:.75,kid:.6,brain:.55,hr:1},
  k:'Scene 5 · obstructive',t:'Something blocks the flow',
  txt:`In obstructive shock, hypoperfusion comes from raised resistance or a blockage of flow <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>. Vena cava compression, tension pneumothorax and pericardial tamponade (shown: fluid squeezing the heart) reduce filling; pulmonary embolism or a mediastinal mass raise the load on the right ventricle <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>. It is likely the rarest type, 1–2% of shock in Standl's table, and Standl 2018 says it "shall be treated with an immediate life-saving intervention" <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>.`,
  pt:`Sometimes the heart and blood are fine but something is in the way, such as fluid squeezing the heart, trapped air pressing on it, or a large clot in the lungs. The blockage has to be relieved quickly <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>.`,
  hook:`Obstructive: tamponade, tension pneumothorax, vena cava compression (low preload); pulmonary embolism (high RV afterload) <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>.`},
 {from:5/6,at:5/6+.55/6,short:'mixed',fail:['pipes','pump'],kind:'tamp',sub:'wide, leaky pipes and a tired pump',flow:'often normal',
  st:{pump:.6,tone:.05,tank:.45,flow:.85,perf:.45,leak:.85,bleed:0,obs:0,dim:.4,map:.45,co:.9,skin:.65,kid:.65,brain:.55,hr:1.4},
  k:'Scene 6 · mixed',t:'Septic shock is often mixed',
  txt:`"Shock can be due to a combination of processes" <sup class="c" data-ref="Cecconi2014ESICM" title="Source 85"><a href="/sepsis-and-shock/sources/#src-Cecconi2014ESICM">85</a></sup>, and Standl 2018 calls septic shock "a mixed form of a variety of pathologies" <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>. The vessels widen and leak, and the heart muscle can be depressed too: in 20 people with septic shock, all had a normal or high cardiac index, yet 10 had an ejection fraction below 0.40, which returned to normal in survivors within about 10 days <sup class="c" data-ref="Parker1984" title="Source 343"><a href="/sepsis-and-shock/sources/#src-Parker1984">343</a></sup>. Sepsis-3 identifies septic shock by a vasopressor requirement to keep MAP at 65 mmHg or more with lactate above 2 mmol/L despite adequate fluids, with hospital mortality above 40%, a population figure <sup class="c" data-ref="Singer2016Sepsis3" title="Source 448"><a href="/sepsis-and-shock/sources/#src-Singer2016Sepsis3">448</a></sup>.`,
  pt:`In septic shock several things go wrong at once: the vessels relax and leak, and the heart can tire for a while. In many people the heart recovers over days <sup class="c" data-ref="Standl2018,Parker1984" title="Source 343,458"><a href="/sepsis-and-shock/sources/#src-Standl2018">343,458</a></sup>.`,
  hook:`Sepsis-3 septic shock: a vasopressor for MAP ≥65 mmHg plus lactate &gt;2 mmol/L without hypovolaemia; hospital mortality &gt;40% <sup class="c" data-ref="Singer2016Sepsis3" title="Source 448"><a href="/sepsis-and-shock/sources/#src-Singer2016Sepsis3">448</a></sup>.`}
];
function shMix(a,b,k){const o={};for(const q in a)o[q]=lerp(a[q],b[q]==null?a[q]:b[q],k);return o}
/* shock types by source: Cecconi 2014 (SOAP II split) and Standl 2018 table 1 */
const SH_FQ={
 soap:{rows:[['Septic (distributive)',62],['Cardiogenic',17],['Hypovolaemic',16],['Other types (remainder)',5]],
  cap:`SOAP II enrolled 1679 intensive care patients with shock in Europe (2003–2007): septic shock 62%, cardiogenic 17% and hypovolaemic 16% <sup class="c" data-ref="Cecconi2014ESICM" title="Source 85"><a href="/sepsis-and-shock/sources/#src-Cecconi2014ESICM">85</a></sup>; the trial report gives the counts as 1044, 280 and 263 <sup class="c" data-ref="DeBacker2010SOAPII" title="Source 113"><a href="/sepsis-and-shock/sources/#src-DeBacker2010SOAPII">113</a></sup>. The last bar is simply what is left over (5%), not a reported category.`},
 pub:{rows:[['Distributive',66],['Cardiogenic',16],['Hypovolaemic',16],['Obstructive',2]],
  cap:`Standl 2018 tabulates the share of each type from published figures: distributive 66%, hypovolaemic 16%, cardiogenic 16% and obstructive 2%. Obstructive shock is likely the rarest type <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>.`},
 calc:{rows:[['Distributive',59],['Cardiogenic',13],['Hypovolaemic',27],['Obstructive',1]],
  cap:`Standl 2018 also gives the authors' own calculation: distributive 59%, hypovolaemic 27%, cardiogenic 13% and obstructive 1% <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>. Shares depend on the setting: an ICU trial sees more septic shock, while a trauma centre sees more bleeding.`}
};
inits.shock=()=>{
  /* ---------- main: the circuit through six scenes ---------- */
  const svg=$('#shSvg'),rg=$('#shT'),note=$('#shNote'),rd=$('#shRead');
  let setSt=()=>{};
  function param(t){const i=Math.min(5,Math.floor(t*6)),u=t*6-i;
    const k=i===0?0:i===5?ease(ramp(u,0,.3)):ease(ramp(u,0,.3))*(1-ease(ramp(u,.86,1)));
    return {i,k,P:shMix(SH_N,SH_STEPS[i].st,k)}}
  function draw(t){const N=vb(svg,'720 390','400 620'),{i,k,P}=param(t),S=SH_STEPS[i];
    const L=N?{hx:14,hy:24,cx:10,cy:52,cw:380,ch:270,gx:96,gy:408,gr:46,fx:190,fy:360,fw:196,wx:10,wy:480,ww:380,px:12,py:582,pw:376}
             :{hx:16,hy:26,cx:10,cy:46,cw:450,ch:290,gx:590,gy:110,gr:54,fx:486,fy:166,fw:216,wx:474,wy:250,ww:236,px:16,py:352,pw:688};
    let s=`<text x="${L.hx}" y="${L.hy}" class="t-big" style="fill:${i?'var(--brand)':'var(--ink)'}">${S.t}</text><text x="${L.hx}" y="${L.hy+16}" class="t-sm">${S.sub}</text>`;
    s+=shCircuit(L.cx,L.cy,L.cw,L.ch,{...P,obsKind:S.kind,ph:t*30,beat:t*110*P.hr,fail:S.fail,fv:k,id:'shM'}).svg;
    /* pressure dial (schematic) */
    s+=gauge(L.gx,L.gy,L.gr,P.map*100,130,{ticks:false,bands:[{to:45,col:'var(--bad)'},{to:75,col:'var(--warn)'},{to:130,col:'var(--good)'}]});
    s+=`<text x="${L.gx}" y="${L.gy+30}" class="t-sm t-mid" style="fill:var(--ink);font-weight:600">blood pressure</text><text x="${L.gx-L.gr}" y="${L.gy+14}" class="t-xs t-mid">low</text><text x="${L.gx+L.gr}" y="${L.gy+14}" class="t-xs t-mid">normal</text>`;
    /* flow bar (schematic cardiac output) */
    const fw=L.fw,fx=L.fx,fy=L.fy,u0=1/1.4;
    s+=`<text x="${fx}" y="${fy}" class="t-sm" style="fill:var(--ink);font-weight:600">flow (cardiac output)</text>`;
    s+=`<rect x="${fx}" y="${fy+7}" width="${fw}" height="12" rx="4" style="fill:var(--panel-2)"/><rect x="${fx}" y="${fy+7}" width="${f1(fw*clamp(P.co/1.4))}" height="12" rx="4" style="fill:${P.co<.7?'var(--bad)':'var(--rx)'};opacity:.8"/>`;
    s+=`<line x1="${f1(fx+fw*u0)}" x2="${f1(fx+fw*u0)}" y1="${fy+3}" y2="${fy+23}" style="stroke:var(--ink);stroke-width:1.4"/><text x="${f1(fx+fw*u0)}" y="${fy+34}" class="t-xs t-mid">usual</text>`;
    s+=`<text x="${fx}" y="${fy+48}" class="t-xs">${N?'':'pattern: '}${i===0?'normal':i===1||i===5?'hyperkinetic (distributive)':'low flow'}</text>`;
    /* the three windows */
    s+=`<text x="${L.wx+L.ww/2}" y="${L.wy-10}" class="t-sm t-mid" style="fill:var(--ink);font-weight:600">three windows on perfusion</text>`;
    s+=shWindows(L.wx,L.wy,L.ww,{skin:P.skin,kid:P.kid,brain:P.brain});
    /* scene strip */
    const sw=L.pw/6;SH_STEPS.forEach((q,j)=>{const on=j===i,xx=L.px+j*sw;
      s+=`<rect x="${f1(xx+1)}" y="${L.py}" width="${f1(sw-2)}" height="6" rx="3" style="fill:${on?(j?'var(--brand)':'var(--rx)'):'var(--panel-2)'}"/><text x="${f1(xx+sw/2)}" y="${L.py+20}" class="t-xs t-mid" style="${on?'fill:var(--ink);font-weight:600':''}">${N?q.short.slice(0,7)+(q.short.length>7?'.':''):q.short}</text>`});
    s+=`<circle cx="${f1(L.px+L.pw*t)}" cy="${L.py+3}" r="5.5" style="fill:var(--ink);stroke:var(--panel);stroke-width:2"/>`;
    svg.innerHTML=s;
    rd.innerHTML=`<span>Failing part <b>${i===0?'none':S.fail.map(f=>({pump:'pump',pipes:'pipes',tank:'tank',block:'blockage'}[f])).join(' + ')}</b></span><span>Flow <b>${S.flow}</b></span><span>Pressure <b>${i===0||k<.3?'holding':'falling'}</b></span>`;
    note.innerHTML=noteHTML(SH_STEPS[i]);setSt(i)}
  const stop=playWire(rg,$('#shPlay'),draw,36000,'Replay','shock');
  setSt=stepWire($('#shSteps'),SH_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---------- shock types by source ---------- */
  const fq=$('#shFq'),fqCap=$('#shFqCap');let fqCur='soap',fqVals=SH_FQ.soap.rows.map(r=>r[1]),fqStop=null;
  function drawFq(vals,key){const N=vb(fq,'720 220','400 260'),R=SH_FQ[key].rows;
    const lx=N?12:16,bx0=N?12:210,bw=N?320:440,rh=N?54:44,y0=N?26:30;let s='';
    s+=`<text x="${lx}" y="${y0-10}" class="t-xs">share of shock, %</text>`;
    R.forEach((r,j)=>{const y=y0+j*rh+(N?16:0),v=vals[j],w=bw*v/70,col=j===0?'var(--brand)':j===3?'var(--muted)':'var(--dx)';
      s+=`<text x="${N?lx:bx0-10}" y="${f1(N?y-5:y+14)}" class="t-sm${N?'':' t-end'}" style="fill:var(--ink);font-weight:600">${r[0]}</text>`;
      s+=`<rect x="${bx0}" y="${y}" width="${bw}" height="20" rx="5" style="fill:var(--panel-2)"/><rect x="${bx0}" y="${y}" width="${f1(Math.max(0,w))}" height="20" rx="5" style="fill:${col};opacity:${key==='soap'&&j===3?.45:.85}"/>`;
      s+=`<text x="${f1(bx0+Math.max(0,w)+8)}" y="${y+15}" class="t-sm" style="fill:var(--ink);font-weight:700">${Math.round(v)}%</text>`});
    fq.innerHTML=s}
  function setFq(key){if(fqStop)fqStop();const from=fqVals.slice(),to=SH_FQ[key].rows.map(r=>r[1]);fqCur=key;
    $$('[data-fq]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.fq===key));fqCap.innerHTML=SH_FQ[key].cap;
    fqStop=animate(600,p=>{fqVals=from.map((v,j)=>lerp(v,to[j],ease(p)));drawFq(fqVals,key)},()=>{fqStop=null})}
  $$('[data-fq]').forEach(b=>b.addEventListener('click',()=>setFq(b.dataset.fq)));
  fqCap.innerHTML=SH_FQ.soap.cap;drawFq(fqVals,'soap');

  /* ---------- sandbox: build a blood pressure ---------- */
  const lab=$('#shLab'),hr=$('#shHr'),sv=$('#shSv'),tn=$('#shTone'),lo=$('#shLabOut');
  const PRE={start:[75,70,1],tone:[75,70,.5],tonehr:[120,75,.5],sv:[75,35,1],svhr:[120,35,1]},CO0=75*70/1000;
  function drawLab(){const H=+hr.value,S=+sv.value,T=+tn.value,co=H*S/1000,rel=co/CO0,map=rel*T;
    $('#shHrO').textContent=H+' /min';$('#shSvO').textContent=S+' mL';$('#shToneO').textContent='×'+T.toFixed(2);
    const pk=Object.keys(PRE).find(q=>PRE[q][0]===H&&PRE[q][1]===S&&Math.abs(PRE[q][2]-T)<.005);
    $$('[data-pre]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.pre===pk));
    let s=`<defs>${marker('shLA','var(--muted)',6)}</defs>`;
    const hs=40+S*.36,pw=lerp(30,6,ramp(T,.4,1.8));
    s+=`<text x="12" y="18" class="t-sm" style="fill:var(--ink);font-weight:600">pump</text><text x="140" y="18" class="t-sm" style="fill:var(--ink);font-weight:600">pipes</text><text x="318" y="18" class="t-sm t-mid" style="fill:var(--ink);font-weight:600">pressure</text>`;
    s+=`<path d="M100 92H238" style="stroke:var(--wall);stroke-width:${f1(pw+5)};stroke-linecap:round"/><path d="M100 92H238" style="stroke:var(--blood-soft);stroke-width:${f1(pw)};stroke-linecap:round"/>`;
    const nc=Math.max(2,Math.round(rel*5));for(let i=0;i<nc;i++){const cx=lerp(112,226,(i+.5)/nc);s+=`<ellipse cx="${f1(cx)}" cy="92" rx="${f1(Math.min(6,pw*.32))}" ry="${f1(Math.min(3,pw*.2))}" style="fill:var(--oxy)"/>`}
    s+=`<path d="M146 ${f1(92+pw/2+12)}h40" style="stroke:var(--muted);stroke-width:1.3" marker-end="url(#shLA)"/><text x="168" y="${f1(92+pw/2+28)}" class="t-xs t-mid">tone ×${T.toFixed(2)}</text>`;
    s+=organ('heart',60,92,hs,{});
    s+=`<text x="60" y="${f1(92+hs*.5+16)}" class="t-xs t-mid">${S} mL × ${H}/min</text>`;
    s+=gauge(318,104,52,clamp(map,0,2)*100,200,{ticks:false,bands:[{to:70,col:'var(--bad)'},{to:90,col:'var(--warn)'},{to:200,col:'var(--good)'}]});
    s+=`<text x="318" y="128" class="t-big t-mid">${Math.round(map*100)}%</text><text x="318" y="142" class="t-xs t-mid">of the start</text>`;
    const bar=(y,lbl,val,max,txt,col)=>`<text x="12" y="${y}" class="t-sm" style="fill:var(--ink)">${lbl}</text><text x="388" y="${y}" class="t-sm t-end" style="fill:var(--ink);font-weight:700">${txt}</text><rect x="12" y="${y+6}" width="376" height="12" rx="4" style="fill:var(--panel-2)"/><rect x="12" y="${y+6}" width="${f1(376*clamp(val/max))}" height="12" rx="4" style="fill:${col};opacity:.85"/>`;
    s+=bar(186,'flow (cardiac output)',co,16,co.toFixed(1)+' L/min','var(--rx)');
    s+=bar(232,'oxygen delivery (relative)',rel,3,Math.round(rel*100)+'%','var(--oxy)');
    lab.innerHTML=s;
    const d=Math.round(map*100);
    lo.innerHTML=`Cardiac output <b>${co.toFixed(2)} L/min</b> (${S} mL × ${H} beats a minute). In this model the pressure is <b>${d}%</b> of the starting value${d<95?', a fall of '+(100-d)+'%':d>105?', a rise of '+(d-100)+'%':''}, and oxygen delivery is <b>${Math.round(rel*100)}%</b>.${T<.8&&rel>1.1&&d<95?' Output is high, yet the pressure is still low: the pipes are too wide.':''}`}
  [hr,sv,tn].forEach(e=>e.addEventListener('input',drawLab));
  $$('[data-pre]').forEach(b=>b.addEventListener('click',()=>{const p=PRE[b.dataset.pre];hr.value=p[0];sv.value=p[1];tn.value=p[2];drawLab()}));
  drawLab();

  /* ---------- bedside numbers: MAP and shock index ---------- */
  const sb=$('#shSbp'),db=$('#shDbp'),hb=$('#shHrB'),cv=$('#shCalcV'),co=$('#shCalcOut'),si=$('#shSi');
  function drawSi(v){const X=x=>20+360*(clamp(x,.3,1.8)-.3)/1.5;let s='';
    s+=`<rect x="20" y="34" width="360" height="20" rx="5" style="fill:var(--panel-2)"/>`;
    s+=`<rect x="${f1(X(.5))}" y="34" width="${f1(X(.7)-X(.5))}" height="20" style="fill:var(--good);opacity:.55"/><rect x="${f1(X(.7))}" y="34" width="${f1(X(.9)-X(.7))}" height="20" style="fill:var(--warn);opacity:.3"/><rect x="${f1(X(1))}" y="34" width="${f1(X(1.8)-X(1))}" height="20" rx="5" style="fill:var(--bad);opacity:.25"/>`;
    [.3,.6,1,1.4,1.8].forEach(q=>{s+=`<line x1="${f1(X(q))}" x2="${f1(X(q))}" y1="54" y2="60" class="axis"/><text x="${f1(X(q))}" y="70" class="t-xs t-mid">${q}</text>`});
    s+=`<text x="${f1((X(.5)+X(.7))/2)}" y="86" class="t-xs t-mid" style="fill:var(--good)">0.5–0.7 usual</text><text x="${f1(X(1.35))}" y="86" class="t-xs t-mid" style="fill:var(--bad)">&gt;1.0 higher mortality</text>`;
    s+=`<text x="20" y="106" class="t-xs">trauma groups (Mutschler 2013):</text>`;
    [[.3,.6,'10.9%'],[.6,1,''],[1,1.4,''],[1.4,1.8,'39.8%']].forEach((g,j)=>{s+=`<rect x="${f1(X(g[0])+1)}" y="112" width="${f1(X(g[1])-X(g[0])-2)}" height="8" rx="3" style="fill:var(--bad);opacity:${f1(.12+j*.2)}"/>`;if(g[2])s+=`<text x="${f1((X(g[0])+X(g[1]))/2)}" y="136" class="t-xs t-mid" style="fill:var(--ink)">${g[2]} died</text>`});
    if(v!=null){const mx=X(v);s+=`<path d="M${f1(mx)} 32l-6 -9h12z" style="fill:var(--ink)"/><line x1="${f1(mx)}" x2="${f1(mx)}" y1="32" y2="56" style="stroke:var(--ink);stroke-width:2.4"/><text x="${f1(clamp(mx,40,360))}" y="16" class="t-sm t-mid" style="fill:var(--ink);font-weight:700">SI ${v.toFixed(2)}</text>`}
    si.innerHTML=s}
  function calc(){const S=+sb.value,D=+db.value,H=+hb.value;
    if(!(S>0&&D>0&&H>0)||D>=S){cv.className='verdict no';cv.textContent='Enter a systolic pressure higher than the diastolic, and a heart rate.';co.innerHTML='';drawSi(null);return}
    const pp=S-D,m3=D+pp/3,m4=D+.412*pp,x=H/S;
    cv.className='verdict maybe';
    cv.textContent=`Shock index ${x.toFixed(2)} · MAP ${Math.round(m3)} mmHg`;
    co.innerHTML=`Pulse pressure <b>${pp} mmHg</b>. MAP by the traditional formula (DBP + ⅓ × pulse pressure): <b>${m3.toFixed(1)} mmHg</b>; with the 0.412 factor: <b>${m4.toFixed(1)} mmHg</b>. Shock index (HR ÷ SBP): <b>${x.toFixed(2)}</b>, ${x<.5?'below the 0.5–0.7 range usually quoted as normal':x<=.7?'inside the 0.5–0.7 range usually quoted as normal':x<1?'above the usual 0.5–0.7 range and below 1.0':'at or above 1.0, the range widely linked with higher mortality in the studies'}. These are formula results for study, not an assessment of anyone.`;
    drawSi(x)}
  [sb,db,hb].forEach(e=>e.addEventListener('input',calc));calc();
  redraws.shock=(()=>{const prev=redraws.shock;return()=>{prev&&prev();drawFq(fqVals,fqCur)}})();
};
/* =============== 2.1 Who is at risk =============== */
/* four views of age and sepsis: icon arrays of 100, then bars per 1,000 (each from its own cited population) */
const RK_STEPS=[
 {from:0,at:.15,k:'View 1 · the US population',t:'12 in 100 people are 65 or older',
  txt:`In the US analysis by Martin and colleagues, adults aged 65 or older made up 12% of the population <sup class="c" data-ref="Martin2006Age" title="Source 280"><a href="/sepsis-and-shock/sources/#src-Martin2006Age">280</a></sup>. Keep that number in mind for the next view.`,
  pt:`Out of every 100 people in the US population studied, about 12 were aged 65 or over <sup class="c" data-ref="Martin2006Age" title="Source 280"><a href="/sepsis-and-shock/sources/#src-Martin2006Age">280</a></sup>.`,
  hook:`Older adults: 12% of the population but 64.9% of sepsis cases <sup class="c" data-ref="Martin2006Age" title="Source 280"><a href="/sepsis-and-shock/sources/#src-Martin2006Age">280</a></sup>.`},
 {from:.25,at:.4,k:'View 2 · people with sepsis',t:'65 in 100 people with sepsis are 65 or older',
  txt:`The same older adults accounted for 64.9% of sepsis cases, a relative risk of 13.1 (95% CI 12.6–13.6) compared with younger adults, and age independently predicted death (OR 2.26) <sup class="c" data-ref="Martin2006Age" title="Source 280"><a href="/sepsis-and-shock/sources/#src-Martin2006Age">280</a></sup>. In US data from 1995, severe-sepsis incidence rose more than 100-fold with age <sup class="c" data-ref="Angus2001CCM" title="Source 19"><a href="/sepsis-and-shock/sources/#src-Angus2001CCM">19</a></sup>.`,
  pt:`Older people are much more likely to get sepsis: about two thirds of people with sepsis in this study were 65 or older <sup class="c" data-ref="Martin2006Age" title="Source 280"><a href="/sepsis-and-shock/sources/#src-Martin2006Age">280</a></sup>.`,
  hook:`Age ≥65: RR 13.1 for sepsis versus younger adults; OR 2.26 for death <sup class="c" data-ref="Martin2006Age" title="Source 280"><a href="/sepsis-and-shock/sources/#src-Martin2006Age">280</a></sup>.`},
 {from:.5,at:.65,k:'View 3 · the world, 2017',t:'More than half of cases are in children',
  txt:`Of an estimated 48.9 million sepsis cases worldwide in 2017, 20.3 million were in children under 5, 4.9 million at ages 5–19 and 23.7 million in adults 20 or older. The authors note that more than half of all cases were among children, many of them newborns <sup class="c" data-ref="Rudd2020GBD" title="Source 400"><a href="/sepsis-and-shock/sources/#src-Rudd2020GBD">400</a></sup>. Among children under 5, the commonest causes were diarrhoeal disease (27.9%), neonatal disorders (25.7%) and lower respiratory infection (16.5%) <sup class="c" data-ref="Rudd2020GBD" title="Source 400"><a href="/sepsis-and-shock/sources/#src-Rudd2020GBD">400</a></sup>.`,
  pt:`Around the world, babies and young children are hit hardest: in 2017, more than half of everyone with sepsis was a child <sup class="c" data-ref="Rudd2020GBD" title="Source 400"><a href="/sepsis-and-shock/sources/#src-Rudd2020GBD">400</a></sup>.`,
  hook:`GBD 2017: 20.3 million of 48.9 million cases were in under-5s; incidence peaks in early childhood and again in older adults <sup class="c" data-ref="Rudd2020GBD" title="Source 400"><a href="/sepsis-and-shock/sources/#src-Rudd2020GBD">400</a></sup>.`},
 {from:.75,at:.9,k:'View 4 · rates',t:'The two ends of life',
  txt:`In US data from 1995, severe sepsis occurred in 0.2 per 1,000 children and 26.2 per 1,000 people over 85, and mortality rose from 10% to 38.4% <sup class="c" data-ref="Angus2001CCM" title="Source 19"><a href="/sepsis-and-shock/sources/#src-Angus2001CCM">19</a></sup>. A 2021 meta-analysis estimated neonatal sepsis at 2,824 per 100,000 live births (about 28 per 1,000), the highest population incidence of any age group, with 17.6% dying <sup class="c" data-ref="Fleischmann2021Neonatal" title="Source 152"><a href="/sepsis-and-shock/sources/#src-Fleischmann2021Neonatal">152</a></sup>. The rates come from different populations and definitions, so compare their size, not their decimals.`,
  pt:`Newborn babies and the very old have the highest rates of sepsis. These are figures for large groups, not predictions for one person <sup class="c" data-ref="Angus2001CCM,Fleischmann2021Neonatal" title="Source 19,152"><a href="/sepsis-and-shock/sources/#src-Angus2001CCM">19,152</a></sup>.`,
  hook:`Neonates: about 2,824 sepsis cases per 100,000 live births <sup class="c" data-ref="Fleischmann2021Neonatal" title="Source 152"><a href="/sepsis-and-shock/sources/#src-Fleischmann2021Neonatal">152</a></sup>. Over 85s: 26.2 per 1,000 <sup class="c" data-ref="Angus2001CCM" title="Source 19"><a href="/sepsis-and-shock/sources/#src-Angus2001CCM">19</a></sup>.`}
];
/* REGARDS adjusted hazard ratios */
const RK_HR=[
 ['Chronic lung disease',2.43,'sepsis','Wang2012Chronic'],['Peripheral artery disease',2.16,'sepsis','Wang2012Chronic'],['Steroid medicines',2.10,'infection','Chaudhary2017Steroids'],
 ['Chronic kidney disease',1.99,'sepsis','Wang2012Chronic'],['Previous heart attack',1.79,'sepsis','Wang2012Chronic'],['Diabetes',1.78,'sepsis','Wang2012Chronic'],
 ['Stroke',1.67,'sepsis','Wang2012Chronic'],['Deep vein thrombosis',1.63,'sepsis','Wang2012Chronic'],['Frailty',1.44,'sepsis','Mahalingam2019Frailty']];
const RK_HRTXT=[
 `Chronic lung disease: adjusted hazard ratio 2.43, the strongest single condition in REGARDS. People who had it at the start went on to develop sepsis at about 2.4 times the rate of comparable people without it, after adjusting for other factors <sup class="c" data-ref="Wang2012Chronic" title="Source 507"><a href="/sepsis-and-shock/sources/#src-Wang2012Chronic">507</a></sup>.`,
 `Peripheral artery disease (narrowed leg arteries): adjusted hazard ratio 2.16, about twice the rate of sepsis of comparable people without it <sup class="c" data-ref="Wang2012Chronic" title="Source 507"><a href="/sepsis-and-shock/sources/#src-Wang2012Chronic">507</a></sup>.`,
 `Oral or injected steroids: adjusted hazard ratio 2.10 for infection, and once infected, adjusted odds ratio 2.11 for sepsis <sup class="c" data-ref="Chaudhary2017Steroids" title="Source 92"><a href="/sepsis-and-shock/sources/#src-Chaudhary2017Steroids">92</a></sup>. Steroids are often essential medicines: the point is to know the risk, not to stop them without advice.`,
 `Chronic kidney disease: adjusted hazard ratio 1.99, about twice the rate of comparable people without it <sup class="c" data-ref="Wang2012Chronic" title="Source 507"><a href="/sepsis-and-shock/sources/#src-Wang2012Chronic">507</a></sup>.`,
 `A previous heart attack (myocardial infarction): adjusted hazard ratio 1.79 <sup class="c" data-ref="Wang2012Chronic" title="Source 507"><a href="/sepsis-and-shock/sources/#src-Wang2012Chronic">507</a></sup>.`,
 `Diabetes: adjusted hazard ratio 1.78 <sup class="c" data-ref="Wang2012Chronic" title="Source 507"><a href="/sepsis-and-shock/sources/#src-Wang2012Chronic">507</a></sup>.`,
 `Stroke: adjusted hazard ratio 1.67 <sup class="c" data-ref="Wang2012Chronic" title="Source 507"><a href="/sepsis-and-shock/sources/#src-Wang2012Chronic">507</a></sup>.`,
 `Deep vein thrombosis: adjusted hazard ratio 1.63 <sup class="c" data-ref="Wang2012Chronic" title="Source 507"><a href="/sepsis-and-shock/sources/#src-Wang2012Chronic">507</a></sup>.`,
 `Frailty: adjusted hazard ratio 1.44 for sepsis, and adjusted odds ratio 1.62 for dying within 30 days of it <sup class="c" data-ref="Mahalingam2019Frailty" title="Source 272"><a href="/sepsis-and-shock/sources/#src-Mahalingam2019Frailty">272</a></sup>.`];
inits.risk=()=>{
  /* ---------- main: icon arrays and rates ---------- */
  const svg=$('#rkSvg'),rg=$('#rkT'),note=$('#rkNote');let setSt=()=>{};
  const CAT=[['aged 65+','var(--accent)'],['under 5','var(--brand)'],['5–19','var(--gold)'],['20 or older','var(--dx)']];
  function draw(t){const N=vb(svg,'720 360','400 530'),p=phaseOf(RK_STEPS,t),S=RK_STEPS[p],u=ramp(t,S.from,S.from+.2),e=ease(u);
    const L=N?{gx:60,gy:70,sz:22,gp:6,rx:16,ry:400,bx:16,bw:300,by:90}:{gx:36,gy:66,sz:18,gp:7,rx:330,ry:96,bx:230,bw:420,by:110};
    let s=`<text x="16" y="26" class="t-big">${S.t}</text><text x="16" y="42" class="t-sm">${['US population (Martin 2006)','US sepsis cases (Martin 2006)','world sepsis cases, 2017 (GBD)','rates per 1,000 (Angus 2001; Fleischmann 2021)'][p]}</text>`;
    /* the 100-icon grid: colour by view */
    const fade=p===3?1-ease(ramp(t,.75,.82)):1;
    if(fade>0){let cnt=[0,0,0,0];
      const col=i=>{if(p===0){const k=Math.round(12*e);return i<k?0:-1}
        if(p===1){const k=Math.round(lerp(12,65,e));return i<k?0:-1}
        const a=Math.round(42*ease(ramp(u,0,.4))),b=Math.round(10*ease(ramp(u,.3,.6))),c=Math.round(48*ease(ramp(u,.5,1)));
        return i<a?1:i<42?-1:i<42+b?2:i<52?-1:i<52+c?3:-1};
      s+=`<g style="opacity:${f1(fade)}">`;
      for(let i=0;i<100;i++){const c=p===3?(i<42?1:i<52?2:3):col(i);if(c>=0)cnt[c]++;const x=L.gx+(i%10)*(L.sz+L.gp),y=L.gy+Math.floor(i/10)*(L.sz+L.gp*1.2);
        s+=person(x+L.sz/2,y,L.sz,c<0?'var(--line)':CAT[c][1])}
      s+=`</g>`;
      /* legend and the big number */
      const lx=L.rx,ly=L.ry;
      if(p<2){const k=p===0?Math.round(12*e):Math.round(lerp(12,65,e));
        s+=`<text x="${lx}" y="${ly}" class="t-big" style="font-size:44px;fill:var(--accent)">${k}</text><text x="${lx+(k>9?58:32)}" y="${ly}" class="t-big">in 100</text>`;
        s+=`<text x="${lx}" y="${ly+26}" class="t-sm" style="fill:var(--ink)">${p===0?'people in the population':'people with sepsis'}</text><text x="${lx}" y="${ly+42}" class="t-sm" style="fill:var(--ink)">are aged 65 or over</text>`;
        if(p===1)s+=`<text x="${lx}" y="${ly+70}" class="t-sm">relative risk 13.1 vs</text><text x="${lx}" y="${ly+85}" class="t-sm">younger adults</text>`}
      else if(p===2){[[1,'42','under 5 years'],[2,'10','aged 5–19'],[3,'48','aged 20 or older']].forEach((r,j)=>{const y=ly+j*(N?34:44);
          s+=`<rect x="${lx}" y="${y-14}" width="16" height="16" rx="4" style="fill:${CAT[r[0]][1]}"/><text x="${lx+24}" y="${y}" class="t-big" style="fill:${CAT[r[0]][1]}">${cnt[r[0]]}</text><text x="${lx+58}" y="${y}" class="t-sm" style="fill:var(--ink)">${r[2]}</text>`});
        s+=`<text x="${lx}" y="${ly+(N?108:140)}" class="t-sm">of 100 cases (48.9 million in all)</text>`}}
    /* view 4: bars per 1,000 */
    if(p===3){const g=ease(ramp(t,.8,.92)),X=v=>L.bx+L.bw*v/30;
      const R=[['children, US 1995',.2,'var(--brand)'],['over 85s, US 1995',26.2,'var(--accent)'],['newborns (per 1,000 births)',28.24,'var(--brand)']];
      s+=`<g style="opacity:${f1(ramp(t,.78,.84))}">`;
      R.forEach((r,j)=>{const y=L.by+j*(N?110:64);
        s+=`<text x="${N?L.bx:L.bx-12}" y="${N?y-10:y+15}" class="t-sm${N?'':' t-end'}" style="fill:var(--ink);font-weight:600">${r[0]}</text>`;
        s+=`<rect x="${L.bx}" y="${y}" width="${L.bw}" height="22" rx="5" style="fill:var(--panel-2)"/><rect x="${L.bx}" y="${y}" width="${f1(Math.max(2,(X(r[1])-L.bx)*g))}" height="22" rx="5" style="fill:${r[2]};opacity:.85"/>`;
        s+=`<text x="${f1(L.bx+Math.max(2,(X(r[1])-L.bx)*g)+8)}" y="${y+16}" class="t-sm" style="fill:var(--ink);font-weight:700">${(r[1]*g).toFixed(1)}</text>`});
      const ay=L.by+(N?330:196);s+=tline(L.bx,ay,L.bw,{min:0,max:30,step:10,label:'per 1,000'}).svg;
      s+=`<text x="${L.bx}" y="${ay+46}" class="t-xs">Different sources and definitions:</text><text x="${L.bx}" y="${ay+58}" class="t-xs">compare the size of the bars, not the decimals.</text></g>`}
    svg.innerHTML=s;note.innerHTML=noteHTML(S);setSt(p)}
  const stop=playWire(rg,$('#rkPlay'),draw,24000,'Replay','risk');
  setSt=stepWire($('#rkSteps'),RK_STEPS,rg,draw,stop);draw(+rg.value);

  /* ---------- REGARDS hazard ratios ---------- */
  const hs=$('#rkHr'),ho=$('#rkHrOut');let sel=0;
  function drawHr(){const N=vb(hs,'720 330','400 490');let s='';
    const lx=N?12:16,bx=N?12:230,bw=N?330:420,rh=N?44:32,y0=N?34:30,X=v=>bx+bw*(v-1)/1.6;
    s+=`<text x="${f1(X(1))}" y="${y0-(N?20:14)}" class="t-xs${N?'':' t-mid'}" style="fill:var(--ink)">1 = same rate</text>`;
    RK_HR.forEach((r,i)=>{const y=y0+i*rh+(N?14:0),on=i===sel,w=X(r[1])-X(1);
      s+=`<text x="${N?lx:bx-10}" y="${f1(N?y-4:y+14)}" class="t-sm${N?'':' t-end'}" style="fill:var(--ink);${on?'font-weight:700':''}">${r[0]}${r[2]==='infection'?' (infection)':''}</text>`;
      s+=`<rect x="${f1(X(1))}" y="${y}" width="${f1(w)}" height="18" rx="4" style="fill:${on?'var(--accent)':'var(--dx)'};opacity:${on?.95:.55}"/>`;
      s+=`<text x="${f1(X(r[1])+6)}" y="${y+13}" class="t-sm" style="fill:var(--ink);font-weight:${on?700:500}">${r[1].toFixed(2)}</text>`});
    const ay=y0+RK_HR.length*rh+(N?14:6);
    s+=`<line x1="${f1(X(1))}" x2="${f1(X(1))}" y1="${y0-8}" y2="${ay}" style="stroke:var(--ink);stroke-width:1.4"/>`;
    s+=tline(X(1),ay,bw,{min:1,max:2.6,step:.4,fmt:v=>v.toFixed(1),label:'adjusted hazard ratio'}).svg;
    hs.innerHTML=s;ho.innerHTML=RK_HRTXT[sel]+' A hazard ratio compares rates between groups; it does not tell any one person their own chance.';
    $$('[data-hr]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.hr===sel))}
  $$('[data-hr]').forEach(b=>b.addEventListener('click',()=>{sel=+b.dataset.hr;drawHr()}));drawHr();
  redraws.risk=(()=>{const prev=redraws.risk;return()=>{prev&&prev();drawHr()}})();
};
/* ===== 2.2 Recognising sepsis ===== */
/* NEWS2 points as in the chart reproduced by Verma 2023 (from RCP 2017). Teaching only. */
function rcPts(o){
  const rr=o.rr<=8?3:o.rr<=11?1:o.rr<=20?0:o.rr<=24?2:3;
  let sp;if(o.scale===2){const s=o.sp,ox=o.o2;sp=s<=83?3:s<=85?2:s<=87?1:s<=92?0:!ox?0:s<=94?1:s<=96?2:3}
  else sp=o.sp<=91?3:o.sp<=93?2:o.sp<=95?1:0;
  const o2=o.o2?2:0;
  const bp=o.sbp<=90?3:o.sbp<=100?2:o.sbp<=110?1:o.sbp<=219?0:3;
  const hr=o.hr<=40?3:o.hr<=50?1:o.hr<=90?0:o.hr<=110?1:o.hr<=130?2:3;
  const cn=o.conf?3:0;
  const tt=Math.round(o.temp*10)/10,te=tt<=35?3:tt<=36?1:tt<=38?0:tt<=39?1:2;
  const P={rr,sp,o2,bp,hr,cn,te};P.total=rr+sp+o2+bp+hr+cn+te;P.any3=[rr,sp,bp,hr,cn,te].some(v=>v===3);return P}
function rcBand(P){return P.total>=7?{k:'high',l:'High',c:'var(--bad)'}:P.total>=5?{k:'med',l:'Medium',c:'var(--warn)'}:P.any3?{k:'lm',l:'Low-medium',c:'var(--warn)'}:{k:'low',l:'Low',c:'var(--good)'}}
const RC_SIGNS=[
 {L:'S',w:'Slurred speech or confusion',v:22.2},{L:'E',w:'Extreme shivering or muscle pain, fever',v:54.9},{L:'P',w:'Passing no urine all day',v:4.1},
 {L:'S',w:'Severe breathlessness',v:41.4},{L:'I',w:'It feels like you are going to die',v:1.1},{L:'S',w:'Skin mottled or discoloured',v:1.1}];
const RC_STEPS=[
 {from:0,at:.06,t:'An infection',k:'Where it starts',h:'It starts with an infection',
  txt:`Sepsis begins with an infection somewhere in the body: here, the lungs, because pneumonia was the commonest infection behind sepsis in a CDC review of 325 patients. Early on, it can look like an ordinary illness. Vague presenting symptoms were independently linked with in-hospital death in a Thai cohort (adjusted OR 2.17). <sup class="c" data-ref="Novosad2016MMWR,Wattanapaiboon2020SEPSIS" title="Source 332,512"><a href="/sepsis-and-shock/sources/#src-Novosad2016MMWR">332,512</a></sup>`,
  pt:`Most infections get better. The worry is a person who becomes much more unwell than you would expect, or keeps getting worse.`,
  hook:`Pneumonia is the commonest source of sepsis in the CDC New York review.`},
 {from:.12,at:.18,t:'S · Confusion',k:'S',h:'Slurred speech or confusion',
  txt:`New confusion, drowsiness or slurred speech can mean the brain is not getting enough blood and oxygen. Altered mentation is one of the three qSOFA items, and new confusion scores the full 3 points in NEWS2. In the Thai cohort, 22.2% of people with sepsis reported it. <sup class="c" data-ref="Seymour2016qSOFA,Verma2023NEWS2,Wattanapaiboon2020SEPSIS" title="Source 435,493,512"><a href="/sepsis-and-shock/sources/#src-Seymour2016qSOFA">435,493,512</a></sup>`,
  pt:`If someone is muddled, saying odd things, or very hard to wake, and this is new, treat it as serious.`,
  hook:`New confusion = 3 points on NEWS2 and 1 point on qSOFA.`},
 {from:.25,at:.31,t:'E · Shivering, fever',k:'E',h:'Extreme shivering or muscle pain, fever',
  txt:`This was the commonest sign in the Thai emergency cohort, reported by 54.9%. Temperature counts both ways in NEWS2: 38.1°C or more scores points, and so does 36.0°C or below. <sup class="c" data-ref="Wattanapaiboon2020SEPSIS,Verma2023NEWS2" title="Source 493,512"><a href="/sepsis-and-shock/sources/#src-Wattanapaiboon2020SEPSIS">493,512</a></sup>`,
  pt:`Uncontrollable shaking, severe aches, or feeling very hot or very cold can all be part of sepsis. A normal or low temperature does not rule it out.`,
  hook:`NEWS2 scores a low temperature (≤35.0°C = 3 points) as well as fever.`},
 {from:.37,at:.43,t:'P · No urine',k:'P',h:'Passing no urine all day',
  txt:`When blood pressure falls and blood flow to the kidneys drops, they make less urine. Few people mentioned it (4.1% in the Thai cohort), so it is a sign to ask about directly. Urine output is also part of the kidney score in SOFA. <sup class="c" data-ref="Wattanapaiboon2020SEPSIS,Lambden2019SOFA" title="Source 247,512"><a href="/sepsis-and-shock/sources/#src-Wattanapaiboon2020SEPSIS">247,512</a></sup>`,
  pt:`Ask when the person last passed urine. Very little or none for many hours is a warning sign.`,
  hook:`Low urine output reflects poor kidney perfusion; SOFA counts urine below 500 ml/day.`},
 {from:.5,at:.56,t:'S · Breathless',k:'S',h:'Severe breathlessness',
  txt:`Fast breathing is one of the earliest and most useful observations. A respiratory rate of 22 or more is a qSOFA item, and NEWS2 gives 2 points at 21–24 and 3 points at 25 or more breaths a minute. 41.4% of the Thai cohort reported breathlessness. <sup class="c" data-ref="Seymour2016qSOFA,Verma2023NEWS2,Wattanapaiboon2020SEPSIS" title="Source 435,493,512"><a href="/sepsis-and-shock/sources/#src-Seymour2016qSOFA">435,493,512</a></sup>`,
  pt:`Count the breaths for a minute. Breathing very fast, or struggling to speak in sentences, needs urgent help.`,
  hook:`RR ≥22 (qSOFA); RR ≥25 = 3 points (NEWS2).`},
 {from:.62,at:.68,t:'I · Feels like dying',k:'I',h:'It feels like you are going to die',
  txt:`Some people describe an overwhelming sense that something is very wrong. Only 1.1% of the Thai cohort said this, so its absence means little, but when a person or family says it, it deserves to be taken seriously. <sup class="c" data-ref="Wattanapaiboon2020SEPSIS" title="Source 512"><a href="/sepsis-and-shock/sources/#src-Wattanapaiboon2020SEPSIS">512</a></sup>`,
  pt:`If the person says they have never felt this ill, believe them and get help.`,
  hook:`The SEPSIS mnemonic is an awareness tool and "has not been validated".`},
 {from:.75,at:.81,t:'S · Skin',k:'S',h:'Skin mottled or discoloured',
  txt:`Mottled, blotchy, pale-blue or grey skin, often on the knees and limbs, and cold hands and feet are signs that blood is not reaching the skin. In children with meningococcal disease, abnormal skin colour and cold hands and feet were early signs, appearing at a median of 8 hours. <sup class="c" data-ref="Wattanapaiboon2020SEPSIS,Thompson2006Meningococcal" title="Source 474,512"><a href="/sepsis-and-shock/sources/#src-Wattanapaiboon2020SEPSIS">474,512</a></sup>`,
  pt:`Look at the skin on the knees, arms and lips. Blotchy, bluish or grey patches are a reason to call for help now.`,
  hook:`Early meningococcal sepsis signs: leg pain, cold hands and feet, abnormal skin colour.`},
 {from:.88,at:.95,t:'None of these',k:'A caution',h:'No sign does not mean no sepsis',
  txt:`In the Thai cohort, 14.9% of people with sepsis had none of the six SEPSIS signs. The mnemonic raises awareness; it cannot rule sepsis out. Doctors combine the story, the examination, repeated observations and tests. <sup class="c" data-ref="Wattanapaiboon2020SEPSIS" title="Source 512"><a href="/sepsis-and-shock/sources/#src-Wattanapaiboon2020SEPSIS">512</a></sup>`,
  pt:`If you are worried, say so, even if the person does not fit a checklist. Ask: could this be sepsis?`,
  hook:`About 1 in 7 people with sepsis in the Thai cohort had none of the SEPSIS signs.`}];
/* invented example patient for the timeline, all on air */
const RC_OBS=[{h:0,rr:16,sp:97,sbp:128,hr:84,temp:37.6,conf:false},{h:2,rr:19,sp:96,sbp:122,hr:94,temp:38.3,conf:false},
  {h:4,rr:21,sp:95,sbp:114,hr:102,temp:38.7,conf:false},{h:6,rr:23,sp:94,sbp:106,hr:112,temp:38.9,conf:false},{h:8,rr:25,sp:93,sbp:98,hr:118,temp:39.2,conf:true}]
  .map(o=>Object.assign(o,{scale:1,o2:false,P:rcPts(Object.assign({scale:1,o2:false},o))}));
const RC_STEPS2=[
 {from:0,at:.02,t:'Hour 0',k:'Observations · hour 0',h:'All six observations normal',
  txt:`Breathing 16, SpO₂ 97% on air, systolic BP 128, pulse 84, temperature 37.6°C, alert: every observation sits in the 0-point column. A score of 0 is the low band. <sup class="c" data-ref="Verma2023NEWS2" title="Source 493"><a href="/sepsis-and-shock/sources/#src-Verma2023NEWS2">493</a></sup>`,
  pt:`At the start, every number is in the normal range, so the score is 0.`,hook:`NEWS2 0–4 = low clinical risk.`},
 {from:.2,at:.21,t:'Hour 2',k:'Observations · hour 2',h:'Pulse and temperature tick up',
  txt:`Pulse 94 (91–110: 1 point) and temperature 38.3°C (38.1–39.0: 1 point). Total 2, still the low band. Nothing looks dramatic yet, which is exactly why the trend matters. <sup class="c" data-ref="Verma2023NEWS2" title="Source 493"><a href="/sepsis-and-shock/sources/#src-Verma2023NEWS2">493</a></sup>`,
  pt:`Small changes like a faster pulse and a fever are common in any infection. On their own they do not mean sepsis.`,hook:`Pulse 91–110 = 1; temperature 38.1–39.0 = 1.`},
 {from:.4,at:.41,t:'Hour 4',k:'Observations · hour 4',h:'Breathing speeds up: medium band',
  txt:`Breathing 21 (21–24: 2 points), SpO₂ 95% (1), pulse 102 (1), temperature 38.7°C (1): total 5, the medium band (5–6). Breathing rate is often the first observation to move. Churpek found qSOFA ≥2 was first met a median of only 5 hours before death or ICU transfer, against 17 hours for SIRS ≥2. <sup class="c" data-ref="Verma2023NEWS2,Churpek2017" title="Source 97,493"><a href="/sepsis-and-shock/sources/#src-Verma2023NEWS2">97,493</a></sup>`,
  pt:`The breathing is getting faster. Together, the small changes now add up to a score that tells staff to look more closely.`,hook:`NEWS2 5–6 = medium clinical risk.`},
 {from:.6,at:.61,t:'Hour 6',k:'Observations · hour 6',h:'Blood pressure falls: high band',
  txt:`Breathing 23 (2), SpO₂ 94% (1), systolic 106 (101–110: 1), pulse 112 (111–130: 2), temperature 38.9°C (1): total 7, the high band. In 198,755 observation sets, NEWS discriminated death within 24 hours with AUROC 0.894. <sup class="c" data-ref="Verma2023NEWS2,Smith2013NEWS" title="Source 453,493"><a href="/sepsis-and-shock/sources/#src-Verma2023NEWS2">453,493</a></sup>`,
  pt:`Now the score is high. On the chart, this band means a high clinical risk: a signal that this person may be seriously ill.`,hook:`NEWS2 ≥7 = high clinical risk.`},
 {from:.8,at:.85,t:'Hour 8',k:'Observations · hour 8',h:'New confusion',
  txt:`Breathing 25 (3), SpO₂ 93% (2), systolic 98 (91–100: 2), pulse 118 (2), temperature 39.2°C (2) and new confusion (3): total 14. Two single observations now score 3 each. This invented patient also meets qSOFA (breathing ≥22, systolic ≤100, altered mentation), which was framed in Sepsis-3 as a prompt to consider possible sepsis. <sup class="c" data-ref="Verma2023NEWS2,Seymour2016qSOFA" title="Source 435,493"><a href="/sepsis-and-shock/sources/#src-Verma2023NEWS2">435,493</a></sup>`,
  pt:`New confusion plus very fast breathing and falling blood pressure is an emergency. Recognising the rising trend earlier is the aim.`,hook:`A single parameter scoring 3 is low-medium risk even when the total is low.`}];
inits.recognise=()=>{
  /* ---------- 1. the SEPSIS signs ---------- */
  const svg=$('#rcSvg'),rg=$('#rcT');
  function draw(t){
    const N=vb(svg,'720 380','400 630'),p=phaseOf(RC_STEPS,t),st=RC_STEPS[p],nx=p<RC_STEPS.length-1?RC_STEPS[p+1].from:1.0001,lp=ease(ramp(t,st.from,st.from+(nx-st.from)*.45)),si=p-1;
    const L=N?{bx:200,by:66,bs:.78,th:{x:150,y:72},rx:16,ry:318,rw:368,rh:34,ix:24,iy:566}:{bx:170,by:62,bs:1.05,th:{x:96,y:80},rx:356,ry:44,rw:346,rh:40,ix:372,iy:302};
    let s='';
    const shiv=si===1?Math.sin(t*900)*2.4*lp:0;
    const B=body(L.bx+shiv,L.by,L.bs,{id:'rcB',infect:{site:'lung',v:p===0?.4+.6*lp:.35},mottle:si===5?lp:0,cold:si===5?lp:0});
    const hd=B.at.brain,lu=B.at.lung,bl=B.at.bladder,hs=L.bs;
    s+=`<text x="${N?16:20}" y="28" class="t-big" style="fill:${p>0&&p<7?'var(--accent)':'var(--ink)'}">${p>0&&p<7?RC_SIGNS[si].L+' · '+RC_SIGNS[si].w:st.h}</text>`;
    s+=B.svg;
    if(si===0){for(let i=0;i<4;i++){const a=t*40+i*Math.PI/2,r=34*hs;s+=`<text x="${f1(hd[0]+Math.cos(a)*r)}" y="${f1(hd[1]-4+Math.sin(a)*r*.55)}" class="t-big t-mid" style="fill:var(--accent);opacity:${f1(lp)}">?</text>`}
      s+=`<path d="M${f1(hd[0]+22*hs)} ${f1(hd[1]-28*hs)}c6 -6 12 0 6 6s-12 0 -6 -12" style="fill:none;stroke:var(--accent);stroke-width:1.6;opacity:${f1(lp)}"/>`}
    if(si===1){s+=thermometer(L.bx+62*hs,L.by+10,60*hs,.45+.5*lp,{w:8,label:'fever'});
      [-1,1].forEach(d=>{const ax=B.at.arm[0]+(d>0?96*hs:0)+d*10,ay=B.at.arm[1];for(let k=0;k<3;k++)s+=`<path d="M${f1(ax+d*k*6)} ${f1(ay-14)}q${f1(d*4)} 7 0 14q${f1(-d*4)} 7 0 14" style="fill:none;stroke:var(--accent);stroke-width:1.5;opacity:${f1(lp*(1-k*.25))}"/>`})}
    if(si===2){const dx=L.bx+(N?84:92)*hs,dy=bl[1]+10;s+=`<path d="M${f1(dx)} ${f1(dy-14)}C${f1(dx+9)} ${f1(dy-2)} ${f1(dx+9)} ${f1(dy+8)} ${f1(dx)} ${f1(dy+8)}C${f1(dx-9)} ${f1(dy+8)} ${f1(dx-9)} ${f1(dy-2)} ${f1(dx)} ${f1(dy-14)}Z" style="fill:none;stroke:var(--fluid);stroke-width:2;stroke-dasharray:3 3"/><line x1="${f1(dx-11)}" y1="${f1(dy+10)}" x2="${f1(dx+11)}" y2="${f1(dy-16)}" style="stroke:var(--bad);stroke-width:2.4;opacity:${f1(lp)}"/><text x="${f1(dx)}" y="${f1(dy+26)}" class="t-xs t-mid">no urine</text>`;
      s+=clock(dx,dy-62,20,lp*1440,{full:1440,col:'var(--accent)',label:'hours pass'})}
    if(si===3){s+=organ('lung',lu[0],lu[1],30*hs,{glow:lp});const ph=(t*30)%1;
      for(let k=0;k<3;k++){const u=(ph+k/3)%1;s+=`<path d="M${f1(hd[0]+16*hs+u*40)} ${f1(hd[1]+8-6)}q6 6 0 12" style="fill:none;stroke:var(--dx);stroke-width:2;opacity:${f1(lp*(1-u))}"/>`}}
    if(si===4){const bx=hd[0]+24*hs,by=hd[1]-10,bw=124;s+=`<g style="opacity:${f1(lp)}"><rect x="${f1(bx)}" y="${f1(by-30)}" width="${bw}" height="42" rx="12" style="fill:var(--panel);stroke:var(--accent);stroke-width:1.6"/><path d="M${f1(bx+4)} ${f1(by+4)}l-12 10l18 -4" style="fill:var(--panel);stroke:var(--accent);stroke-width:1.6"/><text x="${f1(bx+bw/2)}" y="${f1(by-13)}" class="t-sm t-mid" style="fill:var(--ink)">I feel like I'm</text><text x="${f1(bx+bw/2)}" y="${f1(by+2)}" class="t-sm t-mid" style="fill:var(--ink)">going to die</text></g>`}
    if(si===5)s+=`<text x="${f1(B.at.knee[0]+70*hs)}" y="${f1(B.at.knee[1])}" class="t-xs" style="opacity:${f1(lp)}">mottled, cold</text>`;
    /* the letters and how often each was reported */
    const X0=L.rx,bw=L.rw-150,sc=v=>bw*v/60;
    s+=`<text x="${X0}" y="${L.ry-8}" class="t-xs">reported by % of 437 patients</text>`;
    RC_SIGNS.forEach((g,i)=>{const y=L.ry+i*L.rh,on=i===si,done=i<si||p===7;
      s+=`<rect x="${X0}" y="${y}" width="${L.rw}" height="${L.rh-6}" rx="8" style="fill:${on?'var(--accent-soft)':'var(--panel)'};stroke:${on?'var(--accent)':'var(--line)'}"/>`;
      s+=`<text x="${X0+16}" y="${y+(L.rh-6)/2+7}" class="t-big t-mid" style="font-size:20px;fill:${on||done?'var(--accent)':'var(--muted)'}">${g.L}</text>`;
      const vv=on?g.v*lp:done?g.v:0;
      s+=`<rect x="${X0+34}" y="${y+(L.rh-6)/2-5}" width="${f1(Math.max(1,sc(vv)))}" height="10" rx="3" style="fill:var(--accent);opacity:${on?1:.5}"/>`;
      s+=`<text x="${X0+40+bw}" y="${y+(L.rh-6)/2+4}" class="t-sm" style="fill:${on?'var(--ink)':'var(--muted)'}">${on||done?g.v.toFixed(1)+'%':''}</text>`});
    if(p===7){const I=icons(L.ix,L.iy-(N?20:0),{n:100,cols:20,k:15,size:N?11:12,gap:3,col:'var(--accent)',base:'var(--line)',shape:'dot'});
      s+=`<text x="${L.ix}" y="${L.iy-(N?28:8)}" class="t-sm" style="fill:var(--ink)">about 15 in 100 had none of the six (14.9%)</text>`+`<g style="opacity:${f1(lp)}">${I.svg}</g>`}
    svg.innerHTML=s;
    $('#rcNote').innerHTML=noteHTML({k:st.k,t:st.h,txt:st.txt,pt:st.pt,hook:st.hook});
    $('#rcRead').innerHTML=`<span>Step <b>${p+1}</b> of ${RC_STEPS.length}</span><span>${p>0&&p<7?'Reported by <b>'+RC_SIGNS[si].v.toFixed(1)+'%</b>':p===7?'None of the signs: <b>14.9%</b>':'Source: <b>lungs</b> (example)'}</span>`;
    mark(p)}
  const stop=playWire(rg,$('#rcPlay'),draw,16000,'Replay','recognise');
  const mark=stepWire($('#rcSteps'),RC_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---------- 2. the deterioration timeline ---------- */
  const svg2=$('#rcSvg2'),rg2=$('#rcT2');
  const ROWS=[['Breathing','rr',o=>o.rr,'/min'],['SpO₂','sp',o=>o.sp+'%',''],['Systolic BP','bp',o=>o.sbp,''],['Pulse','hr',o=>o.hr,''],['Temp','te',o=>o.temp.toFixed(1),'°C'],['Conscious','cn',o=>o.conf?'New C':'Alert','']];
  const PCOL=['var(--panel)','var(--warn-soft)','var(--accent-soft)','var(--bad-soft)'];
  function draw2(t){
    const N=vb(svg2,'720 380','400 560'),p=phaseOf(RC_STEPS2,t),st=RC_STEPS2[p],hr=clamp(t*10,0,8);
    const L=N?{lx:10,cx:108,cw:52,ry:36,rh:34,gx:40,gy:290,gw:340,gh:220}:{lx:16,cx:136,cw:110,ry:34,rh:30,gx:60,gy:236,gw:620,gh:124};
    let s=`<text x="${L.lx}" y="${L.ry-14}" class="t-xs">invented example · all on air</text>`;
    RC_OBS.forEach((o,j)=>{const x=L.cx+j*(L.cw+4),vis=ramp(hr,o.h-.6,o.h);
      s+=`<text x="${f1(x+L.cw/2)}" y="${L.ry-2}" class="t-xs t-mid" style="fill:${vis>0?'var(--ink)':'var(--muted)'}">h${o.h}</text>`;
      ROWS.forEach((r,i)=>{const y=L.ry+4+i*L.rh,pt=o.P[r[1]];
        s+=`<rect x="${f1(x)}" y="${f1(y)}" width="${L.cw}" height="${L.rh-4}" rx="6" style="fill:${vis>0?PCOL[pt]:'var(--panel)'};stroke:var(--line);opacity:${f1(.25+.75*vis)}"/>`;
        if(vis>0)s+=`<text x="${f1(x+6)}" y="${f1(y+(L.rh-4)/2+4)}" class="t-sm" style="fill:var(--ink);opacity:${f1(vis)}">${r[2](o)}</text><text x="${f1(x+L.cw-6)}" y="${f1(y+(L.rh-4)/2+4)}" class="t-sm t-end" style="fill:${pt===3?'var(--bad)':'var(--muted)'};font-weight:600;opacity:${f1(vis)}">${pt}</text>`})});
    ROWS.forEach((r,i)=>{s+=`<text x="${L.lx}" y="${f1(L.ry+4+i*L.rh+(L.rh-4)/2+4)}" class="t-sm" style="fill:var(--ink)">${r[0]}</text>`});
    /* the score line with its bands */
    const Xh=h=>L.gx+L.gw*h/8,Ys=v=>L.gy+L.gh-L.gh*v/16;
    [[0,4.5,'var(--good)'],[4.5,6.5,'var(--warn)'],[6.5,16,'var(--bad)']].forEach(b=>{s+=`<rect x="${L.gx}" y="${f1(Ys(b[1]))}" width="${L.gw}" height="${f1(Ys(b[0])-Ys(b[1]))}" style="fill:${b[2]};opacity:.12"/>`});
    s+=`<text x="${L.gx+L.gw-4}" y="${f1(Ys(16)+12)}" class="t-xs t-end">high 7+</text><text x="${L.gx+L.gw-4}" y="${f1(Ys(6.5)+11)}" class="t-xs t-end">medium 5–6</text><text x="${L.gx+L.gw-4}" y="${f1(Ys(4.5)+11)}" class="t-xs t-end">low 0–4</text>`;
    s+=`<line x1="${L.gx}" x2="${L.gx+L.gw}" y1="${L.gy+L.gh}" y2="${L.gy+L.gh}" class="axis"/><line x1="${L.gx}" x2="${L.gx}" y1="${L.gy}" y2="${L.gy+L.gh}" class="axis"/>`;
    [0,2,4,6,8].forEach(h=>{s+=`<text x="${f1(Xh(h))}" y="${L.gy+L.gh+13}" class="t-xs t-mid">${h} h</text>`});
    [0,5,7,14].forEach(v=>{s+=`<text x="${L.gx-6}" y="${f1(Ys(v)+3)}" class="t-xs t-end">${v}</text>`});
    s+=`<text x="${L.gx}" y="${L.gy-6}" class="t-xs">NEWS2 total</text>`;
    const sc=h=>{let i=0;while(i<RC_OBS.length-1&&h>RC_OBS[i+1].h)i++;if(i>=RC_OBS.length-1)return RC_OBS[i].P.total;const a=RC_OBS[i],b=RC_OBS[i+1];return lerp(a.P.total,b.P.total,ramp(h,a.h,b.h))};
    let d='';for(let k=0;k<=60;k++){const h=hr*k/60;d+=(k?'L':'M')+f1(Xh(h))+' '+f1(Ys(sc(h)))}
    s+=`<path d="${d}" style="fill:none;stroke:var(--accent);stroke-width:2.6;stroke-linejoin:round"/>`;
    RC_OBS.forEach(o=>{if(hr>=o.h){const B=rcBand(o.P);s+=`<circle cx="${f1(Xh(o.h))}" cy="${f1(Ys(o.P.total))}" r="5" style="fill:${B.c};stroke:var(--panel);stroke-width:1.5"/><text x="${f1(Xh(o.h))}" y="${f1(Ys(o.P.total)-9)}" class="t-sm t-mid" style="fill:var(--ink);font-weight:600">${o.P.total}</text>`}});
    svg2.innerHTML=s;
    const cur=RC_OBS[Math.min(4,Math.floor(hr/2+.0001))],B=rcBand(cur.P);
    $('#rcNote2').innerHTML=noteHTML({k:st.k,t:st.h,txt:st.txt,pt:st.pt,hook:st.hook});
    $('#rcRead2').innerHTML=`<span>Hour <b>${cur.h}</b></span><span>NEWS2 <b>${cur.P.total}</b></span><span>Band <b>${B.l}</b></span>`;
    mark2(p)}
  const stop2=playWire(rg2,$('#rcPlay2'),draw2,12000,'Replay','recognise');
  const mark2=stepWire($('#rcSteps2'),RC_STEPS2,rg2,draw2,stop2);
  draw2(+rg2.value);

  /* ---------- 3. the NEWS2 teaching calculator ---------- */
  const F={rr:$('#rcRR'),sp:$('#rcSp'),scale:$('#rcScale'),o2:$('#rcO2'),sbp:$('#rcSBP'),hr:$('#rcHR'),avpu:$('#rcAvpu'),temp:$('#rcTemp')};
  const DEF={rr:18,sp:97,scale:'1',o2:'air',sbp:124,hr:82,avpu:'a',temp:37.2},EX={rr:23,sp:94,scale:'1',o2:'air',sbp:106,hr:112,avpu:'a',temp:38.9};
  const num=(el,d)=>{const v=parseFloat(el.value);return isFinite(v)?v:d};
  function calc(){
    const o={rr:num(F.rr,18),sp:num(F.sp,97),scale:+F.scale.value,o2:F.o2.value==='o2',sbp:num(F.sbp,124),hr:num(F.hr,82),conf:F.avpu.value==='c',temp:num(F.temp,37.2)};
    const P=rcPts(o),B=rcBand(P),si=o.sbp>0?o.hr/o.sbp:0;
    $('#rcRes').innerHTML=`<div><small>NEWS2 total</small><b>${P.total}</b></div><div><small>Clinical risk band</small><b style="color:${B.c}">${B.l}</b></div><div><small>Shock index (HR ÷ SBP)</small><b>${si.toFixed(2)}</b></div>`;
    const ch=[['Breathing',P.rr],['SpO₂ (scale '+o.scale+')',P.sp],[o.o2?'Oxygen':'Air',P.o2],['Systolic BP',P.bp],['Pulse',P.hr],['Consciousness',P.cn],['Temperature',P.te]];
    $('#rcPts').innerHTML=ch.map(c=>`<span class="p${c[1]}">${c[0]}: <b>${c[1]}</b></span>`).join('');
    const why=B.k==='lm'?`The total is in the low range, but one observation scores 3 on its own, which the chart treats as low-medium risk.`:B.k==='high'?`A total of 7 or more is the high band on the NEWS2 chart.`:B.k==='med'?`A total of 5 or 6 is the medium band.`:`A total of 0 to 4, with no single 3, is the low band.`;
    const siTxt=si>=1?`A shock index of 1.0 or more was the most specific cut-off in Berger's pilot.`:si>=.7?`A shock index of 0.7 or more was linked with a raised lactate (≥4 mmol/L) about three times as often as below 0.7 in Berger's pilot.`:`Below 0.7, the shock index sat under the lower cut-off studied by Berger.`;
    $('#rcCalcNote').innerHTML=noteHTML({k:'Teaching calculator',t:`NEWS2 ${P.total}: ${B.l.toLowerCase()} band`,
      txt:`${why} <sup class="c" data-ref="Verma2023NEWS2" title="Source 493"><a href="/sepsis-and-shock/sources/#src-Verma2023NEWS2">493</a></sup> ${siTxt} <sup class="c" data-ref="Berger2013SI" title="Source 54"><a href="/sepsis-and-shock/sources/#src-Berger2013SI">54</a></sup>${o.scale===2?' Scale 2 is only for patients with hypercapnic respiratory failure confirmed on a blood gas. <sup class="c" data-ref="Verma2023NEWS2" title="Source 493"><a href="/sepsis-and-shock/sources/#src-Verma2023NEWS2">493</a></sup>':''}`,
      pt:`This shows how the chart adds up points. It cannot tell you whether a person has sepsis. If someone seems very unwell, get medical help now, whatever the number.`,
      hook:`NEWS2: 0–4 low, 5–6 medium, ≥7 high; any single 3 = low-medium.`})}
  function load(v){Object.keys(v).forEach(k=>{F[k].value=v[k]});calc()}
  Object.values(F).forEach(el=>{el.addEventListener('input',calc);el.addEventListener('change',calc)});
  $('#rcEx').addEventListener('click',()=>load(EX));$('#rcReset').addEventListener('click',()=>load(DEF));
  calc();
};
/* ===== 3.1 Definitions & scores: SIRS to Sepsis-3 ===== */
const DF_STEPS=[
 {from:0,at:.07,yr:1992,t:'Sepsis-1',k:'1991 conference · 1992',h:'Sepsis-1: infection plus SIRS',
  txt:`The ACCP/SCCM conference defined SIRS (2 or more of: temperature &gt;38 or &lt;36°C, heart rate &gt;90, respiratory rate &gt;20 or PaCO₂ &lt;32 mmHg, white count &gt;12,000, &lt;4,000 or &gt;10% bands). Sepsis = infection + SIRS; severe sepsis = sepsis + organ dysfunction; septic shock = sepsis-induced hypotension despite fluids. <sup class="c" data-ref="Bone1992SIRS,Song2018qSOFA,Kaukonen2015" title="Source 60,224,455"><a href="/sepsis-and-shock/sources/#src-Bone1992SIRS">60,224,455</a></sup>`,
  pt:`The first definition looked for signs of inflammation, such as fever and a fast pulse, in someone with an infection. Each stage was seen as a step on a staircase.`,
  hook:`SIRS = 2 of 4: temperature, heart rate, respiratory rate (or PaCO₂), white count.`},
 {from:.15,at:.21,yr:2003,t:'Sepsis-2',k:'2001 conference · 2003',h:'Sepsis-2: no change in the core definition',
  txt:`29 participants from five societies found that "apart from expanding the list of signs and symptoms of sepsis… no evidence exists to support a change to the definitions". They proposed PIRO (predisposition, infection, response, organ dysfunction) as "a hypothesis-generating model for future research". <sup class="c" data-ref="Levy2003Sepsis2" title="Source 259"><a href="/sepsis-and-shock/sources/#src-Levy2003Sepsis2">259</a></sup>`,
  pt:`Ten years later, experts kept the same definition but added more possible signs to the list.`,
  hook:`Sepsis-2 (2001/2003) expanded the signs list; PIRO was a research hypothesis.`},
 {from:.29,at:.36,yr:2015,t:'One in eight',k:'Kaukonen 2015',h:'The crack: one in eight missed',
  txt:`In 109,663 ICU patients with infection and organ failure, 12.1% did not meet 2 SIRS criteria. Their mortality fell over 2000–2013 just as it did in SIRS-positive patients (27.7% to 9.3%, against 36.1% to 18.3%). Each extra SIRS criterion raised the odds of death by 1.13, with no step at 2. <sup class="c" data-ref="Kaukonen2015" title="Source 224"><a href="/sepsis-and-shock/sources/#src-Kaukonen2015">224</a></sup>`,
  pt:`A large study found that 1 in 8 very sick people with infection and failing organs would have been missed by the SIRS rule.`,
  hook:`Kaukonen 2015: 1 in 8 with infection and organ failure is SIRS-negative.`},
 {from:.43,at:.5,yr:2016,t:'Sepsis-3',k:'Sepsis-3 · 2016',h:'Sepsis-3: organ dysfunction',
  txt:`"Sepsis should be defined as life-threatening organ dysfunction caused by a dysregulated host response to infection." Organ dysfunction is an acute SOFA rise of 2 or more, linked with in-hospital mortality above 10%. "Severe sepsis" was dropped as redundant, and qSOFA was offered as a bedside prompt. <sup class="c" data-ref="Singer2016Sepsis3,Seymour2016qSOFA" title="Source 435,448"><a href="/sepsis-and-shock/sources/#src-Singer2016Sepsis3">435,448</a></sup>`,
  pt:`Since 2016, sepsis means an infection that is damaging the body's organs because of the way the body reacts to it.`,
  hook:`Sepsis-3: infection + acute SOFA ≥2. "Severe sepsis" no longer exists.`},
 {from:.57,at:.64,yr:2016,t:'Septic shock',k:'Sepsis-3 · 2016',h:'Septic shock: pressure and lactate',
  txt:`Septic shock is a subset of sepsis with profound circulatory, cellular and metabolic abnormalities. Criteria: a vasopressor needed to keep MAP at 65 mmHg or more and a lactate above 2 mmol/L despite adequate fluids. Hospital mortality is above 40%; in the SSC database this group had 42.3%. <sup class="c" data-ref="Singer2016Sepsis3,ShankarHari2016Shock" title="Source 441,448"><a href="/sepsis-and-shock/sources/#src-Singer2016Sepsis3">441,448</a></sup>`,
  pt:`Septic shock is the most serious form: blood pressure stays low even after fluids, so medicines are needed to raise it, and the body's cells are struggling.`,
  hook:`Septic shock = vasopressor for MAP ≥65 + lactate &gt;2 mmol/L despite fluids.`},
 {from:.72,at:.78,yr:2024,t:'Phoenix',k:'Children · 2024',h:'Phoenix criteria for children',
  txt:`Sepsis-3 excluded children. The 2024 Phoenix criteria define sepsis in children under 18 as suspected infection with a Phoenix Sepsis Score of 2 or more, from four systems: respiratory, cardiovascular, coagulation and neurological. Septic shock is sepsis with at least 1 cardiovascular point. <sup class="c" data-ref="Schlapbach2024Phoenix" title="Source 419"><a href="/sepsis-and-shock/sources/#src-Schlapbach2024Phoenix">419</a></sup>`,
  pt:`Children now have their own definition, built from more than 3 million hospital records.`,
  hook:`Phoenix: suspected infection + score ≥2; shock = ≥1 cardiovascular point.`},
 {from:.86,at:.93,yr:2025,t:'SOFA-2',k:'SOFA-2 · 2025',h:'SOFA-2: the score is updated',
  txt:`SOFA-2 keeps six systems with revised thresholds and modern support (high-flow oxygen, ECMO, more vasopressors, kidney replacement therapy, delirium treatment). AUROC 0.79 against 0.77 for SOFA. Sepsis-3 is still defined with the original SOFA. <sup class="c" data-ref="Ranzani2025SOFA2,Lobo2025SOFA2" title="Source 268,384"><a href="/sepsis-and-shock/sources/#src-Ranzani2025SOFA2">268,384</a></sup>`,
  pt:`The organ score behind the definition was updated in 2025. Whether the sepsis definition itself will switch to it is not yet settled.`,
  hook:`SOFA-2 (2025): 6 systems, revised thresholds; Sepsis-3 still uses SOFA-1.`}];
/* SOFA points as tabulated by Lambden 2019 (modified from Vincent 1996) */
const DF_SOFA=[
 {k:'resp',n:'Respiratory',u:'PaO₂/FiO₂ (mmHg)',o:['&gt;400','&lt;400','&lt;300','&lt;200 with respiratory support','&lt;100 with respiratory support']},
 {k:'coag',n:'Coagulation',u:'Platelets (×10³/µL)',o:['&gt;150','&lt;150','&lt;100','&lt;50','&lt;20']},
 {k:'liver',n:'Liver',u:'Bilirubin, mg/dL [µmol/L]',o:['&lt;1.2 [&lt;20]','1.2–1.9 [20–32]','2.0–5.9 [33–101]','6.0–11.9 [102–204]','&gt;12.0 [&gt;204]']},
 {k:'cv',n:'Cardiovascular',u:'MAP or vasopressors (µg/kg/min)',o:['MAP &gt;70 mmHg','MAP &lt;70 mmHg','Dopamine ≤5 or dobutamine (any dose)','Dopamine &gt;5, adrenaline ≤0.1 or noradrenaline ≤0.1','Dopamine &gt;15, adrenaline &gt;0.1 or noradrenaline &gt;0.1']},
 {k:'cns',n:'Nervous system',u:'Glasgow Coma Scale',o:['15','13–14','10–12','6–9','&lt;6']},
 {k:'renal',n:'Kidneys',u:'Creatinine, mg/dL [µmol/L], or urine output',o:['&lt;1.2 [&lt;110]','1.2–1.9 [110–170]','2.0–3.4 [171–299]','3.5–4.9 [300–440] or urine &lt;500 ml/day','&gt;5.0 [&gt;440] or urine &lt;200 ml/day']}];
const DF_SOFA_EX=[2,2,1,3,1,2];
const DF_TOOLS={sirs:{n:'SIRS ≥2',sens:88.1,spec:25.8},qsofa:{n:'qSOFA ≥2',sens:60.8,spec:72.0}};
const DF_AUC=[{g:'Outside the ICU',v:[['qSOFA',.81],['SOFA',.79],['SIRS',.76]]},{g:'Inside the ICU',v:[['SOFA',.74],['qSOFA',.66],['SIRS',.64]]}];
function dfBox(x,y,w,h,lab,o={}){const on=o.on,op=o.op==null?1:o.op;return `<g style="opacity:${f1(op)}"><rect x="${f1(x)}" y="${f1(y)}" width="${f1(w)}" height="${f1(h)}" rx="10" style="fill:${on?'var(--dx-soft)':'var(--panel)'};stroke:${o.col||(on?'var(--dx)':'var(--line)')};stroke-width:${on?1.6:1}"/><text x="${f1(x+w/2)}" y="${f1(y+h/2+(o.sub?-2:4))}" class="t-lbl t-mid">${lab}</text>${o.sub?`<text x="${f1(x+w/2)}" y="${f1(y+h/2+13)}" class="t-xs t-mid">${o.sub}</text>`:''}${o.x?`<line x1="${f1(x+6)}" y1="${f1(y+h-6)}" x2="${f1(x+w-6)}" y2="${f1(y+6)}" style="stroke:var(--bad);stroke-width:2.6"/>`:''}</g>`}
inits.definitions=()=>{
  /* ---------- 1. the timeline ---------- */
  const svg=$('#dfSvg'),rg=$('#dfT');
  function draw(t){
    const N=vb(svg,'720 380','400 600'),p=phaseOf(DF_STEPS,t),st=DF_STEPS[p],nx=p<DF_STEPS.length-1?DF_STEPS[p+1].from:1.0001,lp=ease(ramp(t,st.from,st.from+(nx-st.from)*.5));
    const W=N?400:720,ax0=N?24:40,ax1=W-(N?24:40),ay=50,X=y=>ax0+(ax1-ax0)*(y-1990)/36;
    const P=N?{x:12,y:96,w:376,h:490}:{x:20,y:92,w:680,h:276};
    let s=`<defs>${marker('dfA','var(--muted)')}</defs><text x="${ax0}" y="24" class="t-big" style="fill:var(--dx)">${st.h}</text>`;
    s+=`<line x1="${ax0}" x2="${ax1}" y1="${ay}" y2="${ay}" class="axis"/>`;
    [1990,2000,2010,2020].forEach(y=>{s+=`<text x="${f1(X(y))}" y="${ay+16}" class="t-xs t-mid">${y}</text><line x1="${f1(X(y))}" x2="${f1(X(y))}" y1="${ay-3}" y2="${ay+3}" class="axis"/>`});
    DF_STEPS.forEach((m,i)=>{const on=i===p,done=i<=p,x=X(m.yr)+(i===4?0:0);
      s+=`<circle cx="${f1(x)}" cy="${ay}" r="${on?7:4.5}" style="fill:${done?'var(--dx)':'var(--panel)'};stroke:var(--dx);stroke-width:1.5"/>`;
      if(on)s+=`<text x="${f1(clamp(x,ax0+30,ax1-30))}" y="${ay-12}" class="t-sm t-mid" style="fill:var(--ink);font-weight:600">${m.yr} · ${m.t}</text>`});
    s+=`<rect x="${P.x}" y="${P.y}" width="${P.w}" height="${P.h}" rx="12" style="fill:var(--field);stroke:var(--line)"/>`;
    const cx=P.x+P.w/2;
    if(p<=1){/* the staircase */
      const labs=[['Infection',''],['Sepsis','infection + ≥2 SIRS'],['Severe sepsis','+ organ dysfunction'],['Septic shock','+ hypotension despite fluids']];
      const n=4,bw=N?P.w-120:150,bh=N?52:46;
      labs.forEach((l,i)=>{const bx=N?P.x+16+i*30:P.x+20+i*(bw+14),by=N?P.y+P.h-80-i*(bh+30):P.y+P.h-60-i*52;
        s+=dfBox(bx,by,bw,bh,l[0],{sub:l[1],on:i===1,op:p===1?1:ramp(lp,i*.2,i*.2+.3)});
        if(i<3)s+=N?`<path d="M${bx+bw/2} ${by-2}v-24" style="stroke:var(--muted);stroke-width:1.3;marker-end:url(#dfA);opacity:${f1(p===1?1:ramp(lp,i*.2+.2,i*.2+.4))}"/>`:`<path d="M${bx+bw/2} ${by-2}C${bx+bw/2} ${by-22} ${bx+bw+20} ${by-24} ${bx+bw+40} ${by-10}" style="fill:none;stroke:var(--muted);stroke-width:1.3;marker-end:url(#dfA);opacity:${f1(p===1?1:ramp(lp,i*.2+.2,i*.2+.4))}"/>`});
      const chips=['T &gt;38 or &lt;36°C','HR &gt;90','RR &gt;20','WCC &gt;12k / &lt;4k'];
      chips.forEach((c,i)=>{const cw=N?84:110,cx0=N?P.x+12+i*(cw+6):P.x+P.w-4*(cw+8)+i*(cw+8),cy0=P.y+14;
        s+=`<rect x="${cx0}" y="${cy0}" width="${cw}" height="24" rx="12" style="fill:var(--panel);stroke:var(--dx);opacity:${f1(p===1?.6:ramp(lp,.1,.4))}"/><text x="${cx0+cw/2}" y="${cy0+16}" class="t-xs t-mid" style="fill:var(--ink)">${c}</text>`});
      s+=`<text x="${N?P.x+12:P.x+P.w-4*118}" y="${P.y+54}" class="t-xs">SIRS: any 2 of 4</text>`;
      if(p===1){const L=['P','I','R','O'],W2=['Predisposition','Infection','Response','Organ dysfunction'];L.forEach((c,i)=>{const px=N?P.x+12+(i%2)*180:P.x+30,py=N?P.y+64+Math.floor(i/2)*26:P.y+70+i*28;
        s+=`<g style="opacity:${f1(ramp(lp,i*.15,i*.15+.3))}"><text x="${px}" y="${py+14}" class="t-big" style="fill:var(--rx)">${c}</text><text x="${px+18}" y="${py+13}" class="t-xs">${W2[i]}</text></g>`});
        s+=`<text x="${N?P.x+12:P.x+30}" y="${P.y+(N?130:190)}" class="t-xs" style="fill:var(--rx)">PIRO: a hypothesis</text>`}}
    if(p===2){/* the SIRS gate */
      const gx=N?cx:P.x+P.w*.55,gy=N?P.y+70:P.y+30,gh=N?300:P.h-90;
      s+=`<rect x="${gx-8}" y="${gy}" width="16" height="${gh}" rx="4" style="fill:var(--dx)"/><text x="${gx}" y="${gy-8}" class="t-sm t-mid" style="fill:var(--ink);font-weight:600">≥2 SIRS?</text>`;
      for(let i=0;i<8;i++){const miss=i===5,x0=N?P.x+30:P.x+40,yy=gy+6+i*(gh-10)/8;
        let x=lerp(x0,gx+(N?120:200),ramp(lp,i*.05,.6+i*.05)),y=yy;
        if(miss&&x>gx-30){x=gx-30;y=lerp(yy,gy+gh+4,ramp(lp,.55,.9))}
        s+=person(x,y,Math.min(18,(gh-10)/8-3),miss?'var(--muted)':'var(--dx)')}
      s+=N?`<text x="${P.x+16}" y="${P.y+P.h-34}" class="t-sm" style="fill:var(--ink)">1 in 8 (12.1%) with infection and</text><text x="${P.x+16}" y="${P.y+P.h-18}" class="t-sm" style="fill:var(--ink)">organ failure were SIRS-negative</text>`:`<text x="${P.x+40}" y="${P.y+P.h-20}" class="t-sm" style="fill:var(--ink)">1 in 8 (12.1%) with infection and organ failure were SIRS-negative</text>`}
    if(p===3||p===4){/* nested sets */
      const ex=N?cx:P.x+P.w*.4,ey=N?P.y+190:P.y+P.h/2,R=N?170:150,sc=p===3?ease(lp):1;
      s+=`<ellipse cx="${ex}" cy="${ey}" rx="${f1(R*sc)}" ry="${f1(R*.78*sc)}" style="fill:var(--panel);stroke:var(--muted);stroke-width:1.4"/><text x="${ex}" y="${f1(ey-R*.78*sc+20)}" class="t-lbl t-mid">Infection</text>`;
      s+=`<ellipse cx="${ex}" cy="${f1(ey+R*.14)}" rx="${f1(R*.66*sc)}" ry="${f1(R*.5*sc)}" style="fill:var(--dx-soft);stroke:var(--dx);stroke-width:1.6;opacity:${f1(ramp(lp,p===3?.3:0,p===3?.6:.01))}"/><text x="${ex}" y="${f1(ey-R*.2)}" class="t-lbl t-mid" style="fill:var(--dx);opacity:${f1(p===4?1:ramp(lp,.4,.7))}">Sepsis</text><text x="${ex}" y="${f1(ey-R*.2+14)}" class="t-xs t-mid" style="opacity:${f1(p===4?1:ramp(lp,.4,.7))}">acute SOFA rise ≥2</text>`;
      const so=p===4?1:ramp(lp,.6,.9);
      s+=`<ellipse cx="${ex}" cy="${f1(ey+R*.34)}" rx="${f1(R*.34)}" ry="${f1(R*.22)}" style="fill:${p===4?'var(--bad-soft)':'var(--panel)'};stroke:var(--bad);stroke-width:${p===4?2.2:1.4};opacity:${f1(so)}"/><text x="${ex}" y="${f1(ey+R*.36)}" class="t-sm t-mid" style="fill:var(--bad);font-weight:600;opacity:${f1(so)}">Septic shock</text>`;
      if(p===3){const bx=N?P.x+P.w-150:P.x+P.w-190,by=N?P.y+P.h-70:P.y+40;s+=dfBox(bx,by,N?140:160,44,'Severe sepsis',{sub:'dropped as redundant',x:ramp(lp,.7,1)>0,op:1})}
      if(p===4){const qx=N?P.x+20:P.x+P.w-230,qy=N?P.y+P.h-120:P.y+40;
        s+=`<g style="opacity:${f1(lp)}">`+pump(qx,qy,90,70,{v:lp,txt:'MAP ≥65',on:true,col:'var(--rx)'}).svg+`<text x="${qx+45}" y="${qy+86}" class="t-xs t-mid">vasopressor needed</text>`;
        s+=lactateMeter(qx+(N?280:150),qy-6,20,90,2+lp*2,8,{bands:[{from:2,to:8,col:'var(--lactate)',label:'&gt;2'}],val:true,unit:'mmol/L'})+`<text x="${qx+(N?240:120)}" y="${qy+118}" class="t-xs">despite adequate fluids</text></g>`}}
    if(p===5){/* Phoenix */
      const bx=N?P.x+90:P.x+150,by=N?P.y+24:P.y+20,bs=N?.85:.9;
      const B=body(bx,by,bs,{id:'dfB',organs:true,fail:{brain:.0,lung:.0,heart:0}});s+=B.svg;
      const sys=[['Respiratory','0–3',B.at.lung],['Cardiovascular','0–6',B.at.heart],['Coagulation','0–2',B.at.arm],['Neurological','0–2',B.at.brain]];
      sys.forEach((q,i)=>{const op=ramp(lp,i*.15,i*.15+.3),tx=N?P.x+200:P.x+330,ty=(N?P.y+60:P.y+50)+i*(N?62:50);
        s+=`<g style="opacity:${f1(op)}"><circle cx="${f1(q[2][0])}" cy="${f1(q[2][1])}" r="14" style="fill:var(--dx);opacity:.22"/><path d="M${f1(q[2][0]+14)} ${f1(q[2][1])}L${tx-8} ${ty-4}" style="stroke:var(--dx);stroke-width:1;stroke-dasharray:3 3;fill:none"/><text x="${tx}" y="${ty}" class="t-lbl">${q[0]}</text><text x="${tx}" y="${ty+14}" class="t-xs">${q[1]} points</text></g>`});
      s+=`<text x="${N?P.x+16:P.x+330}" y="${N?P.y+P.h-24:P.y+P.h-30}" class="t-sm" style="fill:var(--ink);opacity:${f1(ramp(lp,.6,.9))}">suspected infection + score ≥2 = sepsis</text>`}
    if(p===6){const T=[['Brain','delirium treatment'],['Respiratory','SpO₂/FiO₂, high-flow, ECMO'],['Cardiovascular','more vasopressors, MCS'],['Liver','revised thresholds'],['Kidney','kidney replacement therapy'],['Haemostasis','revised thresholds']];
      const cols=N?2:3,tw=N?(P.w-36)/2:(P.w-60)/3,th=N?100:90;
      T.forEach((q,i)=>{const tx=P.x+12+(i%cols)*(tw+12),ty=P.y+(N?20:24)+Math.floor(i/cols)*(th+14);s+=dfBox(tx,ty,tw,th,q[0],{sub:q[1],on:ramp(lp,i*.1,i*.1+.3)>.5,op:.3+.7*ramp(lp,i*.1,i*.1+.3)})});
      s+=`<text x="${P.x+12}" y="${P.y+P.h-14}" class="t-sm" style="fill:var(--ink)">AUROC SOFA-2 0.79 vs SOFA 0.77</text>`}
    svg.innerHTML=s;
    $('#dfNote').innerHTML=noteHTML({k:st.k,t:st.h,txt:st.txt,pt:st.pt,hook:st.hook});
    $('#dfRead').innerHTML=`<span>Year <b>${st.yr}</b></span><span>Milestone <b>${p+1}</b> of ${DF_STEPS.length}</span>`;
    mark(p)}
  const stop=playWire(rg,$('#dfPlay'),draw,18000,'Replay','definitions');
  const mark=stepWire($('#dfSteps'),DF_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---------- 2. qSOFA ---------- */
  const qrr=$('#dfQrr'),qsbp=$('#dfQsbp'),qmen=$('#dfQmen');
  function qcalc(){const rr=+qrr.value||0,sb=+qsbp.value||0,a=rr>=22?1:0,b=sb<=100&&sb>0?1:0,c=qmen.checked?1:0,tot=a+b+c;
    $('#dfQres').innerHTML=`<div><small>qSOFA</small><b>${tot} / 3</b></div><div><small>Respiratory rate ≥22</small><b>${a}</b></div><div><small>Systolic ≤100</small><b>${b}</b></div><div><small>Altered mentation</small><b>${c}</b></div>`;
    $('#dfQnote').innerHTML=noteHTML({k:'Teaching calculator',t:tot>=2?'qSOFA 2 or more: positive':'qSOFA below 2',
      txt:tot>=2?`In the derivation data, a qSOFA of 2 or more meant a 3- to 14-fold higher hospital mortality than below 2, across baseline-risk deciles. Sepsis-3 framed it as a prompt "to consider possible sepsis", not a diagnosis. <sup class="c" data-ref="Seymour2016qSOFA" title="Source 435"><a href="/sepsis-and-shock/sources/#src-Seymour2016qSOFA">435</a></sup>`:`A low qSOFA does not rule sepsis out: pooled sensitivity for death was only 60.8%, and outside the ICU 51.2%. SSC 2021 recommends against using qSOFA as a single screening tool. <sup class="c" data-ref="Fernando2018,Evans2021SSC" title="Source 134,141"><a href="/sepsis-and-shock/sources/#src-Fernando2018">134,141</a></sup>`,
      pt:`This only shows how the three items add up. A low number does not mean someone is safe. If someone seems very unwell with an infection, get medical help now.`,
      hook:`qSOFA: RR ≥22, altered mentation, SBP ≤100; ≥2 = positive.`})}
  [qrr,qsbp,qmen].forEach(e=>{e.addEventListener('input',qcalc);e.addEventListener('change',qcalc)});qcalc();

  /* ---------- 3. SIRS vs qSOFA ---------- */
  const cmp=$('#dfCmp');let tool='sirs';
  function dcmp(){const N=vb(cmp,'720 300','400 540'),T=DF_TOOLS[tool],k1=Math.round(T.sens),k2=Math.round(100-T.spec);
    const A=N?{x1:24,x2:212,y:46,bx:110,by:290,bw:250}:{x1:24,x2:214,y:46,bx:520,by:46,bw:170};
    let s=`<text x="${A.x1}" y="30" class="t-sm" style="fill:var(--ink);font-weight:600">100 who died: ${k1} flagged</text><text x="${A.x2}" y="30" class="t-sm" style="fill:var(--ink);font-weight:600">100 who survived: ${k2} flagged</text>`;
    s+=icons(A.x1,A.y,{n:100,cols:10,k:k1,size:12,gap:3,col:'var(--dx)',shape:'dot'}).svg+icons(A.x2,A.y,{n:100,cols:10,k:k2,size:12,gap:3,col:'var(--warn)',shape:'dot'}).svg;
    s+=`<text x="${A.x1}" y="${A.y+186}" class="t-xs">sensitivity ${T.sens}%</text><text x="${A.x2}" y="${A.y+186}" class="t-xs">false alarms (1 − specificity ${T.spec}%)</text>`;
    s+=`<text x="${N?24:A.bx-110}" y="${A.by-14}" class="t-sm" style="fill:var(--ink);font-weight:600">AUROC, in-hospital death (2016)</text>`;
    let y=A.by;DF_AUC.forEach(g=>{s+=`<text x="${N?24:A.bx-110}" y="${y+6}" class="t-xs">${g.g}</text>`;y+=12;
      g.v.forEach(v=>{const hl=(tool==='sirs'&&v[0]==='SIRS')||(tool==='qsofa'&&v[0]==='qSOFA'),w=A.bw*(v[1]-.5)/.4;
        s+=`<text x="${A.bx-8}" y="${y+10}" class="t-xs t-end">${v[0]}</text><rect x="${A.bx}" y="${y}" width="${f1(w)}" height="13" rx="3" style="fill:${hl?'var(--dx)':'var(--line)'}"/><text x="${f1(A.bx+w+5)}" y="${y+10}" class="t-xs">${v[1].toFixed(2)}</text>`;y+=18});y+=14});
    s+=`<text x="${A.bx}" y="${y}" class="t-xs">bars start at 0.5 (chance)</text>`;
    cmp.innerHTML=s;$('#dfCmpRead').innerHTML=`<span>Tool <b>${T.n}</b></span><span>Sensitivity <b>${T.sens}%</b></span><span>Specificity <b>${T.spec}%</b></span>`}
  $('#dfTog').addEventListener('click',e=>{const b=e.target.closest('[data-tool]');if(!b)return;tool=b.dataset.tool;$$('#dfTog [data-tool]').forEach(x=>x.setAttribute('aria-pressed',x===b));dcmp()});
  redraws.definitions=(()=>{const prev=redraws.definitions;return()=>{prev&&prev();dcmp();scalc()}})();
  dcmp();

  /* ---------- 4. SOFA ---------- */
  const box=$('#dfSofa');
  box.innerHTML=DF_SOFA.map(r=>`<label for="dfS_${r.k}">${r.n} <span class="stage-cap">${r.u}</span><select id="dfS_${r.k}">${r.o.map((o,i)=>`<option value="${i}">${i} · ${o}</option>`).join('')}</select></label>`).join('');
  const sels=DF_SOFA.map(r=>$('#dfS_'+r.k)),base=$('#dfBase'),ssvg=$('#dfSsvg');
  function scalc(){const v=sels.map(s=>+s.value),tot=v.reduce((a,b)=>a+b,0),b0=clamp(+base.value||0,0,24),d=tot-b0;
    $('#dfSres').innerHTML=`<div><small>SOFA total</small><b>${tot} / 24</b></div><div><small>Change from baseline</small><b>${d>0?'+':''}${d}</b></div><div><small>Sepsis-3 organ criterion</small><b style="font-size:20px">${d>=2?'Rise ≥2':'Not met'}</b></div>`;
    const N=vb(ssvg,'720 120','400 200');let s='';
    DF_SOFA.forEach((r,i)=>{const cols=N?2:6,cw=N?184:112,x=8+(i%cols)*(cw+(N?12:6)),y=N?8+Math.floor(i/2)*62:14;
      s+=`<text x="${x}" y="${y+10}" class="t-xs">${r.n}</text>`;for(let k=0;k<4;k++)s+=`<rect x="${x+k*(cw/4)}" y="${y+18}" width="${f1(cw/4-3)}" height="22" rx="4" style="fill:${k<v[i]?(v[i]>=3?'var(--organ-fail)':'var(--dx)'):'var(--panel-2)'}"/>`;
      s+=`<text x="${x}" y="${y+54}" class="t-xs" style="fill:var(--ink)">${v[i]} point${v[i]===1?'':'s'}</text>`});
    ssvg.innerHTML=s;
    $('#dfSnote').innerHTML=noteHTML({k:'Teaching calculator',t:`SOFA ${tot}, change ${d>0?'+':''}${d}`,
      txt:`${d>=2?'An acute rise of 2 points or more, in someone with infection, is the Sepsis-3 marker of organ dysfunction, associated with in-hospital mortality above 10%. <sup class="c" data-ref="Singer2016Sepsis3" title="Source 448"><a href="/sepsis-and-shock/sources/#src-Singer2016Sepsis3">448</a></sup>':'Sepsis-3 uses an acute rise of 2 points or more from baseline, in someone with infection, as its marker of organ dysfunction. <sup class="c" data-ref="Singer2016Sepsis3" title="Source 448"><a href="/sepsis-and-shock/sources/#src-Singer2016Sepsis3">448</a></sup>'} The direction over time carries information too: in Ferreira 2001, mortality was at least 50% when SOFA rose over the first 96 hours and below 27% when it fell (population statistics). <sup class="c" data-ref="Ferreira2001SOFA" title="Source 143"><a href="/sepsis-and-shock/sources/#src-Ferreira2001SOFA">143</a></sup>`,
      pt:`SOFA adds up how much six organs are struggling. It is a tool for intensive care teams; it cannot tell what will happen to one person.`,
      hook:`SOFA: 6 systems × 0–4 = 0–24. Sepsis = infection + acute rise ≥2.`})}
  sels.forEach(s=>s.addEventListener('change',scalc));base.addEventListener('input',scalc);
  $('#dfSex').addEventListener('click',()=>{sels.forEach((s,i)=>s.value=DF_SOFA_EX[i]);base.value=0;scalc()});
  $('#dfSreset').addEventListener('click',()=>{sels.forEach(s=>s.value=0);base.value=0;scalc()});
  scalc();
};
/* =============== 3.2 Lactate, cultures, procalcitonin & tests =============== */
const TS_STEPS=[
 {from:0,at:.1,k:'Step 1 · the usual route',t:'Oxygen in, little lactate',
  txt:`Cells get energy from glucose. Glycolysis splits it into pyruvate, which the cell normally burns using oxygen, and only a little leaves as lactate. The drawing is schematic: a muscle cell under a capillary, with the blood lactate tube on the right. Lactate is a marker of how stressed the cells are, and its causes are debated. <sup class="c" data-ref="GarciaAlvarez2014" title="Source 164"><a href="/sepsis-and-shock/sources/#src-GarciaAlvarez2014">164</a></sup>`,
  pt:`Lactate is a chemical in the blood. A little is always there. A high level can mean the body's tissues are struggling, and higher levels go with more serious illness.`},
 {from:.2,at:.32,k:'Step 2 · the classic view',t:'Too little oxygen',
  txt:`When blood flow and oxygen delivery fall, more pyruvate is turned into lactate (anaerobic glycolysis) and blood lactate rises. The ESICM task force defines circulatory shock as "a life-threatening, generalized form of acute circulatory failure associated with inadequate oxygen utilization by the cells", with cellular dysoxia and raised lactate. Lactate is "typically >2 mEq/L (or mmol/L) in shock states". <sup class="c" data-ref="Cecconi2014ESICM" title="Source 85"><a href="/sepsis-and-shock/sources/#src-Cecconi2014ESICM">85</a></sup>`,
  pt:`When blood flow is poor, cells run short of oxygen and make more lactate, so the level in the blood rises.`,
  hook:`Shock is defined by inadequate cellular oxygen use, not by low blood pressure alone. Lactate is typically above 2 mmol/L. <sup class="c" data-ref="Cecconi2014ESICM" title="Source 85"><a href="/sepsis-and-shock/sources/#src-Cecconi2014ESICM">85</a></sup>`},
 {from:.4,at:.52,k:'Step 3 · a stress signal too',t:'Adrenaline makes lactate',
  txt:`James and colleagues (1999) proposed that much of the lactate in injury or sepsis comes from aerobic glycolysis in skeletal muscle, driven by adrenaline acting on the Na⁺/K⁺ pump, rather than from oxygen debt <span class="ev hyp">Hypothesis</span>, since supported. In thigh muscle of 14 people in septic shock, microdialysis found muscle lactate a mean 1.98 mmol/L above arterial lactate. Ouabain, a Na⁺/K⁺-ATPase blocker, stopped the excess, and the lactate-to-pyruvate ratio did not change. A 2014 review concluded that stress-driven aerobic glycolysis explains sepsis-associated hyperlactataemia better than hypoxia alone <span class="ev est">Established</span> as a marker; the mechanism is still debated. <sup class="c" data-ref="James1999Lactate,Levy2005Lactate,GarciaAlvarez2014" title="Source 164,214,260"><a href="/sepsis-and-shock/sources/#src-James1999Lactate">164,214,260</a></sup>`,
  pt:`Stress hormones such as adrenaline make muscles burn sugar faster, and this also raises lactate, even when there is enough oxygen. So a high lactate is a warning sign, but it does not always mean the body is short of oxygen.`,
  hook:`High lactate in resuscitated sepsis is not proof of oxygen debt: adrenaline-driven Na⁺/K⁺-ATPase activity in muscle makes lactate too, and ouabain abolishes it. <sup class="c" data-ref="Levy2005Lactate" title="Source 260"><a href="/sepsis-and-shock/sources/#src-Levy2005Lactate">260</a></sup>`},
 {from:.6,at:.72,k:'Step 4 · what the number predicts',t:'Higher lactate, higher risk',
  txt:`In 1,278 admitted ED patients with infection, in-hospital mortality was 4.9% at a venous lactate of 0–2.5 mmol/L, 9.0% at 2.5–4.0 and 28.4% at 4.0 or more. A lactate of 4.0 or more was 36% sensitive and 92% specific for death. In 830 ED adults with severe sepsis, intermediate and high lactate were linked to mortality independent of shock. In the SSC database (28,150 patients), mortality was 44.5% with lactate above 4 mmol/L plus hypotension, against 29% with neither. SSC 2021 suggests measuring lactate in adults with suspected sepsis (weak, low quality), but lactate "alone is neither sensitive nor specific enough to rule-in or rule-out the diagnosis on its own". <sup class="c" data-ref="Shapiro2005Lactate,Mikkelsen2009Lactate,Casserly2015Lactate,Evans2021SSC" title="Source 84,134,298,444"><a href="/sepsis-and-shock/sources/#src-Shapiro2005Lactate">84,134,298,444</a></sup>`,
  pt:`On average, a higher lactate goes with more serious illness. These are figures for large groups of patients, not a prediction for any one person.`,
  hook:`Sepsis-3 septic shock = a vasopressor needed for MAP ≥65 mm Hg AND lactate >2 mmol/L (>18 mg/dL) without hypovolaemia; hospital mortality above 40%. <sup class="c" data-ref="Singer2016Sepsis3" title="Source 448"><a href="/sepsis-and-shock/sources/#src-Singer2016Sepsis3">448</a></sup>`},
 {from:.8,at:.9,k:'Step 5 · watching it fall',t:'Lactate as a guide',
  txt:`SSC 2021 suggests guiding resuscitation to decrease serum lactate when it is raised (weak, low quality). In the LACTATE trial (348 ICU patients) the target was a fall of 20% or more every 2 h for 8 h: hospital mortality was 33.9% against 43.5% (P = 0.067; adjusted HR 0.61). Jones 2010 found lactate clearance of at least 10% noninferior to an ScvO₂ target (17% vs 23% mortality). ANDROMEDA-SHOCK compared capillary refill targeting with lactate targeting: 34.9% vs 43.4% at 28 days, not significant (P = .06). <sup class="c" data-ref="Evans2021SSC,Jansen2010Lactate,Jones2010LactateClearance,Hernandez2019ANDROMEDA" title="Source 134,191,215,219"><a href="/sepsis-and-shock/sources/#src-Evans2021SSC">134,191,215,219</a></sup>`,
  pt:`Teams may repeat the lactate test to see how the body responds to treatment. Trials have also tried steering treatment by how fast colour returns after a fingertip is pressed.`,
  hook:`LACTATE trial target: a ≥20% fall every 2 h for the first 8 h. Jones 2010: ≥10% clearance. <sup class="c" data-ref="Jansen2010Lactate,Jones2010LactateClearance" title="Source 215,219"><a href="/sepsis-and-shock/sources/#src-Jansen2010Lactate">215,219</a></sup>`}
];
const TS_CAP=[
 ['Schematic muscle cell: glucose → pyruvate → burned with oxygen','Only a little pyruvate becomes lactate','Blood lactate stays low'],
 ['Blood flow falls: less oxygen reaches the cell','More pyruvate becomes lactate (anaerobic glycolysis)','ESICM: lactate typically >2 mmol/L in shock'],
 ['Oxygen is back, but adrenaline drives the Na⁺/K⁺ pump','Muscle makes lactate aerobically: 1.98 mmol/L above arterial','So a high lactate is not proof of oxygen debt']];
const TS_SHAP=[['0–2.5 mmol/L',4.9,'43 of 877'],['2.5–4.0',9.0,'24 of 267'],['4.0 or more',28.4,'38 of 134']];
const TS_CLR=[[0,5.5],[2,4.2],[4,3.1],[6,2.4],[8,1.8]];
const TS_CLRf=monoFn(TS_CLR);
const TS_BANDS=[{from:0,to:2,col:'var(--good)',label:'≤2'},{from:2,to:4,col:'var(--warn)',label:'>2'},{from:4,to:10,col:'var(--bad)',label:'≥4'}];
function tsState(t){const o2=1-.75*ramp(t,.2,.32)+.75*ramp(t,.4,.47),adr=ramp(t,.42,.52)*(1-.6*ramp(t,.84,.98));
  return {o2,adr,lf:clamp(.12+(1-o2)*.7+adr*.4,0,.85)}}
function tsLac(t,p,lp){if(p<=2)return 1+3.6*ease(ramp(t,.22,.36))-1*ease(ramp(t,.42,.54));
  if(p===3){const v=[1.5,3.2,5.5],k=lp*3,i=Math.min(2,Math.floor(k)),fr=k-i;return lerp(i?v[i-1]:3.6,v[i],ease(clamp(fr*3)))}
  return TS_CLRf(clamp(lp*1.15)*8)}
/* the schematic cell: capillary on top, cell in the middle, blood strip below */
function tsCell(P,S,t,lac,N){const X=f=>P.x+P.w*f,cy0=P.y+8,ch=34,mt=P.y+56,mb=P.y+P.h-42;
  let s=`<rect x="${P.x}" y="${cy0}" width="${P.w}" height="${ch}" rx="15" style="fill:var(--blood-soft);stroke:var(--wall);stroke-width:2"/>`;
  const nrc=Math.round(3+9*S.o2);
  for(let i=0;i<nrc;i++){const u=((t*5)+i/12)%1,x=P.x+10+u*(P.w-20),y=cy0+ch/2+Math.sin(i*2.1)*6;
    s+=`<ellipse cx="${f1(x)}" cy="${f1(y)}" rx="7" ry="4.6" style="fill:var(--deoxy)"/><ellipse cx="${f1(x)}" cy="${f1(y)}" rx="7" ry="4.6" style="fill:var(--oxy);opacity:${f1(S.o2)}"/>`}
  s+=`<text x="${P.x+8}" y="${cy0-1}" class="t-xs" style="fill:var(--ink)">capillary</text>`;
  if(S.o2<.7)s+=`<text x="${P.x+P.w-6}" y="${cy0-1}" class="t-xs t-end" style="fill:var(--bad);font-weight:700;opacity:${f1(ramp(.7-S.o2,0,.2))}">less flow, less oxygen</text>`;
  /* cell */
  s+=`<rect x="${P.x+10}" y="${mt}" width="${P.w-20}" height="${mb-mt}" rx="24" style="fill:var(--cell);stroke:var(--muted);stroke-width:1.4"/>`;
  s+=`<text x="${P.x+P.w-24}" y="${mt+16}" class="t-xs t-end">muscle cell (schematic)</text>`;
  /* blood strip */
  const by=P.y+P.h-32;s+=`<rect x="${P.x}" y="${by}" width="${P.w}" height="30" rx="10" style="fill:var(--blood-soft);opacity:.55"/><text x="${P.x+8}" y="${by+19}" class="t-xs" style="fill:var(--ink)">blood</text>`;
  const nl=Math.round(lac*3.2);for(let i=0;i<nl;i++){const u=((t*1.5)+i*.137)%1;s+=`<circle cx="${f1(P.x+46+u*(P.w-60))}" cy="${f1(by+8+((i*7)%15))}" r="2.6" style="fill:var(--lactate)"/>`}
  /* nodes and routes */
  const G0=[X(.14),cy0+ch/2],G1=[X(.14),mt],Py=[X(.36),P.y+128],Mi=[X(.7),P.y+112],L0=[X(.48),mb],L1=[X(.56),by+16];
  s+=`<path d="M${f1(G1[0])} ${f1(G1[1])}Q${f1(G1[0])} ${f1(Py[1])} ${f1(Py[0]-9)} ${f1(Py[1])}" class="arrow" marker-end="url(#tsAr)"/>`;
  s+=`<path d="M${f1(Py[0]+9)} ${f1(Py[1]-3)}L${f1(Mi[0]-P.w*.12)} ${f1(Mi[1])}" class="arrow" marker-end="url(#tsAr)" style="opacity:${f1(.35+.65*S.o2)}"/>`;
  s+=`<path d="M${f1(Py[0]+4)} ${f1(Py[1]+9)}L${f1(L0[0])} ${f1(L0[1]-2)}" class="arrow" marker-end="url(#tsAr)" style="stroke:var(--lactate);stroke-width:${f1(1.4+S.lf*3)}"/>`;
  s+=`<text x="${f1(G1[0]+6)}" y="${f1(mt+14)}" class="t-xs" style="fill:var(--ink)">glucose</text><text x="${f1(G1[0]+8)}" y="${f1(Py[1]-18)}" class="t-xs">glycolysis</text>`;
  s+=`<circle cx="${f1(Py[0])}" cy="${f1(Py[1])}" r="8" style="fill:var(--gold-soft);stroke:var(--gold);stroke-width:1.4"/><text x="${f1(Py[0])}" y="${f1(Py[1]+22)}" class="t-xs t-mid" style="fill:var(--ink)">pyruvate</text>`;
  const mrx=P.w*.12;s+=`<ellipse cx="${f1(Mi[0])}" cy="${f1(Mi[1])}" rx="${f1(mrx)}" ry="22" style="fill:var(--rx-soft);stroke:var(--rx);stroke-width:1.6;opacity:${f1(.45+.55*S.o2)}"/>`;
  let cr=`M${f1(Mi[0]-mrx*.8)} ${f1(Mi[1])}`;for(let k=1;k<=8;k++)cr+=`L${f1(Mi[0]-mrx*.8+mrx*1.6*k/8)} ${f1(Mi[1]+(k%2?-12:12))}`;
  s+=`<path d="${cr}" style="fill:none;stroke:var(--rx);stroke-width:1.2;opacity:${f1(.45+.55*S.o2)}"/><text x="${f1(Mi[0])}" y="${f1(Mi[1]+36)}" class="t-xs t-mid" style="fill:var(--rx)">${N?'uses oxygen':'mitochondrion: uses oxygen'}</text>`;
  s+=`<text x="${f1(L0[0]+8)}" y="${f1(L0[1]-12)}" class="t-xs" style="fill:var(--lactate);font-weight:700">→ lactate</text>`;
  /* oxygen diffusing to the mitochondrion */
  const no=Math.round(6*S.o2);for(let i=0;i<no;i++){const u=((t*6)+i/6)%1,a=[X(.5+.07*i),cy0+ch],x=lerp(a[0],Mi[0],u),y=lerp(a[1],Mi[1],u);
    s+=`<circle cx="${f1(x)}" cy="${f1(y)}" r="2.4" style="fill:var(--oxy);opacity:${f1(1-u*.6)}"/>`}
  if(no)s+=`<text x="${f1(X(.5)+4)}" y="${f1(cy0+ch+12)}" class="t-xs" style="fill:var(--oxy);font-weight:700">O₂</text>`;
  /* glucose → pyruvate → mitochondrion or lactate */
  const na=9+Math.round(S.adr*7);
  for(let i=0;i<na;i++){const z=(t*7)+i/16,ph=z%1,c=Math.floor(z),toL=((i*.618+c*.37)%1)<S.lf;let p,col='var(--gold)';
    if(ph<.15)p=[lerp(G0[0],G1[0],ph/.15),lerp(G0[1],G1[1],ph/.15)];
    else if(ph<.5){const u=(ph-.15)/.35;p=[lerp(G1[0],Py[0],u*u),lerp(G1[1],Py[1],Math.sqrt(u))]}
    else if(toL){col='var(--lactate)';if(ph<.8){const u=(ph-.5)/.3;p=[lerp(Py[0],L0[0],u),lerp(Py[1],L0[1],u)]}else{const u=(ph-.8)/.2;p=[lerp(L0[0],L1[0],u),lerp(L0[1],L1[1],u)]}}
    else{col='var(--rx)';const u=(ph-.5)/.4;if(u>1)continue;p=[lerp(Py[0],Mi[0],u),lerp(Py[1],Mi[1],u)]}
    s+=`<circle cx="${f1(p[0])}" cy="${f1(p[1])}" r="3.4" style="fill:${col};stroke:var(--panel);stroke-width:.8"/>`}
  /* adrenaline and the Na+/K+ pump */
  if(S.adr>.01){const Pu=[X(.84),mb],op=f1(S.adr);
    s+=`<g style="opacity:${op}"><circle cx="${f1(Pu[0])}" cy="${f1(Pu[1])}" r="10" style="fill:var(--panel);stroke:var(--accent);stroke-width:2"/>`;
    const a=t*900*S.adr*Math.PI/180;s+=`<path d="M${f1(Pu[0]+Math.cos(a)*6)} ${f1(Pu[1]+Math.sin(a)*6)}A6 6 0 1 1 ${f1(Pu[0]+Math.cos(a+4.4)*6)} ${f1(Pu[1]+Math.sin(a+4.4)*6)}" style="fill:none;stroke:var(--accent);stroke-width:1.8"/>`;
    s+=`<text x="${f1(Pu[0])}" y="${f1(Pu[1]-15)}" class="t-xs t-mid" style="fill:var(--accent);font-weight:700">Na⁺/K⁺ pump</text>`;
    s+=`<path d="M${f1(Pu[0]-12)} ${f1(Pu[1]-6)}Q${f1(X(.6))} ${f1(Py[1]+40)} ${f1(Py[0]+12)} ${f1(Py[1]+4)}" style="fill:none;stroke:var(--accent);stroke-width:1.4;stroke-dasharray:4 3" marker-end="url(#tsAr2)"/>`;
    s+=`<text x="${f1(X(.62))}" y="${f1(Py[1]+44)}" class="t-xs t-mid" style="fill:var(--accent)">faster glycolysis</text>`;
    for(let i=0;i<5;i++){const u=((t*9)+i/5)%1,x=lerp(P.x+P.w-8,Pu[0],u),y=lerp(by+18,Pu[1]+4,u),z=3.6;
      s+=`<path d="M${f1(x)} ${f1(y-z)}L${f1(x+z)} ${f1(y)}L${f1(x)} ${f1(y+z)}L${f1(x-z)} ${f1(y)}Z" style="fill:var(--accent)"/>`}
    s+=`<text x="${P.x+P.w-6}" y="${by+27}" class="t-xs t-end" style="fill:var(--accent);font-weight:700">adrenaline</text></g>`}
  return s}
inits.tests=()=>{
  /* ---- 1. why lactate rises ---- */
  const svg=$('#tsSvg'),rg=$('#tsT');
  function draw(t){const N=vb(svg,'720 400','400 470'),p=phaseOf(TS_STEPS,t),st=TS_STEPS[p],nx=p<4?TS_STEPS[p+1].from:1.0001,lp=ramp(t,st.from,nx),S=tsState(t),lac=tsLac(t,p,lp);
    const L=N?{P:{x:12,y:12,w:286,h:262},M:{x:318,y:40,w:20,h:206},K:{x:12,y:294,w:376,h:168}}:{P:{x:12,y:12,w:440,h:262},M:{x:478,y:34,w:26,h:222},K:{x:12,y:286,w:696,h:106}};
    let s=`<defs>${marker('tsAr','var(--muted)')}${marker('tsAr2','var(--accent)')}</defs>`;
    s+=`<g style="opacity:${f1(1-.5*ramp(t,.58,.62))}">`+tsCell(L.P,S,t,lac,N)+`</g>`;
    const M=L.M;s+=lactateMeter(M.x,M.y,M.w,M.h,lac,10,{bands:TS_BANDS,val:true,unit:N?'':'mmol/L',label:N?'mmol/L':'blood lactate'});
    if(!N){const Y=v=>M.y+M.h-M.h*v/10,tx=M.x+M.w+42;
      [[2,'2: Sepsis-3 shock criterion','(with a vasopressor, after fluids)'],[4,'4: Hour-1 bundle fluid trigger','(with hypotension or alone)']].forEach(([v,a,b])=>{
        s+=`<line x1="${M.x+M.w+30}" x2="${tx-2}" y1="${f1(Y(v))}" y2="${f1(Y(v))}" style="stroke:var(--line)"/><text x="${tx}" y="${f1(Y(v)+3)}" class="t-xs" style="fill:var(--ink)">${a}</text><text x="${tx}" y="${f1(Y(v)+14)}" class="t-xs">${b}</text>`});
      s+=`<text x="${tx}" y="${f1(Y(9)+3)}" class="t-xs">thresholds as published</text>`}
    const K=L.K;s+=`<rect x="${K.x}" y="${K.y}" width="${K.w}" height="${K.h}" rx="10" style="fill:var(--field);stroke:var(--line)"/>`;
    if(p<=2)TS_CAP[p].forEach((l,j)=>{s+=`<text x="${K.x+12}" y="${K.y+(N?26+j*24:24+j*26)}" class="${N?'t-xs':'t-sm'}" style="${j===0?'fill:var(--ink);font-weight:600':''}">${l}</text>`});
    else if(p===3){const bx=K.x+(N?96:130),bw=N?K.w-150:330,sel=Math.min(2,Math.floor(lp*3));
      s+=`<text x="${K.x+12}" y="${K.y+16}" class="t-xs" style="fill:var(--ink);font-weight:600">In-hospital deaths by lactate, 1,278 ED patients with infection (Shapiro 2005)</text>`;
      TS_SHAP.forEach(([lab,v,n],i)=>{const y=K.y+28+i*(N?24:22),g=ease(ramp(lp,i*.28,i*.28+.2)),on=i===sel;
        s+=`<text x="${bx-8}" y="${y+11}" class="t-xs t-end" style="${on?'fill:var(--ink);font-weight:700':''}">${lab}</text><rect x="${bx}" y="${y}" width="${bw}" height="14" rx="3" style="fill:var(--panel-2)"/>`;
        s+=`<rect x="${bx}" y="${y}" width="${f1(bw*v/40*g)}" height="14" rx="3" style="fill:${['var(--good)','var(--warn)','var(--bad)'][i]};opacity:${on?1:.6}"/>`;
        s+=`<text x="${f1(bx+bw*v/40*g+6)}" y="${y+11}" class="t-xs" style="fill:var(--ink);opacity:${f1(g)}">${v}%${N?'':' ('+n+')'}</text>`});
      const cy=N?K.y+112:K.y+30,cx=N?K.x+12:K.x+490;
      ['SSC database, 28,150 patients:','44.5% died with lactate >4 + hypotension','29% with neither (Casserly 2015)'].forEach((l,j)=>{s+=`<text x="${cx}" y="${cy+j*15}" class="t-xs" style="${j===0?'fill:var(--ink);font-weight:600':''}">${l}</text>`})}
    else{const hr=clamp(lp*1.15)*8,cx=K.x+(N?34:44),cw=N?K.w-50:380,cyy=K.y+12,chh=N?92:K.h-34;
      const C=tcurve(cx,cyy,cw,chh,TS_CLR,{x0:0,x1:8,y0:0,y1:6,upto:hr,ref:2,refLabel:'2 mmol/L',dot:true});s+=C.svg;
      let d='';[0,2,4,6,8].forEach((h,i)=>{const v=5.5*Math.pow(.8,i);d+=(i?'L':'M')+f1(C.X(h))+' '+f1(C.Y(v))});
      s+=`<path d="${d}" style="fill:none;stroke:var(--muted);stroke-width:1.4;stroke-dasharray:3 4"/>`;
      [0,2,4,6,8].forEach(h=>{s+=`<text x="${f1(C.X(h))}" y="${f1(cyy+chh+12)}" class="t-xs t-mid">${h} h</text>`});
      [0,2,4,6].forEach(v=>{s+=`<text x="${cx-4}" y="${f1(C.Y(v)+3)}" class="t-xs t-end">${v}</text>`});
      const tx=N?K.x+12:K.x+446,ty=N?K.y+128:K.y+24;
      (N?['solid: an illustrative patient · dashed: 20% fall every 2 h','LACTATE trial target; ≥10% clearance in Jones 2010']
        :['solid: an illustrative patient','dashed: a 20% fall every 2 h,','the LACTATE trial target for 8 h','Jones 2010: ≥10% clearance target','ANDROMEDA-SHOCK: capillary refill vs lactate']).forEach((l,j)=>{s+=`<text x="${tx}" y="${ty+j*(N?14:15)}" class="t-xs" style="${j===0?'fill:var(--ink)':''}">${l}</text>`})}
    svg.innerHTML=s;setSt(p);
    $('#tsRead').innerHTML=`<span>step <b>${p+1} of 5</b></span><span>lactate shown <b>${lac.toFixed(1)} mmol/L</b></span><span>oxygen supply <b>${S.o2>.8?'normal':'reduced'}</b></span><span>adrenaline <b>${S.adr>.3?'high':'low'}</b></span>`;
    $('#tsNote').innerHTML=noteHTML(st)}
  const stop=playWire(rg,$('#tsPlay'),draw,30000,'Replay','tests');
  const setSt=stepWire($('#tsSteps'),TS_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---- 2. lactate thresholds explainer ---- */
  const ls=$('#tlSvg'),lv=$('#tlV'),lc=$('#tlVaso');
  function drawL(){const v=+lv.value,N=vb(ls,'720 170','400 236'),x0=N?20:150,x1=N?380:700,X=u=>x0+(x1-x0)*clamp(u/10),y1=N?62:56,y2=N?168:122,vs=lc.checked;
    $('#tlOut').textContent=v.toFixed(1);
    let s='';
    if(!N){s+=`<text x="12" y="${y1+4}" class="t-xs" style="fill:var(--ink);font-weight:600">Published thresholds</text><text x="12" y="${y2+4}" class="t-xs" style="fill:var(--ink);font-weight:600">Shapiro 2005:</text><text x="12" y="${y2+16}" class="t-xs">in-hospital deaths</text>`}
    else{s+=`<text x="${x0}" y="14" class="t-xs" style="fill:var(--ink);font-weight:600">Published thresholds</text><text x="${x0}" y="${y2-26}" class="t-xs" style="fill:var(--ink);font-weight:600">Shapiro 2005: in-hospital deaths</text>`}
    [[0,2,'var(--good-soft)'],[2,4,'var(--warn-soft)'],[4,10,'var(--bad-soft)']].forEach(([a,b,c])=>{s+=`<rect x="${f1(X(a))}" y="${y1-10}" width="${f1(X(b)-X(a))}" height="20" style="fill:${c}"/>`});
    for(let k=0;k<=10;k++)s+=`<line x1="${f1(X(k))}" x2="${f1(X(k))}" y1="${y1+10}" y2="${y1+14}" class="axis"/><text x="${f1(X(k))}" y="${y1+24}" class="t-xs t-mid">${k}</text>`;
    s+=`<text x="${x1}" y="${y1+36}" class="t-xs t-end">mmol/L</text>`;
    [[2,N?'2: Sepsis-3':'2: Sepsis-3 septic shock criterion'],[4,N?'4: Hour-1 fluids':'4: Hour-1 bundle fluid trigger']].forEach(([k,l],i)=>{const yy=y1-16;
      s+=`<line x1="${f1(X(k))}" x2="${f1(X(k))}" y1="${yy-8}" y2="${y1+10}" style="stroke:var(--ink);stroke-width:1.4"/><text x="${f1(i?X(k)+4:X(k)-4)}" y="${yy}" class="t-xs${i?'':' t-end'}" style="fill:var(--ink)">${l}</text>`});
    const zi=v<2.5?0:v<4?1:2;
    TS_SHAP.forEach(([lab,m],i)=>{const a=[0,2.5,4][i],b=[2.5,4,10][i],on=i===zi;
      s+=`<rect x="${f1(X(a)+1)}" y="${y2-10}" width="${f1(X(b)-X(a)-2)}" height="22" rx="4" style="fill:${['var(--good-soft)','var(--warn-soft)','var(--bad-soft)'][i]};stroke:${on?'var(--ink)':'var(--line)'};stroke-width:${on?2:1}"/>`;
      const w=X(b)-X(a);s+=`<text x="${f1((X(a)+X(b))/2)}" y="${y2+4}" class="t-xs t-mid" style="fill:var(--ink);font-weight:${on?700:500}">${w<60?m.toFixed(1)+'%':m.toFixed(1)+'% died'}</text>`});
    s+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="${y1-12}" y2="${y2+14}" style="stroke:var(--lactate);stroke-width:2.4"/><path d="M${f1(X(v)-6)} ${y2+22}L${f1(X(v)+6)} ${y2+22}L${f1(X(v))} ${y2+14}Z" style="fill:var(--lactate)"/>`;
    ls.innerHTML=s;
    const shock=v>2&&vs;
    const verdict=shock?`<div class="verdict no">Lactate above 2 mmol/L with a vasopressor needed after fluids: this matches the Sepsis-3 clinical criteria for septic shock, as published.</div>`
      :v>2?`<div class="verdict maybe">Above 2 mmol/L. On its own this does not meet the Sepsis-3 septic shock criteria, which also need a vasopressor for MAP ≥65 mm Hg after fluids.</div>`
      :`<div class="verdict yes">2 mmol/L or below: under the Sepsis-3 lactate criterion. A normal lactate does not rule sepsis out.</div>`;
    $('#tlNote').innerHTML=`<div class="kicker">Teaching result (not a diagnosis)</div><div class="big-num">${v.toFixed(1)} <span style="font-size:16px">mmol/L</span></div>${verdict}
      <p>Sepsis-3 identifies septic shock by a vasopressor requirement to keep MAP at 65 mm Hg or more <i>and</i> a serum lactate above 2 mmol/L (&gt;18 mg/dL) without hypovolaemia, a combination that carried hospital mortality above 40%. <sup class="c" data-ref="Singer2016Sepsis3" title="Source 448"><a href="/sepsis-and-shock/sources/#src-Singer2016Sepsis3">448</a></sup></p>
      <p>In Shapiro 2005 (1,278 ED patients with infection), ${['4.9% of people with a lactate of 0–2.5 mmol/L','9.0% of people with a lactate of 2.5–4.0 mmol/L','28.4% of people with a lactate of 4.0 mmol/L or more'][zi]} died in hospital. That is a figure for a group of patients, not a prediction for one person. ${zi===2?'A lactate of 4.0 or more was 36% sensitive and 92% specific for death in hospital.':''} <sup class="c" data-ref="Shapiro2005Lactate" title="Source 444"><a href="/sepsis-and-shock/sources/#src-Shapiro2005Lactate">444</a></sup></p>
      ${v>=4?`<p>The 2018 Hour-1 bundle lists "rapid administration of 30 mL/kg crystalloid for hypotension or lactate ≥4 mmol/L", quoted as published. <sup class="c" data-ref="Wang2021Hour1,Levy2018Bundle" title="Source 262,508"><a href="/sepsis-and-shock/sources/#src-Wang2021Hour1">262,508</a></sup></p>`:v>2?`<p>The Hour-1 bundle says to "remeasure lactate level if initial lactate is &gt;2 mmol/L", quoted as published. <sup class="c" data-ref="Wang2021Hour1,Levy2018Bundle" title="Source 262,508"><a href="/sepsis-and-shock/sources/#src-Wang2021Hour1">262,508</a></sup></p>`:''}`}
  lv.addEventListener('input',drawL);lc.addEventListener('change',drawL);drawL();
  {const pr=redraws.tests;redraws.tests=()=>{pr&&pr();drawL()}}

  /* ---- 3. blood cultures ---- */
  const TC_STEPS=[
   {from:0,at:.12,k:'Scene 1 · how many sets',t:'Two sets, before antibiotics',
    txt:`SSC 2021 restates its 2016 best-practice statement: routine cultures, including blood, are taken before antimicrobials "if it results in no substantial delay in the start of antimicrobials (i.e. &lt; 45 min)". In adult inpatients with 3 or more cultures in 24 h, the first detected 73.1% of bloodstream infections, two 89.7%, three 98.2% and four 99.8%: two cultures in 24 h detect about 90%, and up to four may be needed for more than 99%. <sup class="c" data-ref="Evans2021SSC,Lee2007Cultures" title="Source 134,253"><a href="/sepsis-and-shock/sources/#src-Evans2021SSC">134,253</a></sup>`,
    pt:`Blood cultures are blood samples put into bottles to see whether germs grow. Taking more than one set makes it more likely that a germ is found if one is there.`,
    hook:`Two sets detect about 90% of bloodstream infections; three about 98%. <sup class="c" data-ref="Lee2007Cultures" title="Source 253"><a href="/sepsis-and-shock/sources/#src-Lee2007Cultures">253</a></sup>`},
   {from:.2,at:.32,k:'Scene 2 · antibiotics first',t:'Antibiotics lower the yield',
    txt:`In 325 ED adults with severe sepsis, blood cultures drawn before antimicrobials were positive in 31.4%. Cultures drawn a median 70 minutes after antimicrobials were positive in 19.4%, so post-antimicrobial cultures were only 52.9% sensitive. SMFM 2023 also recommends cultures before antimicrobials "as long as there are no substantial delays in timely administration of antibiotics". <sup class="c" data-ref="Cheng2019Cultures,SMFM2023Sepsis" title="Source 95,452"><a href="/sepsis-and-shock/sources/#src-Cheng2019Cultures">95,452</a></sup>`,
    pt:`Antibiotics make germs harder to grow in the lab, so cultures are taken first when this can be done quickly. Antibiotics should not wait for the results.`,
    hook:`Cultures drawn after antibiotics are positive about 40% less often (31.4% → 19.4%). <sup class="c" data-ref="Cheng2019Cultures" title="Source 95"><a href="/sepsis-and-shock/sources/#src-Cheng2019Cultures">95</a></sup>`},
   {from:.4,at:.52,k:'Scene 3 · contamination',t:'A false alarm from the skin',
    txt:`Contaminated blood cultures (false positives) range from 1% to more than 10% of all results. Older guidance set ≤3% as an acceptable rate, though the evidence for that target is debated. ASM's 2024 guideline found that chlorhexidine skin preparation, diversion devices, sterile technique, phlebotomy teams and education each lowered contamination, by about 40–60% together. False positives lead to unnecessary antibiotics, higher costs and delay in finding the true cause. <sup class="c" data-ref="Sautter2024Contamination,Doern2019Contamination" title="Source 122,413"><a href="/sepsis-and-shock/sources/#src-Sautter2024Contamination">122,413</a></sup>`,
    pt:`Sometimes germs from the skin get into the bottle. The test then looks positive when there is no blood infection, which can lead to antibiotics that are not needed.`,
    hook:`Traditional acceptable contamination rate: ≤3%. <sup class="c" data-ref="Sautter2024Contamination" title="Source 413"><a href="/sepsis-and-shock/sources/#src-Sautter2024Contamination">413</a></sup>`},
   {from:.6,at:.72,k:'Scene 4 · who is likely to be bacteraemic',t:'Pre-test probability',
    txt:`In a meta-analysis of 35 studies (4,566 bacteraemic episodes), the chance of bacteraemia ranged from about 2% in cellulitis to 69% in septic shock. A temperature of 38 °C or more had a likelihood ratio of 1.9 and isolated leukocytosis below 1.7, while shaking chills were more informative (4.7). <sup class="c" data-ref="Coburn2012Bacteremia" title="Source 100"><a href="/sepsis-and-shock/sources/#src-Coburn2012Bacteremia">100</a></sup>`,
    pt:`How likely a blood infection is depends on how ill someone is. A fever alone says less than people expect.`,
    hook:`Shaking chills LR 4.7; fever ≥38 °C LR 1.9; leukocytosis LR &lt;1.7. <sup class="c" data-ref="Coburn2012Bacteremia" title="Source 100"><a href="/sepsis-and-shock/sources/#src-Coburn2012Bacteremia">100</a></sup>`},
   {from:.8,at:.9,k:'Scene 5 · naming the germ',t:'Faster identification',
    txt:`In a randomised trial of 617 patients with positive blood culture bottles, rapid multiplex PCR identified the organism 1.3 h after the Gram stain, against 22.3 h with standard processing; fewer contaminants were treated, but mortality, length of stay and cost did not differ. A meta-analysis of 31 studies linked molecular rapid testing to lower mortality only with a stewardship programme <span class="ev early">Early evidence</span>. T2 magnetic resonance testing named Candida species from whole blood in a mean 4.4 h, against 2–5 days for culture. <sup class="c" data-ref="Banerjee2015rmPCR,Timbrook2017mRDT,Mylonakis2015T2" title="Source 40,318,476"><a href="/sepsis-and-shock/sources/#src-Banerjee2015rmPCR">40,318,476</a></sup>`,
    pt:`Newer gene-based tests can name the germ in hours instead of a day or more, which helps doctors choose the right antibiotic sooner.`,
    hook:`rmPCR: organism named 1.3 h vs 22.3 h after Gram stain, but no mortality difference in the RCT. <sup class="c" data-ref="Banerjee2015rmPCR" title="Source 40"><a href="/sepsis-and-shock/sources/#src-Banerjee2015rmPCR">40</a></sup>`}];
  const TC_CAP=[
   ['Lee 2007: share of bloodstream infections found by 1, 2, 3 and 4 cultures in 24 h','SSC 2021: cultures first only if no substantial delay (< 45 min)','Bottles are schematic'],
   ['Cheng 2019, 325 ED adults with severe sepsis','Positive before antimicrobials: 31.4% · after (median 70 min): 19.4%','Each grid shows 100 people'],
   ['Contamination: 1% to more than 10% of all blood culture results','Traditional acceptable rate ≤3% (evidence debated)','Prevention bundles cut contamination by about 40–60%'],
   ['Coburn 2012: 35 studies, 4,566 bacteraemic episodes','Pre-test probability ~2% (cellulitis) to 69% (septic shock)','Likelihood ratios: above 1 raises the probability'],
   ['Banerjee 2015: 617 patients with positive bottles','Organism named 22.3 h (standard) vs 1.3 h (rapid PCR) after Gram stain','T2 for Candida: 4.4 h vs 2–5 days for culture']];
  const tsv=$('#tcSvg'),trg=$('#tcT');
  const bottle=(x,y,s,lev,o={})=>{const w=22*s,h=40*s;let g=`<rect x="${f1(x-6*s)}" y="${f1(y)}" width="${f1(12*s)}" height="${f1(6*s)}" rx="${f1(2*s)}" style="fill:${o.cap||'var(--dx)'}"/><rect x="${f1(x-4*s)}" y="${f1(y+6*s)}" width="${f1(8*s)}" height="${f1(6*s)}" style="fill:var(--panel);stroke:var(--device);stroke-width:1"/>`;
    g+=`<rect x="${f1(x-w/2)}" y="${f1(y+12*s)}" width="${f1(w)}" height="${f1(h)}" rx="${f1(5*s)}" style="fill:var(--panel);stroke:var(--device);stroke-width:1.3"/>`;
    const lh=(h-4*s)*clamp(lev);if(lh>.5)g+=`<rect x="${f1(x-w/2+2*s)}" y="${f1(y+12*s+h-2*s-lh)}" width="${f1(w-4*s)}" height="${f1(lh)}" rx="${f1(3*s)}" style="fill:${o.col||'var(--blood-soft)'};stroke:var(--clot);stroke-width:.6"/>`;
    if(o.bug)g+=bacterium(x,y+12*s+h*.65,9*s,{kind:'coccus',op:o.bug});
    if(o.label)g+=`<text x="${f1(x)}" y="${f1(y+12*s+h+12)}" class="t-xs t-mid" style="fill:var(--ink)">${o.label}</text>`;return g};
  function tcScene(p,B,lp,N){let s='';const cx=B.x+B.w/2;
    if(p===0){const n=4,gw=N?B.w/4:110,x0=N?B.x+gw/2:B.x+250,DET=[73.1,89.7,98.2,99.8];
      if(!N){s+=`<text x="${B.x+12}" y="${B.y+22}" class="t-lbl">Before antibiotics</text>`;
        s+=`<rect x="${B.x+12}" y="${B.y+40}" width="96" height="16" rx="4" style="fill:var(--dx)"/><text x="${B.x+60}" y="${B.y+52}" class="t-xs t-mid" style="fill:var(--on-brand)">cultures</text>`;
        s+=`<rect x="${B.x+112}" y="${B.y+40}" width="96" height="16" rx="4" style="fill:var(--rx)"/><text x="${B.x+160}" y="${B.y+52}" class="t-xs t-mid" style="fill:var(--on-brand)">antibiotics</text>`;
        s+=`<text x="${B.x+12}" y="${B.y+74}" class="t-xs">SSC 2021: if no substantial</text><text x="${B.x+12}" y="${B.y+86}" class="t-xs">delay (&lt; 45 min)</text>`;
        s+=ivBag(B.x+160,B.y+102,.9,{col:'var(--rx)',label:'abx',fill:1-.5*ramp(lp,.6,1),ph:lp*20,drip:lp>.6}).svg}
      for(let i=0;i<n;i++){const x=x0+i*gw,y=B.y+(N?20:26),f=ease(ramp(lp,i*.18,i*.18+.14));
        s+=bottle(x,y,N?1.1:1.4,f,{label:`${i+1} set${i?'s':''}`});
        const by=y+(N?86:110),bh=N?160:76,hv=bh*DET[i]/100*f;
        s+=`<rect x="${f1(x-14)}" y="${by}" width="28" height="${bh}" rx="3" style="fill:var(--panel-2)"/><rect x="${f1(x-14)}" y="${f1(by+bh-hv)}" width="28" height="${f1(hv)}" rx="3" style="fill:var(--dx);opacity:${i===1?1:.65}"/>`;
        s+=`<text x="${f1(x)}" y="${f1(by-4)}" class="t-xs t-mid" style="fill:var(--ink);font-weight:700;opacity:${f1(f)}">${DET[i]}%</text>`}
      s+=`<text x="${N?B.x+8:x0-60}" y="${B.y+B.h-6}" class="t-xs">bars: cumulative share of bloodstream infections detected (Lee 2007)</text>`}
    else if(p===1){const K=[31,19],labs=['drawn before antimicrobials','redrawn a median 70 min after'],sz=N?11:14,gp=N?3:4,gw=10*(sz+gp);
      for(let k=0;k<2;k++){const x=N?cx-gw/2:B.x+80+k*330,y=N?B.y+34+k*196:B.y+44,kk=Math.round(K[k]*ease(ramp(lp,.05+k*.3,.35+k*.3)));
        s+=`<text x="${x}" y="${y-22}" class="t-lbl" style="fill:${k?'var(--rx)':'var(--dx)'}">${K[k]===31?'31.4':'19.4'}% positive</text><text x="${x}" y="${y-8}" class="t-xs">${labs[k]}</text>`;
        s+=icons(x,y,{n:100,cols:10,k:kk,size:sz,gap:gp,col:k?'var(--rx)':'var(--dx)',shape:'dot'}).svg}}
    else if(p===2){const sx=N?B.x+12:B.x+20,sy=B.y+20,sw=N?B.w-24:300,sh=110;
      s+=`<rect x="${sx}" y="${sy}" width="${sw}" height="30" rx="6" style="fill:var(--skin)"/><text x="${sx+6}" y="${sy+19}" class="t-xs" style="fill:var(--ink)">skin</text>`;
      s+=`<rect x="${sx}" y="${sy+64}" width="${sw}" height="34" rx="12" style="fill:var(--blood-soft);stroke:var(--wall);stroke-width:2"/><text x="${sx+6}" y="${sy+85}" class="t-xs" style="fill:var(--ink)">vein</text>`;
      for(let i=0;i<5;i++)s+=bacterium(sx+40+i*(sw-60)/4,sy+12+(i%2)*6,11,{kind:'coccus',seed:i+3});
      const nx=sx+sw*.6,ny=ease(ramp(lp,.05,.35));s+=`<path d="M${f1(nx+60-60*ny)} ${f1(sy-14+ny*60)}l70 -46" style="stroke:var(--device);stroke-width:3;stroke-linecap:round"/><path d="M${f1(nx+60-60*ny)} ${f1(sy-14+ny*60)}l-8 7" style="stroke:var(--device);stroke-width:1.4"/>`;
      const bx=N?B.x+B.w-50:sx+sw+70,byy=N?sy+sh+6:sy+10,cont=ramp(lp,.35,.6);
      s+=bottle(bx,byy,N?1.1:1.5,.6*ramp(lp,.3,.5),{bug:cont,label:cont>.5?'false positive':'culture bottle'});
      const rx=N?B.x+12:B.x+440,rw=N?B.w-90:236,ry=N?sy+sh+40:sy+40,X=v=>rx+rw*v/12;
      s+=`<text x="${rx}" y="${ry-14}" class="t-xs" style="fill:var(--ink);font-weight:600">contamination rate (% of all results)</text>`;
      s+=`<line x1="${rx}" x2="${rx+rw}" y1="${ry+12}" y2="${ry+12}" class="axis"/>`;[0,3,6,9,12].forEach(v=>{s+=`<text x="${f1(X(v))}" y="${ry+26}" class="t-xs t-mid">${v}${v===12?'+':''}</text>`});
      const g=ease(ramp(lp,.5,.8));s+=`<rect x="${f1(X(1))}" y="${ry}" width="${f1((X(10)-X(1))*g)}" height="10" rx="3" style="fill:var(--warn);opacity:.7"/>`;
      if(g>.9)s+=`<path d="M${f1(X(10))} ${ry+5}h${f1(rw*.12)}" style="stroke:var(--warn);stroke-width:3" marker-end="url(#tcAr)"/>`;
      s+=`<line x1="${f1(X(3))}" x2="${f1(X(3))}" y1="${ry-6}" y2="${ry+16}" style="stroke:var(--good);stroke-width:2.4"/><text x="${f1(X(3))}" y="${ry+40}" class="t-xs t-mid" style="fill:var(--good);font-weight:700">≤3% target</text>`;
      s+=`<text x="${rx}" y="${ry+60}" class="t-xs">1% to more than 10% (Sautter 2024)</text>`}
    else if(p===3){const rx=N?B.x+14:B.x+40,rw=N?B.w-28:B.w-80,ry=B.y+(N?50:44),X=v=>rx+rw*v/100,g=ease(ramp(lp,.05,.4));
      s+=`<text x="${rx}" y="${ry-22}" class="t-xs" style="fill:var(--ink);font-weight:600">pre-test probability of bacteraemia</text>`;
      s+=`<rect x="${rx}" y="${ry}" width="${rw}" height="12" rx="6" style="fill:var(--panel-2)"/><rect x="${f1(X(2))}" y="${ry}" width="${f1((X(69)-X(2))*g)}" height="12" rx="6" style="fill:var(--dx);opacity:.55"/>`;
      [0,25,50,75,100].forEach(v=>{s+=`<text x="${f1(X(v))}" y="${ry+26}" class="t-xs t-mid">${v}%</text>`});
      s+=`<circle cx="${f1(X(2))}" cy="${ry+6}" r="6" style="fill:var(--dx)"/><text x="${f1(X(2))}" y="${ry-6}" class="t-xs" style="fill:var(--ink)">cellulitis ~2%</text>`;
      if(g>.95)s+=`<circle cx="${f1(X(69))}" cy="${ry+6}" r="6" style="fill:var(--bad)"/><text x="${f1(X(69))}" y="${ry-6}" class="t-xs t-mid" style="fill:var(--ink)">septic shock 69%</text>`;
      const LR=[['shaking chills',4.7,'var(--dx)'],['fever ≥38 °C',1.9,'var(--muted)'],['leukocytosis','<1.7',1.7]],lx=N?B.x+110:B.x+200,lw=N?B.w-150:360,ly=ry+(N?66:62),LX=v=>lx+lw*v/5;
      s+=`<text x="${N?B.x+14:rx}" y="${ly-10}" class="t-xs" style="fill:var(--ink);font-weight:600">likelihood ratio for bacteraemia</text>`;
      LR.forEach(([lab,v,c],i)=>{const y=ly+i*(N?28:24),num=typeof v==='number'?v:c,gg=ease(ramp(lp,.4+i*.15,.55+i*.15));
        s+=`<text x="${lx-8}" y="${y+11}" class="t-xs t-end" style="fill:var(--ink)">${lab}</text><rect x="${lx}" y="${y}" width="${f1((LX(num)-lx)*gg)}" height="14" rx="3" style="fill:${typeof v==='number'?c:'var(--muted)'};opacity:.8"/><text x="${f1(lx+(LX(num)-lx)*gg+5)}" y="${y+11}" class="t-xs" style="opacity:${f1(gg)}">${v}</text>`});
      s+=`<line x1="${f1(LX(1))}" x2="${f1(LX(1))}" y1="${ly-4}" y2="${ly+(N?82:72)}" style="stroke:var(--ink);stroke-dasharray:3 3"/><text x="${f1(LX(1))}" y="${ly+(N?94:84)}" class="t-xs t-mid">1 = no change</text>`}
    else{const ax=N?B.x+14:B.x+150,aw=N?B.w-28:B.w-200,ay=B.y+(N?150:150),X=v=>ax+aw*v/24,g=ease(ramp(lp,.05,.6));
      const A=tline(ax,ay,aw,{min:0,max:24,step:N?6:4,fmt:v=>v+' h',label:'hours after the Gram stain'});s+=A.svg;
      const rows=[['standard processing',22.3,'var(--muted)'],['rapid multiplex PCR',1.3,'var(--rx)']];
      rows.forEach(([lab,v,c],i)=>{const y=B.y+(N?40:46)+i*(N?50:44),w=X(Math.min(v,22.3*g))-ax;
        s+=`<text x="${N?ax:ax-10}" y="${N?y-6:y+12}" class="t-xs${N?'':' t-end'}" style="fill:var(--ink);font-weight:600">${lab}</text><rect x="${ax}" y="${y}" width="${f1(Math.max(2,w))}" height="16" rx="4" style="fill:${c};opacity:.8"/><text x="${f1(ax+w+6)}" y="${y+12}" class="t-xs" style="fill:var(--ink);font-weight:700">${f1(Math.min(v,22.3*g))} h</text>`});
      const ty=ay+(N?44:34);s+=`<text x="${N?ax:ax}" y="${ty}" class="t-xs">T2 for Candida from whole blood: species in a mean 4.4 h (culture: 2–5 days)</text>`;
      if(!N)s+=`<text x="${ax}" y="${ty+14}" class="t-xs">Benefit on mortality only with stewardship in a meta-analysis (Early evidence)</text>`}
    return s}
  function drawC(t){const N=vb(tsv,'720 330','400 560'),p=phaseOf(TC_STEPS,t),st=TC_STEPS[p],nx=p<4?TC_STEPS[p+1].from:1.0001,lp=ramp(t,st.from,nx);
    const B=N?{x:12,y:12,w:376,h:384}:{x:12,y:12,w:696,h:228},K=N?{x:12,y:406,w:376,h:144}:{x:12,y:248,w:696,h:74};
    let s=`<defs>${marker('tcAr','var(--warn)')}</defs><rect x="${B.x}" y="${B.y}" width="${B.w}" height="${B.h}" rx="12" style="fill:var(--panel);stroke:var(--line)"/>`;
    s+=`<g style="opacity:${f1(.25+.75*ramp(lp,0,.08))}">${tcScene(p,B,lp,N)}</g>`;
    s+=`<rect x="${K.x}" y="${K.y}" width="${K.w}" height="${K.h}" rx="10" style="fill:var(--field);stroke:var(--line)"/>`;
    TC_CAP[p].forEach((l,j)=>{if(N){const w=tsWrap(l,62);w.forEach((ll,q)=>{s+=`<text x="${K.x+12}" y="${K.y+22+j*42+q*14}" class="t-xs" style="${j===0?'fill:var(--ink);font-weight:600':''}">${ll}</text>`})}
      else s+=`<text x="${K.x+12}" y="${K.y+20+j*20}" class="t-sm" style="${j===0?'fill:var(--ink);font-weight:600':''}">${l}</text>`});
    tsv.innerHTML=s;setC(p);$('#tcNote').innerHTML=noteHTML(st)}
  const stopC=playWire(trg,$('#tcPlay'),drawC,30000,'Replay','tests');
  const setC=stepWire($('#tcSteps'),TC_STEPS,trg,drawC,stopC);
  drawC(+trg.value);

  /* ---- 4. procalcitonin stop rule ---- */
  const TP=[[0,4],[1,12],[2,9.5],[3,6],[4,3.4],[5,2],[6,1.2],[7,.75],[8,.5],[9,.34],[10,.25]];
  const tpf=monoFn(TP),tp=$('#tpSvg'),trp=$('#tpT');
  let tpStop=-1;for(let d=0;d<=10;d+=.01){let pk=0;for(let e=0;e<=d+1e-9;e+=.01)pk=Math.max(pk,tpf(e));const v=tpf(d);if(d>=1&&(v<=pk*.2||v<=.5)){tpStop=d;break}}
  function drawP(t){const N=vb(tp,'720 260','400 300'),day=t*10,x=N?44:60,w=N?340:420,y=16,h=N?200:196;
    const C=tcurve(x,y,w,h,TP,{x0:0,x1:10,y0:.1,y1:20,log:true,upto:day,col:'var(--dx)',dot:true,ref:.5,refLabel:'0.5 μg/L'});let s=C.svg;
    let pk=0;for(let e=0;e<=day+1e-9;e+=.02)pk=Math.max(pk,tpf(e));const v=tpf(day),fall=pk>0?1-v/pk:0,met=day>=tpStop&&tpStop>=0;
    if(day>=1){const yy=C.Y(pk*.2);s+=`<line x1="${x}" x2="${x+w}" y1="${f1(yy)}" y2="${f1(yy)}" style="stroke:var(--warn);stroke-width:1.3;stroke-dasharray:5 4"/><text x="${x+w-4}" y="${f1(yy-5)}" class="t-xs t-end" style="fill:var(--warn)">80% below peak</text>`}
    [.1,.5,1,2,5,10,20].forEach(q=>{s+=`<text x="${x-5}" y="${f1(C.Y(q)+3)}" class="t-xs t-end">${q}</text>`});
    for(let d=0;d<=10;d+=2)s+=`<text x="${f1(C.X(d))}" y="${y+h+13}" class="t-xs t-mid">day ${d}</text>`;
    s+=`<text x="${x}" y="${y-4}" class="t-xs" style="fill:var(--ink)">PCT (μg/L, log scale)</text>`;
    if(tpStop>=0){const sx=C.X(tpStop);s+=`<line x1="${f1(sx)}" x2="${f1(sx)}" y1="${y}" y2="${y+h}" style="stroke:var(--good);stroke-width:1.6;opacity:${met?1:.35}"/><text x="${f1(sx+4)}" y="${y+12}" class="t-xs" style="fill:var(--good);font-weight:700;opacity:${met?1:.5}">stop rule met</text>`}
    if(!N){const tx=x+w+20;['Illustrative patient','peak to date: '+pk.toFixed(1)+' μg/L','now: '+v.toFixed(2)+' μg/L','fall from peak: '+Math.round(fall*100)+'%'].forEach((l,j)=>{s+=`<text x="${tx}" y="${y+30+j*18}" class="${j?'t-sm':'t-lbl'}" style="${j?'':'fill:var(--dx)'}">${l}</text>`});
      s+=`<text x="${tx}" y="${y+120}" class="t-lbl" style="fill:${met?'var(--good)':'var(--muted)'}">${met?'SAPS stop rule met':'not yet met'}</text>`}
    tp.innerHTML=s;
    $('#tpRead').innerHTML=`<span>day <b>${day.toFixed(1)}</b></span><span>PCT <b>${v.toFixed(2)} μg/L</b></span><span>fall from peak <b>${Math.round(fall*100)}%</b></span><span>stop rule <b>${met?'met':'not met'}</b></span>`;
    $('#tpNote').innerHTML=`<div class="kicker">Teaching example (not care advice)</div><h4>${met?'The published stop rule is met':'The published stop rule is not met yet'}</h4>
      <p>In SAPS (1,546 ICU patients, 15 Dutch hospitals) the PCT stop rule was a fall of 80% or more from peak, or a level of 0.5 μg/L or lower. Median antibiotic duration was 5 days with PCT guidance and 7 with standard care, and 28-day mortality was 20% against 25%. <sup class="c" data-ref="deJong2016SAPS" title="Source 114"><a href="/sepsis-and-shock/sources/#src-deJong2016SAPS">114</a></sup></p>
      <p>SSC 2021 suggests using procalcitonin <i>and</i> clinical evaluation to decide when to stop, where source control is adequate and the right duration is unclear, and suggests against using it to decide when to start. <sup class="c" data-ref="Evans2021SSC" title="Source 134"><a href="/sepsis-and-shock/sources/#src-Evans2021SSC">134</a></sup></p>
      <div class="pt"><b>In plain words</b>Procalcitonin is a blood test that can help doctors decide when it may be safe to stop antibiotics. It is always read together with how the person is doing. <sup class="c" data-ref="deJong2016SAPS,Evans2021SSC" title="Source 114,134"><a href="/sepsis-and-shock/sources/#src-deJong2016SAPS">114,134</a></sup></div>`}
  playWire(trp,$('#tpPlay'),drawP,14000,'Replay','tests');
  drawP(+trp.value);
};
function tsWrap(s,n){const w=s.split(' '),L=[];let c='';w.forEach(x=>{if((c+' '+x).trim().length>n){L.push(c.trim());c=x}else c+=' '+x});if(c.trim())L.push(c.trim());return L}
/* =============== 4.1 The first hour: bundle & antibiotics =============== */
/* the five Hour-1 elements; m = the schematic minute each one starts on the clock (illustrative, not a standard) */
const FH_EL=[
 {m:8,n:'Lactate',q:'"measure lactate level and remeasure lactate level if initial lactate is >2 mmol/L"'},
 {m:15,n:'Cultures',q:'"obtain blood cultures before administering antibiotics"'},
 {m:24,n:'Antibiotics',q:'"administer broad-spectrum antibiotics"'},
 {m:31,n:'Fluids',q:'"begin rapid administration of 30 mL/kg crystalloid for hypotension or lactate ≥4 mmol/L"'},
 {m:44,n:'Pressor',q:'"apply vasopressor if hypotension is present during or after fluid resuscitation to maintain a mean arterial pressure ≥65 mmHg"'}];
const FH_STEPS=[
 {from:0,at:.03,k:'Minute 0 · time zero',t:'Sepsis is recognised',
  txt:`SSC 2021: "Sepsis and septic shock are medical emergencies, and we recommend that treatment and resuscitation begin immediately" (best practice statement). The SSC 2018 bundle update introduced the "Hour-1 bundle", whose five elements are meant to be started within the first hour. The 2018 paper is paywalled, so its wording here comes from a verbatim listing in an open-access compliance study. <sup class="c" data-ref="Evans2021SSC,Levy2018Bundle,Wang2021Hour1" title="Source 134,262,508"><a href="/sepsis-and-shock/sources/#src-Evans2021SSC">134,262,508</a></sup>`,
  pt:`Sepsis is an emergency. Once a hospital team suspects it, they start several things at once, as quickly as they can.`,
  hook:`Hour-1 bundle: lactate (remeasure if >2), blood cultures before antibiotics, broad-spectrum antibiotics, 30 mL/kg crystalloid for hypotension or lactate ≥4, vasopressors for MAP ≥65. <sup class="c" data-ref="Wang2021Hour1,Levy2018Bundle" title="Source 262,508"><a href="/sepsis-and-shock/sources/#src-Wang2021Hour1">262,508</a></sup>`},
 {from:.1,at:.2,k:'Element 1 · lactate',t:'Measure lactate',
  txt:`As published, the bundle's first element is to ${FH_EL[0].q}. SSC 2021 suggests measuring blood lactate in adults suspected of having sepsis (weak, low quality), as an adjunct: lactate alone cannot rule sepsis in or out. A missed 3- or 6-hour lactate was the commonest reason for failing the US SEP-1 measure (40% of failures). <sup class="c" data-ref="Wang2021Hour1,Levy2018Bundle,Evans2021SSC,Rhee2018SEP1" title="Source 134,262,390,508"><a href="/sepsis-and-shock/sources/#src-Wang2021Hour1">134,262,390,508</a></sup>`,
  pt:`A blood test for lactate gives the team a sense of how stressed the body is, and it is often repeated.`,
  hook:`Remeasure lactate if the first value is above 2 mmol/L. <button class="btn ghost" data-go="tests">Lactate →</button>`},
 {from:.217,at:.31,k:'Element 2 · cultures',t:'Blood cultures before antibiotics',
  txt:`The bundle says to ${FH_EL[1].q}. SSC 2021 frames this as taking cultures first only "if it results in no substantial delay in the start of antimicrobials (i.e. &lt; 45 min)". Cultures drawn after antimicrobials were positive in 19.4% of patients, against 31.4% before. <sup class="c" data-ref="Wang2021Hour1,Levy2018Bundle,Evans2021SSC,Cheng2019Cultures" title="Source 95,134,262,508"><a href="/sepsis-and-shock/sources/#src-Wang2021Hour1">95,134,262,508</a></sup>`,
  pt:`Blood samples are taken to grow the germ, ideally before antibiotics. Antibiotics should not wait long for them.`},
 {from:.367,at:.46,k:'Element 3 · antibiotics',t:'Broad-spectrum antibiotics',
  txt:`The bundle says to ${FH_EL[2].q}. SSC 2021 recommends antimicrobials "immediately, ideally within 1 h of recognition" for possible septic shock or a high likelihood of sepsis (strong), and suggests rapid investigation with antimicrobials within 3 h if concern persists for possible sepsis without shock (weak). Choosing the right drug matters too: survival in septic shock was 52.0% after appropriate and 10.3% after inappropriate initial therapy (Kumar 2009). <sup class="c" data-ref="Wang2021Hour1,Levy2018Bundle,Evans2021SSC,Kumar2009Inappropriate" title="Source 134,242,262,508"><a href="/sepsis-and-shock/sources/#src-Wang2021Hour1">134,242,262,508</a></sup>`,
  pt:`Antibiotics are started quickly, through a drip. When shock is possible, guidelines say to give them within an hour.`,
  hook:`SSC 2021: ≤1 h for possible shock or high likelihood of sepsis; ≤3 h after rapid assessment for possible sepsis without shock. <sup class="c" data-ref="Evans2021SSC" title="Source 134"><a href="/sepsis-and-shock/sources/#src-Evans2021SSC">134</a></sup>`},
 {from:.483,at:.6,k:'Element 4 · fluids',t:'Crystalloid for hypotension or high lactate',
  txt:`The bundle says to ${FH_EL[3].q}. SSC 2021 suggests at least 30 mL/kg of IV crystalloid within the first 3 h for sepsis-induced hypoperfusion or septic shock (weak, low quality), based on observational evidence. In the New York cohort, time to completing the fluid bolus was not associated with mortality (OR 1.01 per hour). SMFM 2023 recommends 1 to 2 L in pregnancy. <sup class="c" data-ref="Wang2021Hour1,Levy2018Bundle,Evans2021SSC,Seymour2017Timing,SMFM2023Sepsis" title="Source 134,262,436,452,508"><a href="/sepsis-and-shock/sources/#src-Wang2021Hour1">134,262,436,452,508</a></sup>`,
  pt:`A drip of salt-based fluid is given to help raise blood pressure and blood flow. How much depends on the person.`,
  hook:`30 mL/kg is a weak SSC 2021 suggestion on observational evidence. <button class="btn ghost" data-go="fluids">Fluids →</button>`},
 {from:.7,at:.85,k:'Element 5 · vasopressor',t:'A vasopressor for MAP ≥65',
  txt:`The bundle says to ${FH_EL[4].q}. SSC 2021 recommends an initial MAP target of 65 mm Hg over higher targets (strong, moderate quality) and suggests starting vasopressors peripherally rather than waiting for central access, for a short time and in a vein at or above the antecubital fossa (weak, very low quality). It suggests ICU admission within 6 h for those who need it. <sup class="c" data-ref="Wang2021Hour1,Levy2018Bundle,Evans2021SSC" title="Source 134,262,508"><a href="/sepsis-and-shock/sources/#src-Wang2021Hour1">134,262,508</a></sup>`,
  pt:`If blood pressure stays low after fluids, a medicine that tightens blood vessels is given by a pump.`,
  hook:`MAP target 65 mm Hg (strong). <button class="btn ghost" data-go="pressors">Vasopressors →</button>`}];
const FA_SER=[{k:'Kumar 2006',or:1.119,col:'var(--bad)',d:'septic shock, from hypotension'},{k:'Peltan 2019',or:1.10,col:'var(--accent)',d:'1-year deaths, from ED arrival'},{k:'Liu 2017',or:1.09,col:'var(--warn)',d:'from ED registration'},{k:'Seymour 2017',or:1.04,col:'var(--rx)',d:'New York, to antibiotics'}];
const FA_LIU=[['sepsis',.3],['severe sepsis',.4],['shock',1.8]];
const FE_T=[
 {n:'Rivers 2001',d:'263 patients, 1 centre · in-hospital',b:[['EGDT',30.5],['standard therapy',46.5]]},
 {n:'ProCESS 2014',d:'1,341 patients, 31 US EDs · 60-day',b:[['EGDT',21.0],['protocol standard',18.2],['usual care',18.9]]},
 {n:'ARISE 2014',d:'1,600 patients, 51 centres · 90-day',b:[['EGDT',18.6],['usual care',18.8]]},
 {n:'ProMISe 2015',d:'1,260 patients, 56 English hospitals · 90-day',b:[['EGDT',29.5],['usual care',29.2]]},
 {n:'PRISM 2017',d:'3,723 patients pooled · 90-day',b:[['EGDT',24.9],['usual care',25.4]]}];
const FE_STEPS=[
 {from:0,at:.14,k:'2001 · one centre',t:'Rivers: a big effect',
  txt:`Rivers 2001 randomised 263 ED patients with severe sepsis or septic shock at one centre to 6 hours of early goal-directed therapy (EGDT) or standard therapy. In-hospital mortality was 30.5% with EGDT and 46.5% with standard therapy (P = 0.009). <sup class="c" data-ref="Rivers2001EGDT" title="Source 396"><a href="/sepsis-and-shock/sources/#src-Rivers2001EGDT">396</a></sup>`,
  pt:`An early single-hospital trial suggested that a strict treatment protocol in the first hours saved many lives.`},
 {from:.2,at:.34,k:'2014 · United States',t:'ProCESS: no benefit',
  txt:`ProCESS (1,341 patients, 31 US EDs) found 60-day in-hospital mortality of 21.0% with protocol EGDT, 18.2% with protocol standard therapy and 18.9% with usual care (RR protocol vs usual 1.04, 0.82–1.31). <sup class="c" data-ref="ProCESS2014" title="Source 369"><a href="/sepsis-and-shock/sources/#src-ProCESS2014">369</a></sup>`,
  pt:`A much larger trial found that following the strict protocol did not do better than good usual care.`},
 {from:.4,at:.54,k:'2014 · Australasia',t:'ARISE: no benefit',
  txt:`ARISE (1,600 patients, 51 centres, mainly Australia and New Zealand) found 90-day mortality of 18.6% with EGDT and 18.8% with usual care (difference −0.3 percentage points, −4.1 to 3.6). <sup class="c" data-ref="ARISE2014" title="Source 29"><a href="/sepsis-and-shock/sources/#src-ARISE2014">29</a></sup>`},
 {from:.6,at:.74,k:'2015 · England',t:'ProMISe: no benefit, more cost',
  txt:`ProMISe (1,260 patients, 56 English hospitals) found 90-day mortality of 29.5% with EGDT and 29.2% with usual care (RR 1.01, 0.85–1.20). EGDT raised costs, and the probability that it was cost-effective was below 20%. <sup class="c" data-ref="Mouncey2015ProMISe" title="Source 310"><a href="/sepsis-and-shock/sources/#src-Mouncey2015ProMISe">310</a></sup>`},
 {from:.8,at:.92,k:'2017 · pooled',t:'PRISM: the verdict',
  txt:`PRISM pooled individual data from 3,723 patients at 138 hospitals in ProCESS, ARISE and ProMISe. 90-day mortality was 24.9% with EGDT and 25.4% with usual care (adjusted OR 0.97, 0.82–1.14); EGDT increased ICU use and costs, with no benefit even in subgroups with worse shock (higher lactate, or hypotension plus hyperlactataemia). <sup class="c" data-ref="PRISM2017" title="Source 368"><a href="/sepsis-and-shock/sources/#src-PRISM2017">368</a></sup>`,
  pt:`When the three big trials were combined, the strict protocol still did not save more lives. Early recognition, antibiotics and fluids remain the core of care.`,
  hook:`Rivers 2001 EGDT cut mortality from 46.5% to 30.5%; ProCESS, ARISE, ProMISe and PRISM found no benefit over usual care. <sup class="c" data-ref="Rivers2001EGDT,PRISM2017" title="Source 368,396"><a href="/sepsis-and-shock/sources/#src-Rivers2001EGDT">368,396</a></sup>`}];
function fhBottle(x,y,s,lev){const w=20*s,h=34*s;let g=`<rect x="${f1(x-5*s)}" y="${f1(y)}" width="${f1(10*s)}" height="${f1(5*s)}" rx="${f1(2*s)}" style="fill:var(--dx)"/><rect x="${f1(x-w/2)}" y="${f1(y+8*s)}" width="${f1(w)}" height="${f1(h)}" rx="${f1(4*s)}" style="fill:var(--panel);stroke:var(--device);stroke-width:1.2"/>`;
  const lh=(h-4*s)*clamp(lev);if(lh>.5)g+=`<rect x="${f1(x-w/2+2*s)}" y="${f1(y+8*s+h-2*s-lh)}" width="${f1(w-4*s)}" height="${f1(lh)}" rx="${f1(3*s)}" style="fill:var(--blood-soft);stroke:var(--clot);stroke-width:.6"/>`;return g}
function fhWrap(s,n){const w=s.split(' '),L=[];let c='';w.forEach(x=>{if((c+' '+x).trim().length>n){L.push(c.trim());c=x}else c+=' '+x});if(c.trim())L.push(c.trim());return L}
inits.firsthour=()=>{
  /* ---- 1. the Hour-1 clock ---- */
  const svg=$('#fhSvg'),rg=$('#fhT');
  function tile(k,B,min,N){const E=FH_EL[k],e=ramp(min,E.m,E.m+5),run=ramp(min,E.m,60),on=e>0,cx=B.x+B.w/2;
    let s=`<rect x="${f1(B.x)}" y="${f1(B.y)}" width="${f1(B.w)}" height="${f1(B.h)}" rx="10" style="fill:${on?'var(--rx-soft)':'var(--panel)'};stroke:${on?'var(--rx)':'var(--line)'};stroke-width:${on?1.6:1}"/>`;
    s+=`<text x="${f1(B.x+8)}" y="${f1(B.y+16)}" class="t-lbl" style="font-size:11.5px;fill:${on?'var(--rx)':'var(--muted)'}">${k+1} · ${E.n}</text>`;
    s+=`<g style="opacity:${f1(.35+.65*e)}">`;const iy=B.y+26,ih=B.h-52;
    if(k===0){const v=4.4*e;s+=lactateMeter(cx-8,iy+14,16,ih-34,v,10,{bands:[{from:0,to:2,col:'var(--good)'},{from:2,to:10,col:'var(--warn)'}],val:e>0,label:''});
      if(min>E.m+6)s+=`<text x="${f1(cx)}" y="${f1(B.y+B.h-22)}" class="t-xs t-mid" style="fill:var(--ink)">&gt;2: remeasure</text>`}
    else if(k===1){const sc=N?1.05:1.2;[0,1].forEach(j=>{s+=fhBottle(cx-15+j*30,iy+10,sc,ramp(min,E.m+j*2,E.m+4+j*2))});
      s+=`<text x="${f1(cx)}" y="${f1(iy+10+46*sc+12)}" class="t-xs t-mid" style="fill:var(--ink)">before antibiotics</text>`}
    else if(k===2)s+=ivBag(cx,iy+4,N?.8:.9,{col:'var(--rx)',label:'abx',fill:1-.6*run,ph:min*.35,drip:on,to:[cx,iy+ih-2]}).svg;
    else if(k===3){s+=ivBag(cx,iy+4,N?.8:.9,{col:'var(--fluid)',label:'fluid',fill:1-.85*run,ph:min*.5,drip:on,to:[cx,iy+ih-14]}).svg;
      s+=`<text x="${f1(cx)}" y="${f1(B.y+B.h-22)}" class="t-xs t-mid" style="fill:var(--ink)">30 mL/kg</text>`}
    else{const map=52+8*ramp(min,31,44)+16*ramp(min,44,58),pw=Math.min(B.w-16,84);
      s+=pump(cx-pw/2,iy+2,pw,34,{v:run,txt:'pressor',on}).svg;
      const gr=N?24:28,gy=B.y+B.h-28;s+=gauge(cx,gy,gr,map,120,{ticks:false,bands:[{to:65,col:'var(--warn)'},{to:120,col:'var(--good)'}]});
      const a=Math.PI*(1-65/120);s+=`<text x="${f1(cx+(gr+8)*Math.cos(a))}" y="${f1(gy-(gr+8)*Math.sin(a)+3)}" class="t-xs t-mid" style="fill:var(--ink);font-weight:700">65</text>`;
      s+=`<text x="${f1(cx)}" y="${f1(gy+12)}" class="t-xs t-mid">MAP</text>`}
    s+=`</g><text x="${f1(cx)}" y="${f1(B.y+B.h-7)}" class="t-xs t-mid" style="fill:${on?'var(--rx)':'var(--muted)'};font-weight:600">${on?'started, min '+E.m:'not yet'}</text>`;
    return s}
  function draw(t){const N=vb(svg,'720 380','400 650'),p=phaseOf(FH_STEPS,t),st=FH_STEPS[p],min=t*60;
    const C=N?{cx:200,cy:92,r:70}:{cx:112,cy:132,r:84};
    let s=clock(C.cx,C.cy,C.r,min,{full:60,col:'var(--rx)',marks:FH_EL.filter(E=>min>=E.m).map(E=>({min:E.m,col:'var(--rx)'})),label:'minutes since sepsis was recognised'});
    s+=`<text x="${C.cx}" y="${C.cy+C.r+36}" class="t-big t-mid" style="font-size:22px;fill:var(--rx)">${Math.floor(min)} min</text>`;
    const T=[];if(N){const w=(376-12)/3,h=148;for(let k=0;k<5;k++){const r=k<3?0:1,c=k<3?k:k-3;T.push({x:12+c*(w+6)+(r?(w+6)/2:0),y:212+r*(h+8),w,h})}}
    else{const w=(708-226-24)/5;for(let k=0;k<5;k++)T.push({x:226+k*(w+6),y:20,w,h:220})}
    T.forEach((B,k)=>{s+=tile(k,B,min,N)});
    const K=N?{x:12,y:530,w:376,h:110}:{x:12,y:272,w:696,h:98};
    s+=`<rect x="${K.x}" y="${K.y}" width="${K.w}" height="${K.h}" rx="10" style="fill:var(--field);stroke:var(--line)"/>`;
    const head=p===0?'SSC 2021, as published:':`Hour-1 bundle element ${p} (SSC 2018), as published:`,
      q=p===0?'"Sepsis and septic shock are medical emergencies, and we recommend that treatment and resuscitation begin immediately"':FH_EL[p-1].q;
    s+=`<text x="${K.x+12}" y="${K.y+20}" class="t-xs" style="fill:var(--rx);font-weight:700">${head}</text>`;
    fhWrap(q,N?58:96).forEach((l,j)=>{s+=`<text x="${K.x+12}" y="${K.y+40+j*(N?16:18)}" class="${N?'t-xs':'t-sm'}" style="fill:var(--ink)">${l.replace(/>/g,'&gt;')}</text>`});
    svg.innerHTML=s;setSt(p);
    const done=FH_EL.filter(E=>min>=E.m).length;
    $('#fhRead').innerHTML=`<span>minute <b>${Math.floor(min)}</b></span><span>elements started <b>${done} of 5</b></span>`;
    $('#fhNote').innerHTML=noteHTML(st)}
  const stop=playWire(rg,$('#fhPlay'),draw,26000,'Replay','firsthour');
  const setSt=stepWire($('#fhSteps'),FH_STEPS,rg,draw,stop);
  draw(+rg.value);

  /* ---- 2. time to antibiotics ---- */
  const fa=$('#faSvg'),frg=$('#faT');
  function drawA(t){const N=vb(fa,'720 320','400 540'),h=t*6,G=N?{x:44,y:20,w:336,h:250}:{x:56,y:20,w:400,h:250},X=v=>G.x+G.w*v/6,Y=v=>G.y+G.h-G.h*(v-1)/1;
    let s=`<rect x="${G.x}" y="${G.y}" width="${G.w}" height="${G.h}" style="fill:var(--field)"/>`;
    for(let v=1;v<=2.001;v+=.25)s+=`<line x1="${G.x}" x2="${G.x+G.w}" y1="${f1(Y(v))}" y2="${f1(Y(v))}" class="grid"/><text x="${G.x-5}" y="${f1(Y(v)+3)}" class="t-xs t-end">×${v.toFixed(2)}</text>`;
    for(let k=0;k<=6;k++)s+=`<text x="${f1(X(k))}" y="${G.y+G.h+13}" class="t-xs t-mid">${k} h</text>`;
    s+=`<line x1="${G.x}" x2="${G.x+G.w}" y1="${G.y+G.h}" y2="${G.y+G.h}" class="axis"/><line x1="${G.x}" x2="${G.x}" y1="${G.y}" y2="${G.y+G.h}" class="axis"/>`;
    s+=`<text x="${G.x+4}" y="${G.y+12}" class="t-xs" style="fill:var(--ink)">relative odds of death vs no delay</text><text x="${G.x+G.w}" y="${G.y+G.h+26}" class="t-xs t-end">hours of delay</text>`;
    FA_SER.forEach((S,i)=>{let d='';for(let k=0;k<=60;k++){const u=k/10;d+=(k?'L':'M')+f1(X(u))+' '+f1(Y(Math.pow(S.or,u)))}
      s+=`<path d="${d}" style="fill:none;stroke:${S.col};stroke-width:2.4;opacity:.85"/>`;
      const v=Math.pow(S.or,h);s+=`<circle cx="${f1(X(h))}" cy="${f1(Y(v))}" r="4.6" style="fill:${S.col};stroke:var(--panel);stroke-width:1.5"/>`;
      const ly=Y(Math.pow(S.or,6));s+=`<text x="${G.x+G.w-4}" y="${f1(ly+(i===2?12:-5))}" class="t-xs t-end" style="fill:${S.col};font-weight:700">${S.k} · ${S.or}/h</text>`});
    s+=`<line x1="${f1(X(h))}" x2="${f1(X(h))}" y1="${G.y}" y2="${G.y+G.h}" style="stroke:var(--ink);stroke-dasharray:3 3;opacity:.6"/>`;
    const L=N?{x:20,y:330,w:360}:{x:486,y:30,w:222},bw=N?L.w-120:L.w-90;
    s+=`<text x="${L.x}" y="${L.y}" class="t-xs" style="fill:var(--ink);font-weight:700">Liu 2017: absolute mortality</text><text x="${L.x}" y="${L.y+13}" class="t-xs" style="fill:var(--ink);font-weight:700">increase per hour of delay</text>`;
    FA_LIU.forEach(([lab,v],i)=>{const y=L.y+30+i*34;s+=`<text x="${L.x}" y="${y+10}" class="t-xs">${lab}</text><rect x="${L.x}" y="${y+14}" width="${bw}" height="12" rx="3" style="fill:var(--panel-2)"/><rect x="${L.x}" y="${y+14}" width="${f1(bw*v/2)}" height="12" rx="3" style="fill:${i===2?'var(--bad)':'var(--warn)'}"/><text x="${f1(L.x+bw*v/2+5)}" y="${y+24}" class="t-xs" style="fill:var(--ink);font-weight:700">${v}%</text>`});
    const ny=L.y+30+3*34+8;['Strongest in shock: Im 2022 found','benefit within 1 h in septic shock','(OR 0.66) but not without shock'].forEach((l,j)=>{s+=`<text x="${L.x}" y="${ny+j*13}" class="t-xs">${l}</text>`});
    fa.innerHTML=s;
    $('#faRead').innerHTML=`<span>delay <b>${h.toFixed(1)} h</b></span>`+FA_SER.map(S=>`<span>${S.k} <b>×${Math.pow(S.or,h).toFixed(2)}</b></span>`).join('');
    $('#faNote').innerHTML=`<div class="kicker">Average associations, not predictions</div><h4>${h<1?'Within the first hour':h<3?'Between 1 and 3 hours':'Beyond 3 hours'}</h4>
      <p>Kumar 2006 reported an adjusted odds ratio for death of 1.119 for each hour of delay in effective antimicrobials after hypotension began in septic shock; in New York, each hour to antibiotics carried an OR of 1.04; at Kaiser Permanente, 1.09 per hour from registration; in Utah, 10% higher odds of death at 1 year per hour from arrival. <sup class="c" data-ref="Kumar2006Delay,Seymour2017Timing,Liu2017Antibiotics,Peltan2019Door" title="Source 241,267,350,436"><a href="/sepsis-and-shock/sources/#src-Kumar2006Delay">241,267,350,436</a></sup></p>
      <p>The effect was strongest in shock: Liu 2017's absolute increase per hour was 0.3% in sepsis, 0.4% in severe sepsis and 1.8% in shock, and Im 2022 found each 1-h delay within 3 h carried a 35% higher mortality risk in septic shock, with no such trend without shock. A meta-analysis found no significant difference at the 1-h or 3-h thresholds. <sup class="c" data-ref="Liu2017Antibiotics,Im2022Antibiotics,Sterling2015Meta" title="Source 211,267,460"><a href="/sepsis-and-shock/sources/#src-Liu2017Antibiotics">211,267,460</a></sup></p>
      <div class="pt"><b>In plain words</b>In studies, each hour of delay before antibiotics was linked to worse outcomes on average, especially in septic shock. These are population figures, not predictions for one person. <sup class="c" data-ref="Liu2017Antibiotics,Im2022Antibiotics" title="Source 211,267"><a href="/sepsis-and-shock/sources/#src-Liu2017Antibiotics">211,267</a></sup></div>`}
  playWire(frg,$('#faPlay'),drawA,12000,'Replay','firsthour');
  drawA(+frg.value);

  /* ---- 3. EGDT trials ---- */
  const fe=$('#feSvg'),erg=$('#feT');
  function drawE(t){const N=vb(fe,'720 320','400 400'),p=phaseOf(FE_STEPS,t),st=FE_STEPS[p];
    const lx=N?12:12,bx=N?12:236,bw=N?300:400,X=v=>bx+bw*v/50;let s='',y=N?14:12;
    if(!N){[0,10,20,30,40,50].forEach(v=>{s+=`<line x1="${f1(X(v))}" x2="${f1(X(v))}" y1="8" y2="300" class="grid"/><text x="${f1(X(v))}" y="314" class="t-xs t-mid">${v}%</text>`})}
    FE_T.forEach((T,i)=>{const g=ease(ramp(t,FE_STEPS[i].from,FE_STEPS[i].from+.1)),on=i===p,op=t>=FE_STEPS[i].from?1:.3;
      s+=`<g style="opacity:${op}">`;
      if(N){s+=`<text x="${lx}" y="${y+10}" class="t-lbl" style="font-size:12px;fill:${on?'var(--rx)':'var(--ink)'}">${T.n}</text><text x="${lx+96}" y="${y+10}" class="t-xs">${T.d}</text>`;y+=16}
      else{s+=`<text x="${lx}" y="${y+12}" class="t-lbl" style="font-size:12.5px;fill:${on?'var(--rx)':'var(--ink)'}">${T.n}</text><text x="${lx}" y="${y+25}" class="t-xs">${T.d.split(' · ')[0]}</text><text x="${lx}" y="${y+37}" class="t-xs">${T.d.split(' · ')[1]} mortality</text>`}
      T.b.forEach(([lab,v],j)=>{const yy=y+j*16,w=bw*v/50*g;
        s+=`<rect x="${bx}" y="${yy+2}" width="${f1(w)}" height="12" rx="3" style="fill:${j===0?'var(--rx)':'var(--muted)'};opacity:${on?1:.7}"/><text x="${f1(bx+w+5)}" y="${yy+12}" class="t-xs" style="fill:var(--ink);opacity:${f1(g)}"><tspan style="font-weight:700">${v}%</tspan> ${lab}</text>`});
      const bh=N?T.b.length*16:Math.max(T.b.length*16,40);
      if(on)s+=`<rect x="${lx-6}" y="${y-(N?20:4)}" width="${N?388:708}" height="${bh+(N?24:8)}" rx="8" style="fill:none;stroke:var(--rx);stroke-width:1.2;opacity:.6"/>`;
      s+=`</g>`;y+=bh+(N?22:14)});
    if(N){[0,25,50].forEach(v=>{s+=`<text x="${f1(X(v))}" y="${y+4}" class="t-xs t-mid">${v}%</text>`})}
    fe.innerHTML=s;setE(p);$('#feNote').innerHTML=noteHTML(st)}
  const stopE=playWire(erg,$('#fePlay'),drawE,22000,'Replay','firsthour');
  const setE=stepWire($('#feSteps'),FE_STEPS,erg,drawE,stopE);
  drawE(+erg.value);
};
/* ===== 4.2 Fluids ===== */
/* Frank–Starling story: five steps. The curve shape and the dots are schematic; numbers in the notes are cited. */
const FL_SSTEPS=[
 {from:0,at:.1,k:'Step 1 · the curve',t:'Preload and stroke volume',
  txt:`Cardiac output equals stroke volume times heart rate, and depends on heart rate, contractility, preload and afterload. Preload is "the degree of myocardial distension prior to shortening". Within limits, the more the muscle is stretched, the harder it contracts: the Frank–Starling relationship <sup class="c" data-ref="Vincent2008CO" title="Source 498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">498</a></sup>. In sepsis, cardiac output is usually normal or high even when the heart muscle is depressed, because low vascular tone lowers afterload <sup class="c" data-ref="Vincent2008CO" title="Source 498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">498</a></sup>.`,
  pt:`The heart works like a spring: filling it a little more makes it push out more blood, but only up to a point.`,
  hook:`CO = SV × HR. Four determinants: heart rate, contractility, preload, afterload <sup class="c" data-ref="Vincent2008CO" title="Source 498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">498</a></sup>.`},
 {from:.18,at:.3,k:'Step 2 · the steep part',t:'Patient A: fluid helps',
  txt:`Patient A sits on the steep part. A fluid bolus stretches the heart a little more and stroke volume rises a lot: fluid raises stroke volume through the Frank–Starling mechanism, "like adding a tailwind to the cyclist" <sup class="c" data-ref="Vincent2008CO" title="Source 498"><a href="/sepsis-and-shock/sources/#src-Vincent2008CO">498</a></sup>. The ESICM consensus defines a positive response to fluid as a cardiac output rise of at least 10–15%, and recommends giving fluid as a challenge, unless hypovolaemia is obvious <sup class="c" data-ref="Cecconi2014ESICM" title="Source 85"><a href="/sepsis-and-shock/sources/#src-Cecconi2014ESICM">85</a></sup>.`,
  pt:`For some people, a drip of fluid makes the heart pump noticeably more blood. That is what doctors hope to see.`,
  hook:`Positive fluid response = cardiac output up by ≥10–15% (ESICM) <sup class="c" data-ref="Cecconi2014ESICM" title="Source 85"><a href="/sepsis-and-shock/sources/#src-Cecconi2014ESICM">85</a></sup>.`},
 {from:.38,at:.5,k:'Step 3 · the flat part',t:'Patient B: fluid adds little',
  txt:`Patient B is already on the flat part. The same bolus barely changes stroke volume, so the fluid adds volume without adding flow. Only about half of unstable patients respond to fluid: 56% in a 24-study review, and a mean of 50% (95% CI 42% to 56%) across 50 studies <sup class="c" data-ref="Marik2008CVP,Bentzer2016JAMA" title="Source 52,275"><a href="/sepsis-and-shock/sources/#src-Marik2008CVP">52,275</a></sup>. Observational studies tie a positive fluid balance to higher mortality, although sicker patients get more fluid <sup class="c" data-ref="Messmer2020CCM" title="Source 293"><a href="/sepsis-and-shock/sources/#src-Messmer2020CCM">293</a></sup>.`,
  pt:`For others, more fluid does not help the heart pump more. It can collect in the tissues and lungs instead.`,
  hook:`About 1 in 2 unstable patients is fluid-responsive <sup class="c" data-ref="Bentzer2016JAMA" title="Source 52"><a href="/sepsis-and-shock/sources/#src-Bentzer2016JAMA">52</a></sup>.`},
 {from:.58,at:.69,k:'Step 4 · a reversible test',t:'Passive leg raise',
  txt:`Back to the start, before any fluid. Raising the legs is a test that can be undone. With cardiac output measured, passive leg raising predicted fluid response with sensitivity 0.85, specificity 0.91 and an AUC of 0.95; the best threshold was a rise of ≥10 ± 2% <sup class="c" data-ref="Monnet2016PLR" title="Source 305"><a href="/sepsis-and-shock/sources/#src-Monnet2016PLR">305</a></sup>. A rise gave a positive likelihood ratio of 11, and no rise a negative LR of 0.13 <sup class="c" data-ref="Bentzer2016JAMA" title="Source 52"><a href="/sepsis-and-shock/sources/#src-Bentzer2016JAMA">52</a></sup>. Judged by pulse pressure instead of cardiac output, sensitivity fell to 0.56 <sup class="c" data-ref="Monnet2016PLR" title="Source 305"><a href="/sepsis-and-shock/sources/#src-Monnet2016PLR">305</a></sup>. SSC 2021 suggests "using dynamic measures to guide fluid resuscitation, over physical examination or static parameters alone" (weak, very low quality) <sup class="c" data-ref="Evans2021SSC" title="Source 134"><a href="/sepsis-and-shock/sources/#src-Evans2021SSC">134</a></sup>.`,
  pt:`Lifting the legs for a minute is a test. If the heart pumps more blood with the legs up, more fluid will probably help <sup class="c" data-ref="Monnet2016PLR,Bentzer2016JAMA" title="Source 52,305"><a href="/sepsis-and-shock/sources/#src-Monnet2016PLR">52,305</a></sup>.`,
  hook:`PLR with cardiac output: AUC 0.95, threshold ≥10% <sup class="c" data-ref="Monnet2016PLR" title="Source 305"><a href="/sepsis-and-shock/sources/#src-Monnet2016PLR">305</a></sup>. Physical examination was not predictive <sup class="c" data-ref="Bentzer2016JAMA" title="Source 52"><a href="/sepsis-and-shock/sources/#src-Bentzer2016JAMA">52</a></sup>.`},
 {from:.8,at:.93,k:'Step 5 · which test',t:'Why a static pressure fails',
  txt:`A single pressure reading cannot tell where a patient sits on the curve. Central venous pressure correlates poorly with blood volume (r 0.16) and does not predict response (AUC 0.56); the authors conclude it "should not be used to make clinical decisions regarding fluid management" <sup class="c" data-ref="Marik2008CVP" title="Source 275"><a href="/sepsis-and-shock/sources/#src-Marik2008CVP">275</a></sup>. In ventilated patients, pulse pressure variation reached an AUC of 0.94, valid only during controlled ventilation without spontaneous breathing <sup class="c" data-ref="Marik2009PPV" title="Source 276"><a href="/sepsis-and-shock/sources/#src-Marik2009PPV">276</a></sup>. In FRESH, PLR-guided care gave a lower 72-h balance (0.65 vs 2.02 L) and less RRT (5.1% vs 17.5%) <sup class="c" data-ref="Douglas2020FRESH" title="Source 124"><a href="/sepsis-and-shock/sources/#src-Douglas2020FRESH">124</a></sup>.`,
  pt:`A single pressure number from a central line does not tell doctors whether more fluid will help. Tests that watch how the heart responds work much better <sup class="c" data-ref="Marik2008CVP,Monnet2016PLR" title="Source 275,305"><a href="/sepsis-and-shock/sources/#src-Marik2008CVP">275,305</a></sup>.`,
  hook:`AUC: CVP 0.56, PPV 0.94, PLR 0.95 <sup class="c" data-ref="Marik2008CVP,Marik2009PPV,Monnet2016PLR" title="Source 275,276,305"><a href="/sepsis-and-shock/sources/#src-Marik2008CVP">275,276,305</a></sup>.`}
];
/* leak and balance story */
const FL_LSTEPS=[
 {from:0,at:.1,k:'Step 1 · a healthy vessel',t:'The glycocalyx lining',
  txt:`The glycocalyx is a gel-like layer lining the inside of blood vessels, about 0.5–5.0 μm thick, made of proteoglycans (syndecan-1 is the most studied), glycosaminoglycans and plasma proteins. It controls vessel permeability and tone, prevents microvascular thrombosis and regulates white-cell adhesion <sup class="c" data-ref="Uchimido2019" title="Source 485"><a href="/sepsis-and-shock/sources/#src-Uchimido2019">485</a></sup>.`,
  pt:`The inside of blood vessels has a thin, gel-like lining that helps keep fluid inside them <sup class="c" data-ref="Uchimido2019" title="Source 485"><a href="/sepsis-and-shock/sources/#src-Uchimido2019">485</a></sup>.`,
  hook:`Glycocalyx: 0.5–5.0 μm; syndecan-1 and heparan sulfate <sup class="c" data-ref="Uchimido2019" title="Source 485"><a href="/sepsis-and-shock/sources/#src-Uchimido2019">485</a></sup>.`},
 {from:.18,at:.3,k:'Step 2 · sepsis',t:'The lining sheds, the vessel leaks',
  txt:`In sepsis, metalloproteinases, heparanase and hyaluronidase shed the glycocalyx, causing leaky vessels, unregulated vasodilation and microthrombi <sup class="c" data-ref="Uchimido2019" title="Source 485"><a href="/sepsis-and-shock/sources/#src-Uchimido2019">485</a></sup>. Pro-inflammatory proteases make endothelial cells lose their tight junctions, and leaky capillaries lose protein and plasma into the tissues <sup class="c" data-ref="Hotchkiss2016NRDP" title="Source 201"><a href="/sepsis-and-shock/sources/#src-Hotchkiss2016NRDP">201</a></sup>. Vasoplegia, the failure of vessels to constrict, is classically attributed to nitric oxide, ATP-sensitive potassium channels and relative vasopressin deficiency <sup class="c" data-ref="Landry2001" title="Source 250"><a href="/sepsis-and-shock/sources/#src-Landry2001">250</a></sup>.`,
  pt:`Sepsis strips the lining away. The vessels widen and leak, so blood pressure falls <sup class="c" data-ref="Uchimido2019" title="Source 485"><a href="/sepsis-and-shock/sources/#src-Uchimido2019">485</a></sup>.`,
  hook:`Distributive shock is "relative hypovolemia": the blood volume is redistributed, not lost <sup class="c" data-ref="Standl2018" title="Source 458"><a href="/sepsis-and-shock/sources/#src-Standl2018">458</a></sup>.`},
 {from:.38,at:.5,k:'Step 3 · resuscitation',t:'Fluid goes in',
  txt:`SSC 2021 suggests "at least 30 mL/kg of intravenous (IV) crystalloid fluid" within the first 3 h for sepsis-induced hypoperfusion or septic shock (weak, low quality), and SSC 2026 keeps it (conditional, low certainty) <sup class="c" data-ref="Evans2021SSC,Prescott2026SSC" title="Source 134,367"><a href="/sepsis-and-shock/sources/#src-Evans2021SSC">134,367</a></sup>. In VASST, average fluid balance was already +4.2 L at enrolment, about 12 h after presentation <sup class="c" data-ref="Boyd2011VASST" title="Source 68"><a href="/sepsis-and-shock/sources/#src-Boyd2011VASST">68</a></sup>.`,
  pt:`Guidelines suggest a first amount of fluid based on body weight, given over the first few hours <sup class="c" data-ref="Evans2021SSC,Prescott2026SSC" title="Source 134,367"><a href="/sepsis-and-shock/sources/#src-Evans2021SSC">134,367</a></sup>.`,
  hook:`30 mL/kg in 3 h: weak recommendation, low-quality evidence <sup class="c" data-ref="Evans2021SSC" title="Source 134"><a href="/sepsis-and-shock/sources/#src-Evans2021SSC">134</a></sup>.`},
 {from:.6,at:.72,k:'Step 4 · the days after',t:'Fluid leaks, balance keeps rising',
  txt:`In VASST, cumulative balance reached +11 L by day 4, and a more positive balance at 12 h and at day 4 was associated with higher 28-day mortality; CVP above 12 mm Hg at 12 h went with the highest mortality <sup class="c" data-ref="Boyd2011VASST" title="Source 68"><a href="/sepsis-and-shock/sources/#src-Boyd2011VASST">68</a></sup>. Across 31 observational studies, mortality rose by a factor of 1.19 per litre of positive balance <sup class="c" data-ref="Messmer2020CCM" title="Source 293"><a href="/sepsis-and-shock/sources/#src-Messmer2020CCM">293</a></sup>. Over-aggressive fluid may itself worsen glycocalyx damage (Hypothesis) <sup class="c" data-ref="Uchimido2019" title="Source 485"><a href="/sepsis-and-shock/sources/#src-Uchimido2019">485</a></sup>. These are associations: sicker patients receive more fluid.`,
  pt:`Some of the fluid leaks out of the vessels into the tissues, so the body can end up holding many litres of extra fluid <sup class="c" data-ref="Boyd2011VASST" title="Source 68"><a href="/sepsis-and-shock/sources/#src-Boyd2011VASST">68</a></sup>.`,
  hook:`VASST balance: +4.2 L at 12 h, +11 L by day 4 <sup class="c" data-ref="Boyd2011VASST" title="Source 68"><a href="/sepsis-and-shock/sources/#src-Boyd2011VASST">68</a></sup>.`},
 {from:.82,at:.95,k:'Step 5 · de-resuscitation',t:'The four phases',
  txt:`A review proposes four phases of septic-shock fluid therapy: resuscitation, optimisation, stabilisation and evacuation (de-resuscitation), with fluid treated as a drug: "four D's" of drug, dosing, duration and de-escalation (a framework, not trial evidence) <sup class="c" data-ref="Malbrain2018AIC" title="Source 274"><a href="/sepsis-and-shock/sources/#src-Malbrain2018AIC">274</a></sup>. In FACTT (acute lung injury), a conservative strategy gave a mean 7-day balance of −136 mL versus +6992 mL and more ventilator-free days (14.6 vs 12.1), without more shock or dialysis <sup class="c" data-ref="Wiedemann2006FACTT" title="Source 519"><a href="/sepsis-and-shock/sources/#src-Wiedemann2006FACTT">519</a></sup>.`,
  pt:`One proposed way of thinking about it: once the person is stable, the aim shifts from giving fluid to letting the body lose the extra fluid it has stored <sup class="c" data-ref="Malbrain2018AIC" title="Source 274"><a href="/sepsis-and-shock/sources/#src-Malbrain2018AIC">274</a></sup>.`,
  hook:`Four phases (Malbrain): resuscitation, optimisation, stabilisation, evacuation <sup class="c" data-ref="Malbrain2018AIC" title="Source 274"><a href="/sepsis-and-shock/sources/#src-Malbrain2018AIC">274</a></sup>.`}
];
/* the trial rows: a = tested fluid or strategy, b = comparison, c = third arm. Values are % as published. */
